// @ts-nocheck
import type { Pathfinder2eSpellDefinition } from './models'

export const PATHFINDER_2E_SPELL_DATA_10: Pathfinder2eSpellDefinition[] = [{"id":"pf2e.spell.pain-of-ages","name":"Pain of Ages","kind":"SPELL","rank":6,"rarity":"UNCOMMON","traits":["concentrate","manipulate","spirit"],"traditions":["DIVINE"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":120},"area":{"shape":"BURST","feet":30}},"duration":{"text":"","sustained":false},"defense":{"kind":"SAVE","statistic":"WILL","basic":true},"damage":[{"id":"tWN5RfwPcNH3ncNm","formula":"8d8","damageType":"spirit","kind":"DAMAGE","applyAbilityModifier":false}],"heightening":{"kind":"INTERVAL","everyRanks":1,"damage":{"tWN5RfwPcNH3ncNm":"2d8"},"areaFeet":0},"counteraction":false,"ritual":null,"description":"You sense a spiritual resonance of deep anguish in the earth beneath your feet, the walls surrounding you, or the fragments of souls left behind in a place of calamity. You draw on this reservoir of pain and unleash its force against your enemies, dealing 8d8 spirit damage. On a critical failure, the creature is also for 1 round as it reels from the impact of so much anguish.\nHeightened (+1) The damage increases by 2d8.","source":{"provider":"PAIZO","sourceId":"HreHc5elibW9hVK8","book":"Pathfinder Lost Omens Shining Kingdoms","license":"ORC","remaster":true},"automation":{"status":"SUPPORTED","reasons":[]}},{"id":"pf2e.spell.personal-ocean","name":"Personal Ocean","kind":"SPELL","rank":6,"rarity":"COMMON","traits":["concentrate","manipulate","water"],"traditions":["ARCANE","PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"NONE"},"area":null},"duration":{"text":"1 minute","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You surround yourself in a bubble-like shroud of seawater that fills your space completely and moves with you. You can breathe, speak, and perceive normally while within your personal ocean, and you gain a swim Speed equal to your land Speed if you don't have one. The rules of aquatic combat apply to you, attacks targeting you, or attacks passing through your square. For instance, a bludgeoning or slashing melee attack targeting you would take a –2 circumstance penalty, and you can't cast fire spells or use actions with the fire trait.\n\nEach time you move, you extinguish non-magical fires in spaces you pass through and can attempt to counteract magical fires you move through. If you successfully counteract a fire larger than the spaces you moved through, you merely push it out of the spaces along your path. If you fail to counteract a given fire, you can't counteract that fire for the duration of the spell.\n\nYou can Dismiss the spell.","source":{"provider":"PAIZO","sourceId":"K2bTUhucPyhXlzjw","book":"Pathfinder Rage of Elements","license":"OGL","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.petrify","name":"Petrify","kind":"SPELL","rank":6,"rarity":"COMMON","traits":["concentrate","earth","manipulate"],"traditions":["ARCANE","PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":120},"target":"1 creature made of organic material","area":null},"duration":{"text":"varies","sustained":false},"defense":{"kind":"SAVE","statistic":"FORTITUDE","basic":false},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"The target's body slowly turns into a stone statue. The target must attempt a Fortitude save.\n\nCritical Success The target is unaffected.\n\nSuccess The target is Slowed 1 for 1 round as stone begins to form on their body.\n\nFailure The target is slowed 1 and must attempt a Fortitude save at the end of each of its turns; this ongoing save has the incapacitation trait. On a failed save, the slowed condition increases by 1 (or 2 on a critical failure) as stone growths creep across their body. A successful save reduces the slowed condition by 1. When a creature becomes fully unable to act due to the slowed condition from petrify, the spell then ends in a flash of gray light, leaving the target permanently as they become a statue. The spell also ends if the slowed condition is removed, which causes the stone to break off harmlessly.\n\nCritical Failure As failure, but the target is initially Slowed 2.","source":{"provider":"PAIZO","sourceId":"znv4ECL7ZtuiagtA","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.phantasmal-calamity","name":"Phantasmal Calamity","kind":"SPELL","rank":6,"rarity":"COMMON","traits":["concentrate","illusion","manipulate","mental"],"traditions":["ARCANE","OCCULT"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":500},"area":{"shape":"BURST","feet":30}},"duration":{"text":"","sustained":false},"defense":{"kind":"SAVE","statistic":"WILL","basic":true},"damage":[{"id":"0","formula":"11d6","damageType":"mental","kind":"DAMAGE","applyAbilityModifier":false}],"heightening":{"kind":"INTERVAL","everyRanks":1,"damage":{"0":"2d6"},"areaFeet":0},"counteraction":false,"ritual":null,"description":"A vision of apocalyptic destruction fills the mind of each creature in the area. The vision deals 11d6 mental damage (basic Will save). On a critical failure, the creature must also succeed at a reflex save or believe it's trapped (stuck in a fissure, adrift at sea, or some other fate in keeping with its vision). If it fails the second save, it's also for 1 minute. It can attempt a new Will save at the end of each of its turns, and on a success, it disbelieves the illusion and recovers from the stunned condition.\nHeightened (+1) The damage increases by 2d6.","source":{"provider":"PAIZO","sourceId":"0XP2XOxT9VSiXFDr","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"SUPPORTED","reasons":[]}},{"id":"pf2e.spell.phantom-orchestra","name":"Phantom Orchestra","kind":"SPELL","rank":6,"rarity":"COMMON","traits":["air","concentrate","manipulate","sonic"],"traditions":["ARCANE","OCCULT","PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":120},"area":{"shape":"BURST","feet":10}},"duration":{"text":"1 minute","sustained":true},"defense":{"kind":"SAVE","statistic":"FORTITUDE","basic":true},"damage":[{"id":"rYf54pXlYEcM3IGT","formula":"8d6","damageType":"sonic","kind":"DAMAGE","applyAbilityModifier":false}],"heightening":{"kind":"INTERVAL","everyRanks":1,"damage":{"rYf54pXlYEcM3IGT":"1d6"},"areaFeet":0},"counteraction":false,"ritual":null,"description":"You orchestrate an invisible ensemble of lost sounds captured inside errant breezes across the Plane of Air, and you can direct this symphony to attack foes within range. The sounds materialize and manifest as directed, appearing as silhouetted instruments and musicians that dance and bob in the wind.\n\nWhen you Cast the Spell, a captured breath of ephemeral music explodes in a great crescendo, appearing in a space you choose within range. On subsequent rounds, the first time you Sustain the Spell each round, you can move your conjured melody to a space within range (if needed) and create another explosion of music.\n\nEach explosion of sound from the phantom orchestra deals 8d6 sonic damage to all creatures in a 10-foot burst (basic Fortitude save). The phantom orchestra doesn't take up space, grant flanking, or have any other attributes a creature would.\n\nHeightened (+1) The damage increases by 1d6.","source":{"provider":"PAIZO","sourceId":"7idCEYHnPpVNL9vX","book":"Pathfinder Rage of Elements","license":"OGL","remaster":true},"automation":{"status":"SUPPORTED","reasons":[]}},{"id":"pf2e.spell.poltergeists-fury","name":"Poltergeist's Fury","kind":"SPELL","rank":6,"rarity":"COMMON","traits":["concentrate","manipulate"],"traditions":["ARCANE","OCCULT"],"casting":{"time":{"kind":"ACTIONS","actions":3}},"targeting":{"range":{"kind":"NONE"},"area":{"shape":"EMANATION","feet":20}},"duration":{"text":"1 minute","sustained":true},"defense":{"kind":"SAVE","statistic":"REFLEX","basic":true},"damage":[{"id":"5zjc1nvfsl4ahgnk","formula":"6d4","damageType":"piercing","kind":"DAMAGE","applyAbilityModifier":false}],"heightening":{"kind":"INTERVAL","everyRanks":1,"damage":{"5zjc1nvfsl4ahgnk":"1d4"},"areaFeet":0},"counteraction":false,"ritual":null,"description":"Your fury spills over in a telekinetic storm of terrifying proportions. Any loose, unattended objects of 1 Bulk or less within range are picked up and begin to orbit you at breathtaking speeds. All creatures in the area take 6d4 piercing damage with a basic Reflex save. Each time you Sustain the spell, you can increase the radius of the storm by 10 feet, to a maximum of 100 feet. The storm moves with you and provides you with lesser cover, though you can't use this cover to hide or sneak. Allies within the storm who roll a success on their Reflex save against your poltergeist's fury get a critical success instead, as you attempt to avoid hitting them.\nHeightened (+1) The damage increases by 1d4.","source":{"provider":"PAIZO","sourceId":"uhEjKSFdEhXzszh6","book":"Pathfinder Dark Archive (Remastered)","license":"ORC","remaster":true},"automation":{"status":"SUPPORTED","reasons":[]}},{"id":"pf2e.spell.primal-call","name":"Primal Call","kind":"RITUAL","rank":6,"rarity":"UNCOMMON","traits":[],"traditions":[],"casting":{"time":{"kind":"LONG","text":"1 day"},"cost":"faerie circle ingredients worth a total value of 1 gp × the spell rank × the target's level"},"targeting":{"range":{"kind":"TEXT","text":"100 miles"},"target":"1 animal, beast, fey, fungus, or plant","area":null},"duration":{"text":"see text","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":{"primaryCheck":"Nature (master)","secondaryChecks":"Crafting, Diplomacy, Survival","secondaryCasters":4},"description":"This functions as except you craft a faerie circle and call an animal, beast, fey, fungus, or plant from within 100 miles.","source":{"provider":"PAIZO","sourceId":"pZc8ZwtsyWnxUUW0","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["RANGE_NOT_STRUCTURED","NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.primal-summons","name":"Primal Summons","kind":"SPELL","rank":6,"rarity":"UNCOMMON","traits":["concentrate","druid","focus"],"traditions":[],"casting":{"time":{"kind":"FREE_ACTION"}},"targeting":{"range":{"kind":"NONE"},"area":null},"duration":{"text":"","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You enhance a summoned creature with the power of the elements. If your next action is to cast either or , choose air, earth, fire, metal, water or wood; the creature you summon gains the corresponding abilities.\n\n- Air The creature gains a fly Speed of 60 feet.\n\n- Earth The creature gains a burrow Speed of 20 feet, reduces its land Speed by 10 feet (minimum 5 feet), and gains resistance 5 to physical damage.\n\n- Fire The creature's Strikes deal 1d6 extra fire damage, and it gains resistance 10 to fire and weakness 5 to cold and water.\n\n- Metal The creature's Strikes deal 1d6 extra electricity damage, and it gains resistance 5 to electricity.\n\n- Water The creature gains a swim Speed of 60 feet, can spend 1 action after a melee attack to attempt a Shove (ignoring multiple attack penalty), and gains resistance 5 to fire.\n\n- Wood The creature gains a climb speed of 30 feet and resistance 2 to bludgeoning and piercing damage.","source":{"provider":"PAIZO","sourceId":"kwlKUxEuT8T15YW6","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.purple-worm-sting","name":"Purple Worm Sting","kind":"SPELL","rank":6,"rarity":"COMMON","traits":["concentrate","manipulate","poison"],"traditions":["ARCANE","PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"TOUCH"},"target":"1 creature","area":null},"duration":{"text":"","sustained":false},"defense":{"kind":"SAVE","statistic":"FORTITUDE","basic":false},"damage":[{"id":"0","formula":"3d6","damageType":"piercing","kind":"DAMAGE","applyAbilityModifier":false}],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You replicate the attack of a deadly purple worm. You deal 3d6 piercing damage to the touched creature and afflict it with purple worm venom. The target must attempt a Fortitude save.\n\nCritical Success The target is unaffected.\n\nSuccess The target takes 3d6 poison damage.\n\nFailure The target is afflicted with purple worm venom at stage 1.\n\nCritical Failure The target is afflicted with purple worm venom at stage 2.\n\nPurple Worm Venom (poison)\n\nLevel 11\n\nMaximum Duration 6 rounds.\n\nStage 1 3d6[poison] damage and Enfeebled 2 (1 round)\n\nStage 2 4d6[poison] damage and Enfeebled 2 (1 round)\n\nStage 3 6d6[poison] damage and Enfeebled 2 (1 round).","source":{"provider":"PAIZO","sourceId":"ayRXv0wQH00TTNZe","book":"Pathfinder Core Rulebook","license":"OGL","remaster":false},"automation":{"status":"SUPPORTED","reasons":[]}},{"id":"pf2e.spell.raise-dead","name":"Raise Dead","kind":"SPELL","rank":6,"rarity":"UNCOMMON","traits":["concentrate","healing","manipulate"],"traditions":["DIVINE"],"casting":{"time":{"kind":"LONG","text":"10 minutes"},"cost":"gemstones worth a total value of the target's level (minimum 1) × 200 gp"},"targeting":{"range":{"kind":"DISTANCE","feet":10},"target":"1 dead creature of 13th level or lower","area":null},"duration":{"text":"","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You attempt to call forth the dead creature's soul, requiring the creature's body to be present and relatively intact. The creature must have died within the past 3 days. If Pharasma has decided that the creature's time has come (at the GM's discretion), or if the creature doesn't wish to return to life, this spell automatically fails, but the cost isn't consumed in the casting.\n\nIf the spell is successful, the creature returns to life with 1 Hit Point, no spells prepared or spell slots available, no points in any pools or any other daily resources, and still with any long-term debilitations of the old body. The time spent in the Boneyard leaves the target temporarily debilitated, making it Clumsy 2, Drained 2, and Enfeebled 2 for 1 week; these conditions can't be removed or reduced by any means until the week has passed. The creature is also permanently changed by its time in the afterlife, such as a slight personality shift, a streak of white in the hair, or a strange new birthmark.\n\nHeightened (7th) The maximum level of the target increases to 15. The cost increases to the target's level (minimum 1) × 400 gp.\n\nHeightened (8th) The maximum level of the target increases to 17. The cost increases to the target's level (minimum 1) × 800 gp.\n\nHeightened (9th) The maximum level of the target increases to 19. The cost increases to the target's level (minimum 1) × 1,600 gp.\n\nHeightened (10th) The maximum level of the target increases to 21. The cost increases to the target's level (minimum 1) × 3,200 gp.","source":{"provider":"PAIZO","sourceId":"IkGYwHRLhkuoGReG","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.raise-runelord","name":"Raise Runelord","kind":"RITUAL","rank":6,"rarity":"RARE","traits":["dream","illusion","mythic"],"traditions":[],"casting":{"time":{"kind":"LONG","text":"1 day"},"cost":"gemstones worth 1,500 gp, fragments or significant items associated with the dead runelord"},"targeting":{"range":{"kind":"NONE"},"target":"1 dead runelord who is not already active as a risen runelord","area":null},"duration":{"text":"","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":{"primaryCheck":"Arcana (mythic)","secondaryChecks":"Religion, Occultism, Society","secondaryCasters":2},"description":"By drawing upon fragments of physical remains or treasured objects of a dead runelord and upon remnant energies of each runelord that live on after their deaths in the Dreamlands, this ritual creates a physical illusion of a long-dead runelord. There can only exist a limited number of risen runelords at a time, since each must be created from one of the finite number of dead runelords, although there's no limit as to how many times a risen runelord can be created to replace one who was destroyed. Risen runelords cannot be made from living or undead runelords. This leaves 32 potential risen runelords in the world at any one time as of the start of Revenge of the Runelords. This ritual creates an 11th-level risen runelord associated with the original runelord's sin, but the duration of that runelord's life depends on the ritual's result. As long as this ritual's inventor, Runelord Xanderghul, still lives, any attempt to cast this ritual by any other creature can never achieve a greater success than failure.\nCritical Success You create a risen runelord with a lifespan of decades, if not more.\n\nSuccess You create a risen runelord with a lifespan of 10 days.\n\nFailure You fail to create the risen runelord.\n\nCritical Failure You fail to create a risen runelord but also attract the attention of vengeful psychopomps who manifest in place of the risen runelord. This should be a severe encounter of a level equal to the primary caster against a mix of psychopomps, who attack at once and fight to the death.\nHeightened (7th) You can create a 14th-level risen runelord, and the cost is 3,000 gp.\n\nHeightened (8th) You can create a 16th-level risen runelord, and the cost is 5,000 gp.\n\nHeightened (9th) You can create an 18th-level risen runelord, and the cost is 10,000 gp.\n\nHeightened (10th) You can create a 20th-level risen runelord, and the cost is 20,000 gp.","source":{"provider":"PAIZO","sourceId":"fr1AGcQo7WuvLvUi","book":"Pathfinder #219: Lord of the Trinity Star","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.ravenous-darkness","name":"Ravenous Darkness","kind":"SPELL","rank":6,"rarity":"UNCOMMON","traits":["attack","concentrate","darkness","manipulate"],"traditions":["ARCANE","DIVINE","OCCULT"],"casting":{"time":{"kind":"ACTIONS","actions":3}},"targeting":{"range":{"kind":"DISTANCE","feet":120},"area":{"shape":"BURST","feet":20}},"duration":{"text":"1 minute","sustained":false},"defense":{"kind":"NONE"},"damage":[{"id":"WkCw5MJm2wVK3uRi","formula":"4d6","damageType":"bludgeoning","kind":"DAMAGE","applyAbilityModifier":false}],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You create a shroud of magical darkness that feeds on those inside it. This globe of pure darkness is identical to that created by a 4th-rank spell. Blunt, gnashing teeth made of shadows gnaw at the creatures within. Make a spell attack roll against the Fortitude DC of each creature in the area. Any creature that fails takes 4d6 bludgeoning damage as teeth attach to it. While the teeth are attached, it takes a –10-foot circumstance penalty to its Speeds and can't Step. Whenever a creature ends its turn in the area, the teeth attempt to attach to that creature if they haven't already, and they deal 1d6 bludgeoning damage to any creature they're already attached to. The shadowy teeth become unattached from any creature that leaves the area but can't otherwise be detached from a creature while that creature remains in the area. You can Dismiss the spell.","source":{"provider":"PAIZO","sourceId":"g1dDUKsIrdlpdqy9","book":"Pathfinder #186: Ghost King's Rage","license":"OGL","remaster":false},"automation":{"status":"SUPPORTED","reasons":[]}},{"id":"pf2e.spell.repulsion","name":"Repulsion","kind":"SPELL","rank":6,"rarity":"COMMON","traits":["aura","concentrate","manipulate","mental"],"traditions":["ARCANE","DIVINE","OCCULT"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"TEXT","text":"emanation up to 40-feet"},"area":null},"duration":{"text":"1 minute","sustained":false},"defense":{"kind":"SAVE","statistic":"WILL","basic":false},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You manifest an aura that prevents creatures from approaching you. When casting the spell, you can make the area any radius you choose, up to 40 feet. A creature must attempt a Will save if it's within the area when you Cast the Spell or as soon as it enters the area while the spell is in effect. Once a creature has attempted the save, it uses the same result for that casting of repulsion. Any restrictions on a creature's movement apply only if it voluntarily moves toward you. For example, if you move closer to a creature, it doesn't then need to move away.\n\nCritical Success The creature's movement is not restricted.\n\nSuccess The creature treats each square in the area as difficult terrain when moving closer to you.\n\nFailure The creature can't move closer to you within the area.","source":{"provider":"PAIZO","sourceId":"yrZA4k2VAqEP8xx7","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["RANGE_NOT_STRUCTURED","NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.revel-in-retribution","name":"Revel in Retribution","kind":"SPELL","rank":6,"rarity":"UNCOMMON","traits":["concentrate","focus","manipulate","mental","oracle"],"traditions":[],"casting":{"time":{"kind":"ACTIONS","actions":1}},"targeting":{"range":{"kind":"NONE"},"area":null},"duration":{"text":"1 minute","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"Time seems to slow for you, allowing you to strike your opponents mid-move. You gain the ability, and you immediately gain a second reaction that you can use only to use Reactive Strike. At the start of each of your subsequent turns when you regain your actions, you gain an additional reaction that can be used only to attempt a Reactive Strike.\n\nLashing out at a defenseless enemy invigorates you with the thrill of combat, granting you 5 temporary Hit Points whenever you successfully hit with a Reactive Strike. The temporary Hit Points last for the spell's duration.\nHeightened (+1) The temporary Hit Points you gain from a successful Reactive Strike increase by 1.","source":{"provider":"PAIZO","sourceId":"Eed8QBWBtpufl1iP","book":"Pathfinder Player Core 2","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.roses-thorns","name":"Rose's Thorns","kind":"SPELL","rank":6,"rarity":"UNCOMMON","traits":["concentrate","manipulate","plant"],"traditions":["PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":120},"area":{"shape":"BURST","feet":20}},"duration":{"text":"1 minute","sustained":true},"defense":{"kind":"SAVE","statistic":"REFLEX","basic":true},"damage":[{"id":"G3HdXE0YaAVaevwg","formula":"8d8","damageType":"piercing","kind":"DAMAGE","applyAbilityModifier":false}],"heightening":{"kind":"MANUAL","text":"Aprimoramento com valores especificos por rank."},"counteraction":false,"ritual":null,"description":"Rose bushes with razor-sharp thorns sprout from the ground in the area. The rose bushes deal 8d8 piercing damage to each creature that's in the area when the spell is cast or that ends its turn in the area (basic Reflex save). A creature that critically fails its saving throw also takes (ternary(gte(@item.rank,9),2,1))d8[persistent,bleed] damage and is for 1 round or until the creature Escapes (against your spell DC), whichever comes first. The area is difficult terrain and hazardous terrain. A creature that moves through the area takes (ternary(gte(@item.rank,9),8,5))[piercing] damage for every square of that area it moves into. Each time you sustain this spell, the radius of the burst increases by 5 feet.\nHeightened (9th) The initial damage increases to 12d8, the persistent bleed damage increases to 2d8, and the hazardous terrain damage increases to 8.","source":{"provider":"PAIZO","sourceId":"gBJtUhewnihlqxm7","book":"Pathfinder Lost Omens Firebrands","license":"OGL","remaster":false},"automation":{"status":"PARTIAL","reasons":["HEIGHTENING_REQUIRES_MANUAL_RESOLUTION"]}},{"id":"pf2e.spell.sacred-form","name":"Sacred Form","kind":"SPELL","rank":6,"rarity":"COMMON","traits":["concentrate","manipulate","polymorph"],"traditions":["DIVINE"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"NONE"},"area":null},"duration":{"text":"1 minute","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You focus all your divine energy and transform yourself into a battle form, similar to your normal form and of the same size as you, but wielding powerful divine armaments. While in this form, you gain the statistics and abilities listed below. You have hands in this battle form and can use manipulate actions. You can Dismiss the spell. You gain the following statistics and abilities.\n- AC = 20 + your level. Ignore your armor's check penalty and Speed reduction.\n- 10 temporary Hit Points.\n- Speed 40 feet.\n- Resistance 3 against physical damage.\n- Darkvision.\n- A special attack with a sacred armament, which is the only attack you can use. Your attack modifier with the sacred armament is +21, and your damage bonus is +8 (or +6 for a ranged attack). The damage dice for Strikes with the weapon are 3d6 bludgeoning damage plus 1d6 spirit damage. If you have a deity, you can have the weapon take the form of your deity's favored weapon and use its damage die size, damage type, and traits. If the favored weapon is a simple weapon with 1d4 or 1d6 damage die, the weapon damage dice are one size larger than normal, though the spirit damage is unchanged. You can also use your attack modifier with this favored weapon if it's higher than that given by the spell.\n- Athletics modifier of +23, unless your own is higher.\nHeightened (8th) You instead gain AC = 21 + your level, 15 temporary Hit Points, resistance 4 against physical damage, attack modifier +28, damage bonus +15 (+12 for a ranged attack), and Athletics +29. If you're Medium or smaller, your battle form is Large, and your attacks also have 10-foot reach, or 15-foot reach if you're using a favored weapon with reach.","source":{"provider":"PAIZO","sourceId":"MMCQsh12TPaDdPbV","book":"Pathfinder Player Core 2","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.scintillating-safeguard","name":"Scintillating Safeguard","kind":"SPELL","rank":6,"rarity":"COMMON","traits":["manipulate"],"traditions":["DIVINE","OCCULT","PRIMAL"],"casting":{"time":{"kind":"REACTION"}},"targeting":{"range":{"kind":"DISTANCE","feet":30},"target":"up to 5 willing creatures who would be harmed by the triggering effect","area":null},"duration":{"text":"","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"Trigger An effect would deal physical or energy damage to you or a creature in range.\nA sparkling magical barrier envelops each target, shielding them against the triggering effect. Choose one type of physical or energy damage the triggering effect deals. Each target gains resistance 10 against that damage type for the triggering effect. The resistance applies only against the initial damage, not against any persistent damage or other lingering effects.\nHeightened (+1) The resistance increases by 1.","source":{"provider":"PAIZO","sourceId":"9W2Qv0wXLg6tQg3y","book":"Pathfinder Player Core 2","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.scrying","name":"Scrying","kind":"SPELL","rank":6,"rarity":"UNCOMMON","traits":["concentrate","manipulate","scrying"],"traditions":["ARCANE","OCCULT"],"casting":{"time":{"kind":"LONG","text":"10 minutes"}},"targeting":{"range":{"kind":"TEXT","text":"planetary"},"target":"1 creature","area":null},"duration":{"text":"10 minutes","sustained":true},"defense":{"kind":"SAVE","statistic":"WILL","basic":false},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You magically spy on a creature of your choice. Scrying works like , except that the image you receive is less precise, insufficient for teleport and similar spells. Instead of creating an eye in a set location within 500 feet, you instead create an eye that manifests just above the target. You can choose a target either by name or by touching one of its possessions or a piece of its body. If you haven't met the target in person, scrying's DC is 2 lower, and if you are unaware of the target's identity (perhaps because you found an unknown creature's fang at a crime scene), the DC is instead 10 lower.\n\nThe effect of scrying depends on the target's Will save.\n\nCritical Success The spell fails and the target is temporarily immune for 1 week. The target also gains a glimpse of you and learns its rough distance and direction from you.\n\nSuccess The spell fails and the target is temporarily immune for 1 day.\n\nFailure The spell succeeds.\n\nCritical Failure The spell succeeds, and the eye follows the target if it moves, traveling up to 60 feet per round.","source":{"provider":"PAIZO","sourceId":"r784cIz17eWujtQj","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["RANGE_NOT_STRUCTURED","NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.seize-identity","name":"Seize Identity","kind":"SPELL","rank":6,"rarity":"RARE","traits":["concentrate","illusion","manipulate","mental","mythic","visual"],"traditions":["ARCANE","OCCULT"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":30},"target":"1 intelligent creature","area":null},"duration":{"text":"1 minute","sustained":true},"defense":{"kind":"SAVE","statistic":"WILL","basic":false},"damage":[{"id":"iuhh6qfveXzz88dv","formula":"4d6","damageType":"mental","kind":"DAMAGE","applyAbilityModifier":false}],"heightening":{"kind":"MANUAL","text":"Aprimoramento com valores especificos por rank."},"counteraction":false,"ritual":null,"description":"With a gleeful cackle, you seize an individual's voice and swallow it. For the duration, you look and sound like the target, and the target can't speak. The effects depend on the result of the target's Will saving throw.\nCritical Success The creature is unaffected.\n\nSuccess You take on the target's appearance, with the same effects of a 3rd-rank spell, and the target can't speak, with the same effects of a 2nd-rank spell.\n\nFailure As success, but the target also takes 4d6 mental damage from the transformation.\n\nCritical Failure As success, but the target also takes 8d6 mental damage from the transformation.\n\nThe first time each round you Sustain this spell after you cast this spell, the target ages rapidly, taking (ternary(gte(@item.rank,9),3,2))d8[void] damage (will save). On a failure, the target also becomes Enfeebled 1 or increases the value of its enfeebled condition by 1.\nHeightened (9th) The mental damage increases by 4d6, and the void damage increases by 1d8.","source":{"provider":"PAIZO","sourceId":"DOBs5ALM1titPYxe","book":"Pathfinder War of Immortals","license":"ORC","remaster":true},"automation":{"status":"PARTIAL","reasons":["HEIGHTENING_REQUIRES_MANUAL_RESOLUTION"]}},{"id":"pf2e.spell.shadow-illusion","name":"Shadow Illusion","kind":"SPELL","rank":6,"rarity":"UNCOMMON","traits":["auditory","concentrate","focus","illusion","manipulate","shadow","visual"],"traditions":[],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":500},"area":null},"duration":{"text":"","sustained":true},"defense":{"kind":"NONE"},"damage":[{"id":"0","formula":"2d8","damageType":"untyped","kind":"DAMAGE","applyAbilityModifier":false}],"heightening":{"kind":"INTERVAL","everyRanks":2,"damage":{"0":"1d8"}},"counteraction":false,"ritual":null,"description":"You create a shadowy illusion of a creature or a stationary object, but the illusion can exist only in an area of dim light or darkness. The spell ends if the illusion is ever out of an area of dim light or darkness. If the illusion is an object, it must fit within a 20-foot burst, and the creature can be of any size up to Gargantuan, filling a 20-foot-by-20-foot space.\n\nThe object or creature appears to animate naturally; it even generates the appropriate sounds and smells, and feels believable to the touch, though its coloring is always muted.\n\nIf the illusion is a creature, shadow illusion has the effects of an spell of the same rank, except it deals 3d8 damage, instead of the amount listed in illusory creature.\nHeightened (+2) The area that an illusory object can fit in increases by 10 feet.\n\nThe damage of the illusory creature's Strike increases by 1d8.","source":{"provider":"PAIZO","sourceId":"EOWh6VVcSjB3WPjX","book":"Pathfinder Advanced Player's Guide","license":"OGL","remaster":false},"automation":{"status":"SUPPORTED","reasons":[]}},{"id":"pf2e.spell.shambling-horror","name":"Shambling Horror","kind":"SPELL","rank":6,"rarity":"UNCOMMON","traits":["attack","concentrate","evil","focus","manipulate"],"traditions":[],"casting":{"time":{"kind":"ACTIONS","actions":3}},"targeting":{"range":{"kind":"TOUCH"},"target":"1 corpse of a Gargantuan or smaller creature that has a level no greater than your level -4 and has died since the last sunrise","area":null},"duration":{"text":"10 minutes","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You reanimate the corpse of a fallen creature as an undead minion under your control. The reanimated creature is an undead skeleton or zombie. Choose a skeleton or zombie stat block of the same size as the original creature and of a level no higher than the creature's original level. The shambling horror keeps Speeds it had in life, as well as melee Strikes that deal only physical damage. These attacks use the highest attack modifier from the skeleton or zombie you choose. Some of the skeleton's or zombie's abilities might not make sense for the shambling horror, and some abilities the creature had in life might not persist in undeath; the GM makes the final choice of what abilities the horror has.\n\nA shambling horror has the minion trait. You can't control more than one shambling horror at the same time-if you create a new one while one is already under your control, you must choose one to release, causing it to lose the minion trait. Shambling horrors that have been released expire when the spell duration does. After the duration expires, you can cast shambling horror again on the same corpse to animate it once more. However, after the next sunrise, you can no longer animate the corpse as a shambling horror.\n\nUndead Skeletons\n\nLevel\nSize\nCreature Name\n\n-1\nMedium\n\n0\nMedium\nWolf Skeleton\n\n1\nMedium\nSkeletal Soldier\n\n2\nMedium\n\n2\nLarge\n\n3\nLarge\n\n5\nMedium\n\n5\nMedium\nSkeletal Mage\n\n6\nLarge\nBeetle Carapace\n\n7\nHuge\n\n8\nLarge\nDrake Skeleton\n\n9\nGargantuan\n\n11\nGargantuan\n\n13\nGargantuan\nSkeletal Titan\n\nZombies\n\nLevel\nSize\nCreature Name\n\n-1\nMedium\n\n0\nMedium\nZombie Snake\n\n1\nMedium\n\n2\nMedium\nHusk Zombie\n\n2\nLarge\n\n3\nLarge\nZombie Owlbear\n\n4\nGargantuan\n\n4\nMedium\nZombie Lord\n\n5\nMedium\nWithered\n\n6\nMedium\n\n6\nHuge\n\n9\nHuge\n\n11\nHuge\nZombie Mammoth","source":{"provider":"PAIZO","sourceId":"Z82DvtSXafPmh4KV","book":"Pathfinder Book of the Dead","license":"OGL","remaster":false},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.siege-weapons-blessing","name":"Siege Weapon's Blessing","kind":"SPELL","rank":6,"rarity":"UNCOMMON","traits":["concentrate","manipulate"],"traditions":["ARCANE","DIVINE","OCCULT"],"casting":{"time":{"kind":"ACTIONS","actions":3}},"targeting":{"range":{"kind":"TOUCH"},"target":"one mounted siege weapon","area":null},"duration":{"text":"1 minute","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You trace a magic rune onto the body of a siege weapon, calling upon fate or your faith to guide the attacks your allies make with this machine. For the spell's duration, any skill checks attempted to Load the siege weapon can be rolled twice, taking the better result; these skill checks gain the fortune trait. In addition, any saving throws attempted by creatures caught in the siege weapon's Launch area must be rolled twice, taking the worse result; these saving throws gain the misfortune trait.\nHeightened (9th) The duration is 8 hours.","source":{"provider":"PAIZO","sourceId":"wdb4XIZw1xmki5nr","book":"Pathfinder Battlecry!","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.skeleton-army","name":"Skeleton Army","kind":"SPELL","rank":6,"rarity":"COMMON","traits":["concentrate","incarnate","manipulate"],"traditions":["ARCANE","DIVINE","OCCULT"],"casting":{"time":{"kind":"ACTIONS","actions":3}},"targeting":{"range":{"kind":"DISTANCE","feet":100},"area":null},"duration":{"text":"until the end of your next turn","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"With a fistful of compressed bones, you summon a legion of skeletal hulks to fight in your war, refusing to let them rest until they've given up their last inches of usefulness to your cause. The undead army occupies the space of a Huge creature and has a Speed of 40 feet.\n\nArrive Bone March The skeletal hulks rise from the dirt, slashing through your enemies and attacking with their dirt-encrusted, bony hands. Enemies within a 20-foot emanation take 4d8 slashing damage (basic Reflex save). On a critical failure, a creature also take 2d8[persistent,bleed] damage.\n\nDepart Tossed Heads Before crumpling into a pile of bones, the skeleton army removes their skulls and throws them at the enemy lines, chattering and howling, dealing 6d6 piercing damage to enemies in a 20-foot burst (basic Reflex save) within 30 feet. On a critical failure, a creature is also Frightened 2.","source":{"provider":"PAIZO","sourceId":"y1dcR5unn2UwlUR9","book":"Pathfinder Battlecry!","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.sky-signs","name":"Sky Signs","kind":"RITUAL","rank":6,"rarity":"UNCOMMON","traits":["air","illusion","visual"],"traditions":[],"casting":{"time":{"kind":"LONG","text":"1 day"},"cost":"lenses and fine mineral dusts worth 300 gp total"},"targeting":{"range":{"kind":"NONE"},"area":null},"duration":{"text":"8 hours","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":{"primaryCheck":"Nature (master)","secondaryChecks":"Crafting, Diplomacy","secondaryCasters":2},"description":"You emblazon a message across the sky itself. Casting the ritual requires choosing a set of symbols for the message you want to send, which you can convey with an atmospheric phenomenon of your choice. Common choices include carefully shaped clouds during the day and auroras at night. Some cultures—such as the many denizens of the Plane of Air and star-gazing iruxis—develop complex symbology to communicate clearly using sky signs.\n\nThe message appears in the sky above you and can be seen to the horizon. To be conveyed in this way, the message must be very simple—typically something that can be expressed in 5 words or fewer. The symbols look the same to anyone who sees them. If you wish to conceal a message, you need to choose symbols that will make sense to your chosen audience but not to any other onlookers.\n\nCritical Success You display your chosen signs, and the message is clear to anyone who sees it.\n\nSuccess You display a somewhat muddled version of your message. The signs aren't entirely clear and require interpretation from those who view them—and many interpret them incorrectly.\n\nFailure You're unable to show your message.\n\nCritical Failure The spirits of air find your message audacious and offensive. As punishment, they emblazon the opposite of your intended message across the sky, and the message is clear to anyone who sees it.\n\nHeightened (10th) The scope of your message is truly staggering and can be seen across the entire planet.","source":{"provider":"PAIZO","sourceId":"sYd3hqv2ZQqa0PSc","book":"Pathfinder Rage of Elements","license":"OGL","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.sleepless-season","name":"Sleepless Season","kind":"RITUAL","rank":6,"rarity":"UNCOMMON","traits":["curse","mental"],"traditions":[],"casting":{"time":{"kind":"LONG","text":"4 hours"},"cost":"an amethyst pendant worth at least 75 gp"},"targeting":{"range":{"kind":"TEXT","text":"5 miles"},"area":{"shape":"SQUARE","feet":5280}},"duration":{"text":"1 week","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":{"primaryCheck":"Herbalism Lore (master) or Occultism (master)","secondaryChecks":"Medicine or Warfare Lore","secondaryCasters":1},"description":"You attempt to inflict a curse of sleeplessness upon individuals in the target area to weaken their resolve, possibly making it easier to conquer them. As you successfully complete the ritual, the amethyst pendant crumbles into sand that travels on an unfelt wind to drift down onto the target area. Each living creature in the target area must attempt a Fortitude saving throw against the ritual's casting DC or become unable to gain the benefits of a full night's rest for 1 week. The curse can be removed before that time with cleanse affliction or similar magic.\nCritical Success Sleep is unattainable for anyone in the target area who fails the saving throw. As usual, a living creature who goes more than 16 hours without sleeping becomes . A target who becomes fatigued in this way is also Enfeebled 1; the value of this condition can't be reduced while they're fatigued. For every subsequent day an affected target is fatigued, the value of their enfeebled condition increases by 1 (to a maximum of 4).\n\nSuccess Sleep can only be caught in short bursts for anyone in the target area who fails the saving throw. As critical success, but a fatigued target doesn't become enfeebled.\n\nFailure The ritual has no effect.\n\nCritical Failure The notion of sleep itself abandons the casters. The casters become fatigued and can't gain the benefits of a full night's rest for 1 month. This is a curse effect.","source":{"provider":"PAIZO","sourceId":"bTFWSpHEvXq8IK37","book":"Pathfinder Battlecry!","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["RANGE_NOT_STRUCTURED","NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.song-of-silver","name":"Song of Silver","kind":"RITUAL","rank":6,"rarity":"RARE","traits":[],"traditions":[],"casting":{"time":{"kind":"LONG","text":"8 hours"}},"targeting":{"range":{"kind":"NONE"},"area":null},"duration":{"text":"1 week","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":{"primaryCheck":"Performance","secondaryChecks":"Crafting, Society","secondaryCasters":6},"description":"The majority of the Song of Silver's time needed to Cast it consists of preparations for the performance, which must take place on a stage in Kintargo. While the Song of Silver can be cast by a single primary caster, up to six secondary casters can assist by helping to decorate the stage with Crafting or by spreading word and gathering an audience with Society. At the end of this 8-hour period, the primary caster performs the song, which takes up the final minute of the casting time.\n\nCritical Success The stage and rooftop above any stage where the song was performed glows softly with silver radiance for 1 week. During this time, the ritual tries to counteract teleportation effects and planar travel into or out of Kintargo attempted by unholy creatures, and all weapons wielded within Kintargo are treated as if they were made of silver for the purposes of calculating damage against creatures who possess weakness to silver. The ritual also generates the Success effects below. The Song of Silver can't be attempted again for 1 month.\n\nSuccess For 1 week, the primary and secondary casters gain a +2 status bonus to all saving throws against mental effects; this bonus doubles to a +4 status bonus against all fear effects. Each caster gains the ability to cast as an innate occult spell at a rank equal to what the Song of Silver was cast at, once during the week. These benefits are suppressed as long as the character is outside of Kintargo. The Song of Silver can't be attempted again for 1 month.\n\nFailure The Song of Silver fails, and it can't be attempted again for 1 month.\n\nCritical Failure Not only does the ritual fail, but the primary caster is overwhelmed with shame at the failure and becomes Stupefied 2 for 1 week (can't be removed by any means). The Song of Silver can't be attempted again for 6 months.\nHeightened (10th) The effects of the Song of Silver expand to cover all of Ravounel.","source":{"provider":"PAIZO","sourceId":"HYXyMFsH0K80etBI","book":"Pathfinder #205: Singer, Stalker, Skinsaw Man","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.speaking-sky","name":"Speaking Sky","kind":"SPELL","rank":6,"rarity":"UNCOMMON","traits":["air","concentrate","focus","manipulate"],"traditions":[],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"NONE"},"area":null},"duration":{"text":"1 round","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"The air speaks to you. You can precisely sense any motion within 60 feet through vibration and air movement.","source":{"provider":"PAIZO","sourceId":"Zvg0FWzClGbzucFd","book":"Pathfinder Lost Omens Impossible Lands","license":"OGL","remaster":false},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.spellsurge","name":"Spellsurge","kind":"SPELL","rank":6,"rarity":"UNCOMMON","traits":["concentrate","focus","mythic"],"traditions":[],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"NONE"},"area":{"shape":"EMANATION","feet":10}},"duration":{"text":"1 minute","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"Magic surges to life around you, feeding on the raw power you radiate. Choose one of the following abilities to affect creatures in your aura. You can choose a different effect, ending the previous one, by Sustaining the spell. You can Dismiss the aura.\n- Interference The excess magic surrounding you creates a mental static. All saving throws against mental effects gain a +2 circumstance bonus.\n- Mana Well You become a source of pure magic that allows spells to be cast more freely. Allied creatures that would normally be required to attempt a flat check to Cast a Spell (such as from the condition) automatically succeed.\n- Overpower Resistance Surging magic penetrates most defenses. Any time a spell affects a creature within the aura, that spell ignores an amount of the creature's resistance equal to your level. This applies to all damage the spell deals, including persistent damage and damage caused by an ongoing effect of the spell. This doesn't cause the spell to ignore immunities.\n- Ward Stray magical energy diffuses damaging spells. Any time a spell affects a creature within the aura, the damage dealt by the spell is reduced by an amount equal to your level. This applies to all damage the spell deals, including persistent damage and damage caused by an ongoing effect of the spell.","source":{"provider":"PAIZO","sourceId":"XIgvCPaSy5WXStVD","book":"Pathfinder War of Immortals","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.spellwrack","name":"Spellwrack","kind":"SPELL","rank":6,"rarity":"COMMON","traits":["concentrate","curse","force","manipulate"],"traditions":["ARCANE","DIVINE","OCCULT"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":30},"target":"1 creature","area":null},"duration":{"text":"","sustained":false},"defense":{"kind":"SAVE","statistic":"WILL","basic":false},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You cause any spells cast on the target to spill out their energy in harmful surges. The target must attempt a Will save.\n\nCritical Success The target is unaffected.\n\nSuccess Whenever the target becomes affected by a spell with a duration, the target takes 2d12[persistent,force] damage. Each time it takes persistent force damage from spellwrack, it reduces the remaining duration of spells affecting it by 1 round. Only a successful arcana check against your spell DC can help the target recover from the persistent damage; the curse and the persistent damage end after 1 minute.\n\nFailure As success, but the curse and persistent damage do not end on their own.\n\nCritical Failure As failure, but the persistent force damage is 4d12[persistent,force].","source":{"provider":"PAIZO","sourceId":"8Umt1AzYfFbC4fui","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.spirit-blast","name":"Spirit Blast","kind":"SPELL","rank":6,"rarity":"COMMON","traits":["concentrate","manipulate","spirit"],"traditions":["DIVINE","OCCULT"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":30},"target":"1 creature","area":null},"duration":{"text":"","sustained":false},"defense":{"kind":"SAVE","statistic":"FORTITUDE","basic":true},"damage":[{"id":"0","formula":"16d6","damageType":"spirit","kind":"DAMAGE","applyAbilityModifier":false}],"heightening":{"kind":"INTERVAL","everyRanks":1,"damage":{"0":"2d6"}},"counteraction":false,"ritual":null,"description":"You concentrate ethereal energy and attack a creature's spirit, dealing 16d6 spirit damage with a basic Fortitude save.\n\nHeightened (+1) The damage increases by 2d6.","source":{"provider":"PAIZO","sourceId":"PHVHBbdHeQRfjLmE","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"SUPPORTED","reasons":[]}},{"id":"pf2e.spell.statuette","name":"Statuette","kind":"RITUAL","rank":6,"rarity":"RARE","traits":["polymorph"],"traditions":[],"casting":{"time":{"kind":"LONG","text":"1 hour"}},"targeting":{"range":{"kind":"DISTANCE","feet":10},"target":"1 freestanding, non-magical object no larger than 3,000 cubic feet (the size of a Huge creature)","area":null},"duration":{"text":"","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":{"primaryCheck":"Arcana (expert)","secondaryChecks":"Crafting, Occultism","secondaryCasters":2},"description":"This ritual is a variant of the shrink item spell that allows for the transformation of significantly larger items. You transform the object into a tiny statuette of itself that is Light Bulk. The ritual does not shrink any creatures inside or on top of the item when it is transformed. The item remains in statuette form until the ritual's duration expires or until a creature places it on a stable surface and uses a 10-minute activity to Interact with the item to enlarge it. When restored to its normal size, the object simply pushes other creatures and objects aside or harmlessly contains them, as a magic item with the structure trait.\n\nYour Arcana check determines how long the object remains in statuette form.\n\nCritical Success The object remains a statuette for 1 week.\n\nSuccess The object remains a statuette for 1 day.\n\nFailure You fail to shrink the object.\n\nCritical Failure You fail to shrink the object, and the highest-level item you carry of light Bulk or more shrinks to a tiny, unusable figurine of itself, weighing negligible bulk, for 1 week.","source":{"provider":"PAIZO","sourceId":"29AyhknPKiDBcy8s","book":"Pathfinder #154: Siege of the Dinosaurs","license":"OGL","remaster":false},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.stone-to-flesh","name":"Stone to Flesh","kind":"SPELL","rank":6,"rarity":"COMMON","traits":["concentrate","earth","manipulate"],"traditions":["DIVINE","PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"TOUCH"},"target":"petrified creature or human-size stone object","area":null},"duration":{"text":"","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"Manipulating the fundamental particles of matter, you convert stone into flesh and blood. You restore a creature to its normal state or transform a stone object into a mass of inert flesh (without stone's Hardness) in roughly the same shape.","source":{"provider":"PAIZO","sourceId":"Pr1ruNTbzGn3H9w5","book":"Pathfinder Core Rulebook","license":"OGL","remaster":false},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.suffocate","name":"Suffocate","kind":"SPELL","rank":6,"rarity":"UNCOMMON","traits":["concentrate","incapacitation","manipulate","nonlethal"],"traditions":[],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":30},"target":"1 living creature that needs to breathe","area":null},"duration":{"text":"1 minute","sustained":true},"defense":{"kind":"SAVE","statistic":"FORTITUDE","basic":false},"damage":[{"id":"S01QYJk4ki5zDbr9","formula":"4d8","damageType":"bludgeoning","kind":"DAMAGE","applyAbilityModifier":false}],"heightening":{"kind":"MANUAL","text":"Aprimoramento com valores especificos por rank."},"counteraction":false,"ritual":null,"description":"You forcefully and cruelly draw the living breath from a creature's lungs, dealing 4d8 bludgeoning damage. The creature must attempt a Fortitude save.\n\nCritical Success The creature is unaffected.\n\nSuccess The creature takes half damage.\n\nFailure The creature takes full damage. For the duration, the creature must hold its breath or suffocate.\n\nCritical Failure The creature takes double damage, and all the air is pulled from the creature's lungs. The creature falls and starts suffocating for the duration.\n\nHeightened (9th) You can target up to 5 creatures.","source":{"provider":"PAIZO","sourceId":"qGWORxQ0aSsH2taf","book":"Pathfinder #186: Ghost King's Rage","license":"OGL","remaster":false},"automation":{"status":"PARTIAL","reasons":["HEIGHTENING_REQUIRES_MANUAL_RESOLUTION"]}},{"id":"pf2e.spell.suspended-retribution","name":"Suspended Retribution","kind":"SPELL","rank":6,"rarity":"COMMON","traits":["concentrate","curse","manipulate","mental","prediction"],"traditions":["DIVINE","OCCULT"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":60},"target":"1 creature","area":null},"duration":{"text":"1 minute","sustained":false},"defense":{"kind":"SAVE","statistic":"REFLEX","basic":true},"damage":[{"id":"OXGejDCEbQpInshn","formula":"70","damageType":"mental","kind":"DAMAGE","applyAbilityModifier":false}],"heightening":{"kind":"INTERVAL","everyRanks":1,"damage":{"OXGejDCEbQpInshn":"10"}},"counteraction":false,"ritual":null,"description":"All life dances one step from the precipice, one heartbeat from disaster. You open your eyes wide and see doom waiting in the wings, then invite it to step forward. A spectral omen of disaster appears above the target's head—traditionally, this is a downward-pointing sword, but some spellcasters report seeing a hangman's noose or a grinning skull instead. When you Cast this Spell, pick one of the following triggers.\n- The target moves more than its Speed in a single round.\n- The target makes more than one Strike in a single round.\n- The target Casts a Spell.\n- The target uses a specific skill you name.\n- The target uses a specific ability you name.\nThe target uses a specific ability you name. If the target takes the triggering action, the portent of doom activates—the sword strikes down, the noose loops around the target's neck, the skull bares its fangs—and the target takes 70 mental damage with a basic Reflex save. The target instinctively knows which action will trigger the omen and can ward off the omen by spending a total of 3 actions, which have the concentrate trait, to pray, make signs against doom, or similar apotropaic actions. These actions need not be consecutive. After the creature spends the actions, the spell ends.\nHeightened (+1) The damage increases by 10.","source":{"provider":"PAIZO","sourceId":"k0qJfSZH5xUEggwU","book":"Pathfinder Dark Archive (Remastered)","license":"ORC","remaster":true},"automation":{"status":"SUPPORTED","reasons":[]}},{"id":"pf2e.spell.tanglecurse","name":"Tanglecurse","kind":"SPELL","rank":6,"rarity":"RARE","traits":["concentrate","curse","fungus","manipulate"],"traditions":["DIVINE","PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":30},"target":"1 creature","area":null},"duration":{"text":"","sustained":false},"defense":{"kind":"SAVE","statistic":"WILL","basic":false},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"Tanglebriar has been called a \"curse on the land,\" which has inspired Treerazer's cult to develop this notorious spell. The target must attempt a Will save.\nCritical Success The target is unaffected.\n\nSuccess A fungal bloom springs up from the ground in a around the target. This area is difficult terrain for creatures that enter the area. The target treats all terrain as difficult terrain since this swath of fungus moves with them as they do, transforming into a tangle of spores and floating tendrils if the target flies or a thick swath of stringy floating algae if the target swims. This effect ends after 1 minute or as soon as the curse is lifted, whichever comes first.\n\nFailure As success, but the fungal bloom increases to 10 feet. It persists until the curse is lifted. In addition, the target is also affected by the spores exuded by the fungal bloom—roll [[/r 1d4]] and consult the results below to see how the spores affect them. This affect reactivates automatically every 24 hours, replacing the previous result.\n\n1: The spores cause atrophy; the target is Enfeebled 1.\n\n2: The spores cause fibrous fungal growths to sprout from the target; the target is Clumsy 1.\n\n3: The spores settle in the target's blood and flesh and cause great pain; the target is Drained 1.\n\n4: The spores intrude upon the mind and cause hallucinations; the target is Stupefied 1.\n\nCritical Failure As failure, but the emanation increases to 15 feet, and the condition value caused by the spores increases to 2.","source":{"provider":"PAIZO","sourceId":"BokwLLK7OjK6ggHs","book":"Pathfinder #211: The Secret of Deathstalk Tower","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.tangling-creepers","name":"Tangling Creepers","kind":"SPELL","rank":6,"rarity":"COMMON","traits":["concentrate","manipulate","plant","wood"],"traditions":["ARCANE","PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":3}},"targeting":{"range":{"kind":"DISTANCE","feet":500},"area":{"shape":"BURST","feet":40}},"duration":{"text":"10 minutes","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"Dense, twitching creepers sprout from every surface and fill any bodies of water in the area. Any creature moving on the land, or Climbing or Swimming within the creepers, takes a –10-foot circumstance penalty to its Speeds while in the area. Once per round, you can Sustain the spell to make a vine lash out from any square within the expanse of creepers. This vine has a 15-foot reach. Make a melee spell attack roll against the target; on a success, the vine pulls the target into the creepers and makes it for 1 round or until the creature Escapes (against your spell DC), whichever comes first.","source":{"provider":"PAIZO","sourceId":"JbAcSLu62TU1OgNF","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.teleport","name":"Teleport","kind":"SPELL","rank":6,"rarity":"UNCOMMON","traits":["concentrate","manipulate","teleportation"],"traditions":["ARCANE","OCCULT"],"casting":{"time":{"kind":"LONG","text":"10 minutes"}},"targeting":{"range":{"kind":"TEXT","text":"100 miles"},"target":"you and up to 4 targets touched, either willing creatures or objects roughly the size of a creature.","area":null},"duration":{"text":"","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You and the targets are instantly transported to any location within range, as long as you can identify the location precisely both by its position relative to your starting position and by its appearance (or other identifying features). Incorrect knowledge of the location's appearance usually causes the spell to fail, but it could instead lead to teleporting to an unwanted location or some other unusual mishap determined by the GM. Teleport is not precise over great distances. The targets appear at a distance from the intended destination equal to roughly 1 percent of the total distance traveled, in a direction determined by the GM. For short journeys, this lack of precision is irrelevant, but for long distances this could be up to 1 mile.\n\nHeightened (7th) You and the other targets can travel to any location within 1,000 miles.\n\nHeightened (8th) You and the other targets can travel to any location on the same planet. If you travel more than 1,000 miles, you arrive only 10 miles off target.\n\nHeightened (9th) You and the other targets can travel to any location on another planet within the same solar system. Assuming you have accurate knowledge of the location's position and appearance, you arrive on the new planet 100 miles off target.\n\nHeightened (10th) As the 9th-rank version, but you and the other targets can travel to any planet within the same galaxy.","source":{"provider":"PAIZO","sourceId":"69L70wKfGDY66Mk9","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["RANGE_NOT_STRUCTURED","NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.tempest-form","name":"Tempest Form","kind":"SPELL","rank":6,"rarity":"UNCOMMON","traits":["concentrate","focus","manipulate","oracle","polymorph"],"traditions":[],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"NONE"},"area":null},"duration":{"text":"1 minute","sustained":true},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"Your body becomes fluid to better suit your surroundings. Choose whether to become air, water, or mist. The spell gains the air trait if you choose air or mist, and the water trait if you choose water or mist. You become amorphous, as does your armor. You lose any item bonus to AC and use your proficiency bonus for unarmored defense to determine your AC. You also gain resistance 10 to physical damage and become immune to precision damage. You can slip through tiny cracks and don't need to breathe. You can't cast spells, activate items, or use actions that have the attack or manipulate trait, except those granted by this spell. You also gain the following effects based on your form.\n- Air You gain a fly Speed of 20 feet and become while you are in the air. You can create the effects of a from your space as a 2-action activity, which has the manipulate trait.\n- Mist You gain a fly Speed of 20 feet, and it becomes hard to see through you. Any creature on one side of your space who is targeted by a creature on the opposite side is to the targeting creature.\n- Water You gain a swim Speed of 20 feet and become invisible while you are in the water. You can electrically charge yourself by taking a single action, which has the manipulate trait. If you do, you are no longer invisible in the water due to electricity indicating your location, but any creature that makes a melee attack against you takes (1d6+max(0,floor(@item.rank/2) -3))[electricity] damage.\n\nHeightened (+2) Increase the resistance by 5 and the electricity damage from the charged water form by 1.","source":{"provider":"PAIZO","sourceId":"zhqnMOVPzVvWSUbC","book":"Pathfinder Player Core 2","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.temporal-ward","name":"Temporal Ward","kind":"SPELL","rank":6,"rarity":"RARE","traits":["concentrate","manipulate"],"traditions":["ARCANE","DIVINE","OCCULT"],"casting":{"time":{"kind":"ACTIONS","actions":3}},"targeting":{"range":{"kind":"TOUCH"},"target":"1 container or doorway","area":null},"duration":{"text":"10 minutes","sustained":false},"defense":{"kind":"SAVE","statistic":"WILL","basic":false},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You ward a target doorway or container with a temporal trap that rewinds the personal timeline of creatures trying to open it. A creature attempting to open a warded doorway or container must attempt a Will save with the below results.\n\nYou can set a password for the ward. Any creature that attempts to open the target container, or to open or pass through the target doorway without speaking the password must attempt a save as normal.\n\nThe ward vanishes automatically once the spell's duration ends, but can be removed before then as if it were a magical trap, using your spell DC for both the Perception check to notice it and Thievery check to disable it. Both checks require the creature attempting them to have expert proficiency in order to succeed.\n\nYou can temporal ward. The maximum number of temporal wards you can have active at a time is equal to your spellcasting ability modifier.\n\nCritical Success The creature is unaffected and opens the doorway or the container as normal.\n\nSuccess The creature experiences a brief moment of déjà-vu in which they're convinced they already opened the door. They must use an additional action to open the door. If they can't or don't want to do so, the action or activity they used to open the door or container is wasted, and the door or container remains closed.\n\nFailure The creature is thrown briefly backwards in time. The action or activity they used to open the door or container is wasted and they're returned to the position they were located at during the start of their turn. Their turn then ends.\n\nCritical Failure As failure, but the temporal displacement also causes the creature to lose their bearings, making them for 1 minute.\n\nHeightened (10th) The temporal ward has an unlimited duration, until it is counteracted, Dismissed, or Disarmed.","source":{"provider":"PAIZO","sourceId":"kLxJx7BECVgHh2vb","book":"Pathfinder #173: Doorway to the Red Star","license":"OGL","remaster":false},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.terminate-bloodline","name":"Terminate Bloodline","kind":"RITUAL","rank":6,"rarity":"UNCOMMON","traits":[],"traditions":[],"casting":{"time":{"kind":"LONG","text":"1 day"},"cost":"a bodily sample from the target, and valuables belonging to the target worth a total value of 100 gp × the spell rank × the target's level"},"targeting":{"range":{"kind":"TEXT","text":"10 miles"},"target":"1 creature of a level no greater than double the terminate bloodline ritual's level","area":null},"duration":{"text":"","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":{"primaryCheck":"Occultism (master)","secondaryChecks":"Society","secondaryCasters":3},"description":"Mighty drow noble houses, including House Shraen, use this ritual to stamp out fledgling noble houses before they rise to power. At the ritual's completion, you place a contagious wasting disease upon the target creature with the intention of ending their familial bloodline.\n\nThe ritual is easiest to cast on a subdued target, typically a low-ranking member of the targeted family bloodline who is kidnapped and has their memory wiped. If the target is conscious when the ritual is cast, the target attempts a Fortitude save against the ritual's DC; on a success, the ritual fails. Otherwise, the target is automatically affected by the dying bloodline disease.\n\nDying Bloodline (curse, disease) Failing or critically failing this disease's Fortitude save causes the disease to progress to the next stage as normal; however, succeeding or critically succeeding at the save has no effect. The disease can be removed only by first successfully counteracting the curse and then counteracting the disease\n\nLevel equal to twice the ritual's level\n\nStage 1 carrier with no effect (1 month)\n\nStage 2 (1 week)\n\nStage 3 fatigued and Drained 1 (1 day)\n\nStage 4 fatigued and Drained 3 (1 day)\n\nStage 5 death.\n\nEvery member of an infected creature's immediate family (blood relationship or parent or child) that comes into physical contact with that infected creature must attempt a Fortitude save or contract the disease.\n\nCritical Success The creature does not contract the disease and does not need to attempt further saves when coming into physical contact with that particular creature (the creature is not immune to the disease, however, and must attempt a save as normal if it comes into physical contact with a different infected family member).\n\nSuccess The creature is not affected but must attempt another save the next time they come into physical contact with that particular infected creature.\n\nFailure The creature contracts the disease and can spread it in the same way as the original target.","source":{"provider":"PAIZO","sourceId":"yUM5OYeMY8971b2S","book":"Pathfinder #155: Lord of the Black Sands","license":"OGL","remaster":false},"automation":{"status":"MANUAL","reasons":["RANGE_NOT_STRUCTURED","NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.the-unseeing-blade-master","name":"The Unseeing Blade Master","kind":"RITUAL","rank":6,"rarity":"RARE","traits":["trial"],"traditions":[],"casting":{"time":{"kind":"LONG","text":"1 day"},"cost":"rare incense worth 1,500 gp"},"targeting":{"range":{"kind":"NONE"},"area":null},"duration":{"text":"","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":{"primaryCheck":"Perception (master)","secondaryChecks":"Religion or Warfare Lore","secondaryCasters":1},"description":"There are many legends of blade masters who, not wanting to rely on flawed mortal eyes, learned to fight through reliance on both their other keen senses and knowledge from the universe itself. Those who intentionally seek out the path often do so by running through forms in thick clouds of incense.\n\nMaking a Strike against an enemy you can see is anathema to this ritual and immediately ends its benefits. If the ritual is ended in this way, you must conduct an ritual before attempting this ritual again.\n\nCritical Success As success, except you can instead defeat an enemy in single combat that both uses a sword and is higher level than you.\n\nSuccess You call a blessing into your sword to guide you on the path and are bound by the ritual's anathema. Once you've used that sword against 20 enemies, each significant enough to grant XP, you gain the feat.\n\nFailure The incense is dispersed by a strange gust of wind and you learn nothing.\n\nCritical Failure The sword you're intending to use for the ritual becomes broken. If you aren't permanently blind, you're instead for 1 month and can't repeat this ritual during that time.","source":{"provider":"PAIZO","sourceId":"5xf9wK9xyAeGFPw7","book":"Pathfinder Lost Omens Tian Xia World Guide","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.tree-of-seasons","name":"Tree of Seasons","kind":"SPELL","rank":6,"rarity":"COMMON","traits":["concentrate","manipulate","plant","wood"],"traditions":["PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":60},"area":null},"duration":{"text":"1 minute","sustained":false},"defense":{"kind":"SAVE","statistic":"REFLEX","basic":true},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You cause a Small tree to instantly sprout in an unoccupied space on the ground. Four seedpods grow from the tree, each filled with the magic of a different one of the four seasons. A creature can Interact to pluck one of the pods, and can then either throw it up to 30 feet as part of the same action or do so with a separate Interact action later. When thrown, a pod explodes in a , dealing 6d6 damage with a basic Reflex save against your spell DC. The damage type depends on the season of the pod: electricity for spring, fire for summer, poison for autumn, or cold for winter. When the spell ends, the tree withers away and any remaining pods rot, leaving behind non-magical seeds.\n\n(@item.level)d6[cold]\n\n(@item.level)d6[electricity]\n\n(@item.level)d6[fire]\n\n(@item.level)d6[poison]\nHeightened (+1) The burst's damage increases by 1d6.","source":{"provider":"PAIZO","sourceId":"u5FAOOXuqK7fLqKW","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.truesight","name":"Truesight","kind":"SPELL","rank":6,"rarity":"COMMON","traits":["concentrate","manipulate","revelation"],"traditions":["ARCANE","DIVINE","OCCULT","PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"NONE"},"area":null},"duration":{"text":"10 minutes","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":true,"ritual":null,"description":"You see things within 60 feet as they actually are. The GM rolls a secret counteract check against any illusion, morph or polymorph effect in the area, but only for the purpose of determining whether you see through it (for instance, if the check succeeds against a polymorph spell, you can see the creature's true form, but you don't end the polymorph spell).","source":{"provider":"PAIZO","sourceId":"uqlxMQQeSGWEVjki","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.unexpected-transposition","name":"Unexpected Transposition","kind":"SPELL","rank":6,"rarity":"COMMON","traits":["concentrate","teleportation"],"traditions":["ARCANE","OCCULT"],"casting":{"time":{"kind":"REACTION"}},"targeting":{"range":{"kind":"DISTANCE","feet":30},"target":"1 creature other than the triggering enemy","area":null},"duration":{"text":"","sustained":false},"defense":{"kind":"SAVE","statistic":"WILL","basic":false},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"Trigger You are targeted with an enemy's Strike.\n\nWhen attacked, you attempt to quickly swap your own position with that of another creature. A creature that is unwilling to swap places with you must attempt a Will save. Willing creatures automatically fail. If you successfully switch places with the target, the triggering attack is resolved against that creature as if it had been the original target of the attack. After the swap, you and the target are both temporarily immune to unexpected transposition spells for 1 minute. You automatically switch places if the target is willing. If it's unwilling, it can attempt a Will save. Neither of you teleports if the target succeeds at its save.","source":{"provider":"PAIZO","sourceId":"OOMQ8Z6EIrGt5NJ6","book":"Pathfinder Secrets of Magic","license":"OGL","remaster":false},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.utter-destruction","name":"Utter Destruction","kind":"SPELL","rank":6,"rarity":"UNCOMMON","traits":["death","sonic","void"],"traditions":["ARCANE","OCCULT","PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":120},"area":{"shape":"CONE","feet":30}},"duration":{"text":"","sustained":false},"defense":{"kind":"SAVE","statistic":"FORTITUDE","basic":false},"damage":[{"id":"0yIRszQ4ZAlq14gX","formula":"4d8","damageType":"sonic","kind":"DAMAGE","applyAbilityModifier":false},{"id":"1tttVaJo3TXKF7uK","formula":"4d8","damageType":"void","kind":"DAMAGE","applyAbilityModifier":false}],"heightening":{"kind":"INTERVAL","everyRanks":1,"damage":{"0yIRszQ4ZAlq14gX":"1d8","1tttVaJo3TXKF7uK":"1d8"},"areaFeet":0},"counteraction":false,"ritual":null,"description":"You screech with an unearthly voice made of destructive energy, smashing everything that lies before you. Creatures in the area take 4d8 sonic damage and 4d8 void damage. Each creature must attempt a Fortitude save. Unattended objects of Hardness 5 or less in the area of effect are destroyed.\nCritical Success The creature takes half damage.\n\nSuccess The creature takes half damage and is for 1 round.\n\nFailure The creature takes full damage and is deafened for 1 minute.\n\nCritical Failure The creature takes double damage and is permanently deafened.\nHeightened (+1) The sonic and void damage each increase by 1d8. The Hardness threshold of items destroyed by the spell increases by 1.","source":{"provider":"PAIZO","sourceId":"XGB77j7m0SLky8U1","book":"Pathfinder #209: Destroyer's Doom","license":"ORC","remaster":true},"automation":{"status":"PARTIAL","reasons":["MULTIPLE_DAMAGE_COMPONENTS"]}},{"id":"pf2e.spell.vampiric-exsanguination","name":"Vampiric Exsanguination","kind":"SPELL","rank":6,"rarity":"COMMON","traits":["concentrate","death","manipulate","void"],"traditions":["ARCANE","DIVINE","OCCULT"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"NONE"},"area":{"shape":"CONE","feet":30}},"duration":{"text":"","sustained":false},"defense":{"kind":"SAVE","statistic":"FORTITUDE","basic":true},"damage":[{"id":"0","formula":"12d6","damageType":"void","kind":"DAMAGE","applyAbilityModifier":false}],"heightening":{"kind":"INTERVAL","everyRanks":1,"damage":{"0":"2d6"},"areaFeet":0},"counteraction":false,"ritual":null,"description":"You draw in the blood and life force of other creatures through your outstretched arms. You deal 12d6 void damage to living creatures in the area with a basic Fortitude save.\n\nYou gain temporary Hit Points equal to half the damage a single creature takes from this spell; calculate these temporary Hit Points using the creature that took the most damage. You lose any remaining temporary Hit Points after 1 minute.\n\nHeightened (+1) The damage increases by 2d6.","source":{"provider":"PAIZO","sourceId":"fd31tAHSSGXyOxW6","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"SUPPORTED","reasons":[]}},{"id":"pf2e.spell.vibrant-pattern","name":"Vibrant Pattern","kind":"SPELL","rank":6,"rarity":"COMMON","traits":["illusion","incapacitation","manipulate","subtle","visual"],"traditions":["ARCANE","OCCULT"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":120},"area":{"shape":"BURST","feet":10}},"duration":{"text":"1 minute","sustained":true},"defense":{"kind":"SAVE","statistic":"WILL","basic":false},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You create a pattern of lights that pulses with intensity. Creatures are while inside the pattern. In addition, a creature must attempt a Will saving throw if it's inside the pattern when you cast it, enters the pattern, ends its turn within the pattern, or uses a Seek or Interact action on the pattern. A creature currently by the pattern doesn't need to attempt new saving throws.\n\nSuccess The creature is unaffected.\n\nFailure The creature is Blinded by the pattern. If it exits the pattern, it can attempt a new save to recover from the Blinded condition at the end of each of its turns, to a maximum duration of 1 minute.\n\nCritical Failure The creature is Blinded for 1 minute.","source":{"provider":"PAIZO","sourceId":"RQjSQVZRG497cJhX","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.vitrifying-blast","name":"Vitrifying Blast","kind":"SPELL","rank":6,"rarity":"COMMON","traits":["concentrate","earth","manipulate"],"traditions":["ARCANE","PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":60},"area":{"shape":"CONE","feet":15}},"duration":{"text":"varies","sustained":false},"defense":{"kind":"SAVE","statistic":"REFLEX","basic":false},"damage":[{"id":"wVWFtjzGdYwwjMJi","formula":"8d6","damageType":"piercing","kind":"DAMAGE","applyAbilityModifier":false}],"heightening":{"kind":"INTERVAL","everyRanks":1,"damage":{"wVWFtjzGdYwwjMJi":"1d6"},"areaFeet":0},"counteraction":false,"ritual":null,"description":"You launch a cone of glass shards, which embed in creatures to turn them partially to glass. The shards deal 8d6 piercing damage to creatures in the area, based on each creature's saving throw.\n\nCritical Success The target is unaffected.\n\nSuccess The target takes half damage and gains weakness 3 to sonic and bludgeoning damage for 1 round.\n\nFailure The target takes full damage, is Slowed 1, and gains weakness to sonic and bludgeoning damage. The weakness is equal to 3 × the slowed value it has from this spell. The target must attempt a Fortitude save at the end of each of its turns; this ongoing save has the incapacitation trait. On a failed save, the creature's slowed value increases by 1 (or by 2 on a critical failure), to a maximum of Slowed 3. A successful save reduces the creature's slowed value by 1 (or by 2 on a critical success). If the creature ends its turn with a slowed value of 0, the effect ends.\n\nCritical Failure As failure, but the target is initially Slowed 2.\n\nHeightened (+1) The damage increases by 1d6.","source":{"provider":"PAIZO","sourceId":"g2V4ID0pl1ZGAxZj","book":"Pathfinder Rage of Elements","license":"OGL","remaster":true},"automation":{"status":"SUPPORTED","reasons":[]}},{"id":"pf2e.spell.wall-of-force","name":"Wall of Force","kind":"SPELL","rank":6,"rarity":"COMMON","traits":["concentrate","force","manipulate"],"traditions":["ARCANE","OCCULT"],"casting":{"time":{"kind":"ACTIONS","actions":3}},"targeting":{"range":{"kind":"DISTANCE","feet":30},"area":null},"duration":{"text":"1 minute","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You form an wall of pure magical force up to 50 feet long and up to 20 feet high. The wall has no discernible thickness. You must create the wall in an unbroken open space so its edges don't pass through any creatures or objects, or the spell is lost. The wall has AC 10, Hardness 30, and 60 Hit Points, and it's immune to critical hits and precision damage. The wall blocks physical effects from passing through it, and because it's made of force, it blocks incorporeal and ethereal creatures as well. Teleportation effects can pass through the barrier, as can visual effects (since the wall is invisible). Wall of force is immune to counteracting effects of its level or lower, but the wall is automatically destroyed by a spell of any rank.\nHeightened (+2) The Hit Points of the wall increase by 20.","source":{"provider":"PAIZO","sourceId":"7Iela4GgVeO3LfAo","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.wall-of-metal","name":"Wall of Metal","kind":"SPELL","rank":6,"rarity":"COMMON","traits":["concentrate","manipulate","metal"],"traditions":["ARCANE","PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":3}},"targeting":{"range":{"kind":"DISTANCE","feet":120},"area":null},"duration":{"text":"1 minute","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You call forth a sheet of metal, forming a wall of iron, low-grade cold iron, or standard-grade silver up to 60 feet long, 30 feet high, and 1/4 inch thick. The wall doesn't need to stand vertically but must form a straight line in an unbroken open space so it doesn't pass through any creatures or objects, or the spell is lost. Each 10-foot-by-10- foot section of the wall has AC 10 and is immune to critical hits and precision damage. The wall's Hardness, HP, and BT use the statistics of a structure of the material you chose. Creatures can move through a section of the wall that's broken.\n\nHeightened (7th) The wall is high-grade silver or standard-grade dawnsilver.\n\nHeightened (8th) The wall is standard-grade cold iron.\n\nHeightened (9th) The wall is high-grade dawnsilver.\n\nHeightened (10th) The wall is high-grade cold iron or standard-grade adamantine.","source":{"provider":"PAIZO","sourceId":"CB5TlGv5ZghtMifi","book":"Pathfinder Rage of Elements","license":"OGL","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.ward-domain","name":"Ward Domain","kind":"RITUAL","rank":6,"rarity":"UNCOMMON","traits":[],"traditions":[],"casting":{"time":{"kind":"LONG","text":"1 day"},"cost":"rare incenses, oils, and powdered silver, worth 150 gp total"},"targeting":{"range":{"kind":"NONE"},"area":null},"duration":{"text":"1 week","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":{"primaryCheck":"Arcana, Nature, or Occultism (master)","secondaryChecks":"Lore (any), Survival, Thievery","secondaryCasters":3},"description":"Area 100 feet × 100 feet, up to 50 feet high.\nThis ritual has long been used to guard the private sanctums of powerful rulers, spellcasters, and other figures of import. You and the other casters spend the casting time burning incense, anointing doorframes, and drawing lines of powered silver across entryways. The ritual creates the following magical effects within the area; these effects are heightened to the rank of ward domain and remain throughout the duration.\n\nAll gates, doors, windows, and similar apertures in the area (if any) are locked, with the effects of lock. In addition, you can obscure up to six doors, doorways, or similar entrances within the area with the effects of illusory object to appear as plain walls. Scrying spells can't perceive any stimuli from the area, and ward domain attempts to counteract teleportation effects into or out of the area, including attempts to summon creatures into the area, using a modifier equal to the ritual's save DC – 10.\n\nA successful dispel magic used on a specific effect removes only that effect (such as the lock effect on one window). A successful detonate magic ends the entire ritual.\nCritical Success You create the effects described above, and you protect an area twice as large.\n\nSuccess You create the effects described above.\n\nFailure The ritual has no effect.\n\nCritical Failure The area becomes trapped and hostile to you and your allies in a way you didn't anticipate.\nHeightened (+1) The ward covers an additional area 100 feet × 100 feet, up to 50 feet high, contiguous with the original area.","source":{"provider":"PAIZO","sourceId":"Er9XNUlL0wB0PM36","book":"Pathfinder Player Core 2","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.word-of-revision","name":"Word of Revision","kind":"SPELL","rank":6,"rarity":"RARE","traits":["concentrate","fortune"],"traditions":["ARCANE","OCCULT"],"casting":{"time":{"kind":"REACTION"}},"targeting":{"range":{"kind":"DISTANCE","feet":60},"target":"1 creature","area":null},"duration":{"text":"","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"Trigger A creature within range fails or critically fails a saving throw or is reduced to 0 Hit Points\n\nAs all good writers know, you shouldn't kill off your protagonist before their story is complete. When you utter a word of revision, you alter the course of reality the instant it would otherwise have occurred, saving a creature from an unexpected or unwarranted fate. If the triggering creature failed its saving throw, it rerolls the saving throw. If the triggering creature critically failed its saving throw, it instead treats the result of that saving throw as a failure. If the triggering creature was reduced to 0 Hit Points, it remains at 1 Hit Point, and it still suffers any other debilitating effects that were associated with the source of the damage. In the case of a creature critically failing a saving throw or being reduced to 0 Hit Points simultaneously, you choose which of the two events to revise.\n\nOnce a creature is affected by a word of revision, it's temporarily immune to further words of revision for 24 hours, as fate resists allowing even the most important of protagonists from avoiding doom too often!\n\nHeightened (9th) You can target up to 10 creatures within range. All targets must still individually qualify as triggering creatures. For example, if a dragon breathed fire on a group of your allies, only those who failed or critically failed their saving throw or those who were reduced to 0 Hit Points could be affected by this spell.","source":{"provider":"PAIZO","sourceId":"BazbvgNmK46XjrVc","book":"Pathfinder Kingmaker","license":"OGL","remaster":false},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.zealous-conviction","name":"Zealous Conviction","kind":"SPELL","rank":6,"rarity":"COMMON","traits":["concentrate","emotion","manipulate","mental"],"traditions":["DIVINE","OCCULT"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":30},"target":"up to 10 willing creatures","area":null},"duration":{"text":"10 minutes","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You bypass your targets' rational minds, instilling them with unshakable conviction and zeal. The targets each gain 12 temporary Hit Points and a +2 status bonus to Will saves against mental effects, as their faith overrides the signals from their own bodies and minds. If you tell a target to do something, it must comply with your request, though if it would normally find the task repugnant, it can attempt a Will save at the end of its turn each round due to the cognitive dissonance. On a success, it ends the spell's effects on itself entirely.\n\nHeightened (9th) The temporary Hit Points increase to 18, and the status bonus to Will saves increases to +3.","source":{"provider":"PAIZO","sourceId":"GYD0XZ4t3tQq6shc","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.zero-gravity","name":"Zero Gravity","kind":"SPELL","rank":6,"rarity":"UNCOMMON","traits":["concentrate","manipulate"],"traditions":["ARCANE","OCCULT"],"casting":{"time":{"kind":"ACTIONS","actions":3}},"targeting":{"range":{"kind":"DISTANCE","feet":120},"area":{"shape":"CYLINDER","feet":20}},"duration":{"text":"1 minute","sustained":true},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"Area 20-foot radius, 40-foot-tall cylinder\n\nYou negate gravity's effects in the area. Creatures float in place unless they can Push Off a surface. Pushing Off is a single action which has the move trait, allowing the creature to move half its Speed in a straight line through the area. After Pushing Off a surface, the creature continues to move the same distance at the start of each of its turns until it leaves the area or Pushes Off against something else. A creature pushing against an untethered object of its size or smaller causes both the creature and the object to move at the same speed, but in opposite directions. Creatures who can levitate or fly can use those abilities to move around in the area without having to push off anything. Creatures who can't levitate or fly are usually on the ground, giving them a surface from which to push off.\n\nYou can Dismiss this spell. When zero gravity ends, all creatures and objects in the area fall back down.","source":{"provider":"PAIZO","sourceId":"P1iqzEIidRagUs7W","book":"Pathfinder Secrets of Magic","license":"OGL","remaster":false},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.allegro","name":"Allegro","kind":"SPELL","rank":7,"rarity":"UNCOMMON","traits":["bard","cantrip","composition","concentrate","emotion","mental"],"traditions":[],"casting":{"time":{"kind":"ACTIONS","actions":1}},"targeting":{"range":{"kind":"DISTANCE","feet":30},"target":"1 ally","area":null},"duration":{"text":"1 round","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You perform rapidly, speeding up your ally. The ally becomes and can use the additional action to Strike, Stride, or Step.","source":{"provider":"PAIZO","sourceId":"IQchIYUwbsVTa9Mc","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.angel-form","name":"Angel Form","kind":"SPELL","rank":7,"rarity":"COMMON","traits":["concentrate","holy","manipulate","polymorph"],"traditions":["DIVINE"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"NONE"},"area":null},"duration":{"text":"1 minute","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"Invoking the celestial realms, you transform into a Medium angel battle form. When you cast this spell, choose balisse, choral, kuribu, or tennin. The battle form is Small if you choose choral or kuribu. While in this form, you gain the angel and celestial traits. You have hands in this battle form and can use manipulate actions. You can Dismiss the spell.\n\nYou gain the following statistics and abilities regardless of the form that you choose:\n- AC = 22 + your level. Ignore your armor check's penalty and Speed reduction.\n- 40 temporary Hit Points and weakness 10 to unholy.\n- Darkvision.\n- One or more attacks specific to the battle form you choose. You're trained with them. Your attack modifier is +25, and you use the listed damage. Melee attacks are Strength based (for the purpose of the enfeebled condition, for example), and ranged attacks are Dexterity based. If your attack modifier is higher for the given unarmed attack or weapon, you can use it instead.\n- Athletics modifier of +25, unless your own modifier is higher.\nYou also gain specific abilities based on the type of angel you choose:\n- Balisse Speed 30 feet, fly 40 feet; Perception modifier of +26 to detect lies and illusions unless your own modifier is higher\n- Melee 1 scimitar (fire, forceful, holy, magical, sweep), Damage 2d6+12 slashing plus 2d6 fire.\n\n- Choral Speed 30 feet, fly 40 feet; +1 status bonus to AC and saves against sonic and auditory\n- Melee 1 fist (agile), Damage 2d6+12 bludgeoning plus 1d6 spirit;\n- Ranged 1 piercing hymn (range 90 feet), Damage 1d6+12 sonic plus 1d6 spirit, and for 1 round on a critical hit.\n\n- Kuribu Speed 25 feet, fly 40 feet; resistance 10 to electricity and fire\n- Melee 1 fist (agile, holy, magical), Damage 3d4+12 bludgeoning.\n- Ranged 1 composite shortbow (deadly 2d10, holy, magical, propulsive, range increment 60 feet) Damage 3d6+12 piercing\n\n- Tennin Speed 30 feet, fly 60 feet; can Step into difficult terrain and use land and fly Speeds to Step;\n- Melee 1 fist (agile, holy, magical, nonlethal), Damage 1d6+12 bludgeoning plus 1d6 cold and 1d6 spirit.\n\nHeightened (9th) Your battle form is Large. You must have space to expand, or the spell is lost. You instead gain 60 temporary Hit Points, weakness 15 to unholy, attack modifier +30, damage bonus +20, and Athletics +33.","source":{"provider":"PAIZO","sourceId":"E3zIZ4pjlOuWeGRz","book":"Pathfinder Secrets of Magic","license":"OGL","remaster":false},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.attacked-from-within","name":"Attacked from Within","kind":"SPELL","rank":7,"rarity":"UNCOMMON","traits":["concentrate","manipulate","spirit"],"traditions":["DIVINE","OCCULT"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":30},"target":"1 creature","area":null},"duration":{"text":"varies","sustained":false},"defense":{"kind":"SAVE","statistic":"WILL","basic":false},"damage":[{"id":"nd3XNs3JZLTqgaDv","formula":"12d8","damageType":"spirit","kind":"DAMAGE","applyAbilityModifier":false}],"heightening":{"kind":"INTERVAL","everyRanks":1,"damage":{"nd3XNs3JZLTqgaDv":"2d8"},"areaFeet":0},"counteraction":false,"ritual":null,"description":"You assert your power over the target's own spirit as you reach deep into its soul in order to discover a moment of excruciating anguish, debilitating humiliation, or abject despair. The target takes 12d8 spirit damage and must attempt a Will save.\nCritical Success The target takes no damage, with a brief sensation of pain followed by a pleasant memory.\n\nSuccess The target takes half damage and is Frightened 1.\n\nFailure The target takes full damage and is Frightened 2.\n\nCritical Failure The target takes double damage and is frightened 2 and for 1 round.\nHeightened (+1) The damage increases by 2d8.","source":{"provider":"PAIZO","sourceId":"B4p4cD9Q71mHTpOP","book":"Pathfinder Lost Omens Shining Kingdoms","license":"ORC","remaster":true},"automation":{"status":"SUPPORTED","reasons":[]}},{"id":"pf2e.spell.beheading-buzz-saw","name":"Beheading Buzz Saw","kind":"SPELL","rank":7,"rarity":"COMMON","traits":["concentrate","manipulate","metal"],"traditions":["ARCANE"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"NONE"},"area":{"shape":"LINE","feet":60}},"duration":{"text":"","sustained":false},"defense":{"kind":"SAVE","statistic":"REFLEX","basic":false},"damage":[{"id":"0","formula":"5d10","damageType":"slashing","kind":"DAMAGE","applyAbilityModifier":false},{"id":"1","formula":"4d6","damageType":"bleed","kind":"DAMAGE","applyAbilityModifier":false}],"heightening":{"kind":"INTERVAL","everyRanks":1,"damage":{"0":"1d10","1":"1d6"},"areaFeet":0},"counteraction":false,"ritual":null,"description":"You compress molten scraps pulled from the Plane of Metal into a spinning disc with gruesome blades protruding from its edges. It wheels forward, slicing through anyone in its path. Each creature in the area takes 5d10 slashing damage and 4d6 persistent bleed damage, with a Reflex save.\n\nSuccess The creature is unaffected.\n\nFailure The creature takes full damage.\n\nCritical Failure The creature takes double damage. If the creature has a head, it must succeed at a fortitude save or be decapitated; this kills any creature except ones that don't require a head to live. For creatures with multiple heads, this usually kills the creature only if you sever its last head. This second save has the death and incapacitation traits.\nHeightened (+1) The slashing damage increases by 1d10, and the persistent bleed damage increases by 1d6.","source":{"provider":"PAIZO","sourceId":"dKWc83KKiXoIJkhp","book":"Pathfinder Rage of Elements","license":"OGL","remaster":true},"automation":{"status":"PARTIAL","reasons":["MULTIPLE_DAMAGE_COMPONENTS"]}},{"id":"pf2e.spell.blightburn-blast","name":"Blightburn Blast","kind":"SPELL","rank":7,"rarity":"UNCOMMON","traits":["concentrate","disease","manipulate"],"traditions":["ARCANE","OCCULT","PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"NONE"},"area":{"shape":"CONE","feet":15}},"duration":{"text":"","sustained":false},"defense":{"kind":"SAVE","statistic":"FORTITUDE","basic":true},"damage":[{"id":"0","formula":"4d6","damageType":"poison","kind":"DAMAGE","applyAbilityModifier":false}],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You channel a blast of powerful blightburn radiation from your hands. You deal 4d6 poison damage to creatures in the area. Creatures who fail their save are afflicted with stage 1 of blightburn sickness (on a critical failure, the creature moves immediately to stage 2). The level of blightburn sickness caused by this spell is equal to twice the spell's rank, and the disease's save DC uses the caster's DC.\n\nBlightburn Sickness (uncommon, disease) Level 15\n\nThe ceiling of the vault of the Black Desert is studded with deadly crystals that glimmer like stars above the dark sands. These crystals are radioactive and flood the vault with lethal energy. Creatures other than those native to the vault or who have survived there for a long time develop a disease called blightburn sickness.\n\nCreatures native to the Black Desert are immune, as are creatures who are affected by blightburn sickness but recover from it. The target can't recover from the disease's drained or sickened condition except by magic.\n\nThe surest way to avoid contracting blightburn sickness is by wearing a blightburn ward, a piece of protective jewelry often found among urdefhans' gear or for sale in Shraen.\n\nSaving Throw DC 32 Fortitude\n\nOnset [[/r 1d4 #days]]{1d4 days}\n\nStage 1 Drained 1 (1 day)\n\nStage 2 Drained 1 and Sickened 1 (1 day)\n\nStage 3 Drained 2 and Sickened 2 (1 week)\n\nStage 4 Drained 3 and Sickened 3 (1 month)\n\nStage 5 Drained increases by 1 (1 year)","source":{"provider":"PAIZO","sourceId":"EgkypvUZIZkx1UlQ","book":"Pathfinder #155: Lord of the Black Sands","license":"OGL","remaster":false},"automation":{"status":"SUPPORTED","reasons":[]}},{"id":"pf2e.spell.chrysopoetic-curse","name":"Chrysopoetic Curse","kind":"SPELL","rank":7,"rarity":"UNCOMMON","traits":["concentrate","curse","manipulate"],"traditions":["ARCANE","DIVINE"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":30},"target":"one creature","area":null},"duration":{"text":"1 minute","sustained":false},"defense":{"kind":"SAVE","statistic":"WILL","basic":false},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You grant the target the gift of riches, giving them the power to turn anything they touch to gold. The target must attempt a Will save.\nCritical Success The target is unaffected.\n\nSuccess The target's skin turns their armor and clothing partially to gold. If the target is wearing any armor or clothing, they become .\n\nFailure As success, but the curse extends to the target's held weapons and other gear. If the target is holding any weapons or other objects, they become Clumsy 3, and the objects' Hardness is reduced by 5.\n\nCritical Failure The curse becomes even stronger, extending to the surrounding terrain. As failure, and if the creature is standing on a solid surface, the ground in their space transmutes itself into a quagmire of liquid gold. The gold is greater difficult terrain. If the creature leaves its square (or when the curse ends), any affected terrain returns to its original shape and substance and the terrain in the new square transmutes to gold.\n\nAny objects that were turned to gold return to their previous form and original shape when they leave the target's possession or the spell ends. As long as the target did not critically succeed on their saving throw, 2d6 gp worth of gold flakes and dust are left behind as the curse recedes.","source":{"provider":"PAIZO","sourceId":"hvV6IruyW4MAr0Ub","book":"Pathfinder Lost Omens Rival Academies","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.city-of-sin","name":"City of Sin","kind":"RITUAL","rank":7,"rarity":"UNCOMMON","traits":["emotion","mental","mythic"],"traditions":[],"casting":{"time":{"kind":"LONG","text":"7 days"}},"targeting":{"range":{"kind":"NONE"},"area":null},"duration":{"text":"1 month","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":{"primaryCheck":"Diplomacy (mythic) or Society (mythic)","secondaryChecks":"Intimidation, Underworld Lore","secondaryCasters":2},"description":"Area 7-mile-radius circle centered on you\nEach day during the casting of this ritual, intelligent creatures within range become increasingly prone to shed their inhibitions and give in to whatever tempts them. Exposed communities experience increases in crime, vice, and violence (however the community defines those vices). At the ritual's culmination, chaos ensues as everyone from every walk of life chooses temptation over faithfulness to their convictions.\nCritical Success Intelligent creatures in the ritual's area might betray even their most closely held convictions, including behaviors anathema to their class or faith. They take a –4 circumstance penalty to saves against mental effects and to their and DCs.\n\nSuccess Intelligent creatures in the ritual's area become more likely to give in to temptation, indulging vices and violating all but the strongest convictions. They take a –2 circumstance penalty to saves against mental effects and to their Coerce and Request DCs.\n\nFailure Intelligent creatures in the ritual's radius behave normally but gain the general sense that something unnatural tried to manipulate their actions.\n\nCritical Failure As failure above, except communities of intelligent creatures in the ritual's area bond over any events they experienced during the ritual's casting. They commit themselves to shared principles for behavior, gaining a +2 circumstance bonus to saves against mental effects and to their Coerce and Request DCs for 1 week.","source":{"provider":"PAIZO","sourceId":"9WMEO6JEcAulgUv3","book":"Pathfinder War of Immortals","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.collective-memories","name":"Collective Memories","kind":"RITUAL","rank":7,"rarity":"UNCOMMON","traits":[],"traditions":[],"casting":{"time":{"kind":"LONG","text":"1 day"},"cost":"rare incense worth a total value of 300 gp"},"targeting":{"range":{"kind":"NONE"},"area":null},"duration":{"text":"","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":{"primaryCheck":"Occultism (master)","secondaryChecks":"Performance, Society","secondaryCasters":2},"description":"You tap into other mortals' memories, knowledge, legends, tales, and lore about a subject. The subject must be an important person, place, or thing. If the subject is present, increase the degree of success of your primary skill check by one step. If you have only vague information about the subject before attempting the ritual, decrease the degree of success of your primary skill check by one step. These modifiers cancel each other out if you have a subject present with little to no baseline information.\n\nCritical Success For 1 hour after the ritual ends, you sort through memories that are mostly coherent, emphasizing more accurate or useful information over misremembered knowledge or exaggerated tales.\n\nSuccess For 1 hour after the ritual ends, you learn useful information for further inquiry that remains generally incomplete or enigmatic. As is the nature of mortal memory and stories, you are likely to learn multiple contradictory versions.\n\nFailure You fail to learn any useful legends.\n\nCritical Failure Your mind becomes overwhelmed with the vast array of knowledge at your disposal. You can't sense or respond to anything in the present for 1 week except to perform necessities like breathing and sleeping. When you recover, however, you can retrain one of your skills into a Lore based on the knowledge of a subject you were accessing, as if you had spent 1 week retraining.","source":{"provider":"PAIZO","sourceId":"hp6Q64dl7xbdn4gQ","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.contingency","name":"Contingency","kind":"SPELL","rank":7,"rarity":"COMMON","traits":["concentrate","manipulate"],"traditions":["ARCANE"],"casting":{"time":{"kind":"LONG","text":"10 minutes"}},"targeting":{"range":{"kind":"NONE"},"area":null},"duration":{"text":"until the next time you make your daily preparations","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You prepare a spell that will trigger later. While casting contingency, you also cast another spell of 4th rank or lower with a casting time of no more than 3 actions. This companion spell must be one that can affect you. You must make any decisions for the spell when you cast contingency, such as choosing a damage type for resist energy. During the casting, choose a trigger under which the spell will be cast, using the same restrictions as for the trigger of a Ready action. Once contingency is cast, you can cause the companion spell to come into effect as a reaction with that trigger. It affects only you, even if it would affect more creatures. If you define complicated conditions, as determined by the GM, the trigger might fail. If you cast contingency again, the newer casting supersedes the older.\n\nHeightened (8th) You can choose a spell of 5th rank or lower.\n\nHeightened (9th) You can choose a spell of 6th rank or lower.\n\nHeightened (10th) You can choose a spell of 7th rank or lower.","source":{"provider":"PAIZO","sourceId":"WG91Z5TiR6oO5FOw","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.control-sand","name":"Control Sand","kind":"SPELL","rank":7,"rarity":"UNCOMMON","traits":["concentrate","earth","manipulate"],"traditions":["ARCANE","PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"NONE"},"area":{"shape":"EMANATION","feet":5}},"duration":{"text":"1 minute","sustained":true},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You whip up a small sandstorm around your body. When a creature starts its turn in the area or moves into the area, it must succeed at a Fortitude save or become dazzled for as long as it remains in the area; it is then temporarily immune to this dazzling effect for 10 minutes.\n\nChoose one of the following additional effects when you cast this spell. On subsequent rounds, you can switch to a different effect once per round as a free action triggered by sustaining the spell.\n\n- Sand Shield You create a magical shield made of sand. The sand shield provides no benefit to AC, but it does allow you to use the reaction and acts as a shield for this purpose. The sand shield has Hardness 14, 21 Hit Points, and no Broken Threshold; when the shield's HP are reduced to 0, you can't use its Shield Block reaction again until the next time you Sustain the Spell and choose the sand shield effect.\n\n- Sandblast You direct a jet of sand at a single target. One creature of your choice within 30 feet takes 8d6 slashing damage (basic Reflex save). On a critical failure, the creature is also for 1 minute.\n\n- Sandstorm The area of the spell expands to a 30-foot emanation, and any creature that starts its turn in the area or moves into the area takes 6d4 slashing damage (basic Reflex save) and must hold its breath or begin suffocating.","source":{"provider":"PAIZO","sourceId":"oahqARSgOGDRybBQ","book":"Pathfinder #155: Lord of the Black Sands","license":"OGL","remaster":false},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.corrosive-body","name":"Corrosive Body","kind":"SPELL","rank":7,"rarity":"COMMON","traits":["acid","concentrate","manipulate","polymorph"],"traditions":["ARCANE","PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"NONE"},"area":null},"duration":{"text":"1 minute","sustained":false},"defense":{"kind":"NONE"},"damage":[{"id":"ezuFcvEpWgltK1Pu","formula":"3d6","damageType":"acid","kind":"DAMAGE","applyAbilityModifier":false}],"heightening":{"kind":"MANUAL","text":"Aprimoramento com valores especificos por rank."},"counteraction":false,"ritual":null,"description":"You exhale corrosive gas, and acidic secretions coat your skin as you transform into a being of living acid. You gain acid immunity. Any creature that touches you or damages you with an unarmed melee attack or non-reach melee weapon takes 3d6 acid damage, and your unarmed attacks deal 1d4 additional acid damage. The first time each round that you deal acid damage to a creature in this way, you gain 3d6 Temporary Hit Points temporary Hit Points as your body digests the eroded material and transforms it into a protective acid. When the spell ends, any remaining temporary HP expires as well. Your acid spells deal one additional die of acid damage (of the same damage die the spell uses). You can cast as an innate spell; the splash damage affects all creatures within 15 feet instead of the normal 5 feet.\n\nHeightened (9th) Creatures touching you take 4d6 acid damage instead of 3d6, your unarmed attacks deal 2d4 additional acid damage, and you gain 5d6 Temporary Hit Points temporary Hit Points.","source":{"provider":"PAIZO","sourceId":"9aFg4EuOBVz0i3Lb","book":"Pathfinder Secrets of Magic","license":"OGL","remaster":false},"automation":{"status":"PARTIAL","reasons":["HEIGHTENING_REQUIRES_MANUAL_RESOLUTION"]}},{"id":"pf2e.spell.cosmic-form","name":"Cosmic Form","kind":"SPELL","rank":7,"rarity":"COMMON","traits":["concentrate","manipulate","polymorph"],"traditions":["DIVINE","PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"NONE"},"area":null},"duration":{"text":"1 minute","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You recreate your form entirely out of cosmic energy, transforming into a Large battle form. You must have enough space to expand into, or the spell is lost. When you cast this spell, choose to take on the powers of the moon or the sun. You have hands in this battle form and can use manipulate actions. You can Dismiss the spell.\n\nYou gain the following statistics and abilities regardless of the form that you choose:\n- AC = 21 + your level. Ignore your armor check's penalty and Speed reduction.\n- 20 temporary Hit Points.\n- Darkvision.\n- One or more attacks specific to the battle form you use. You're trained with them. Your attack modifier is +25, and you use the listed damage. The melee attacks are Strength based (for the purpose of the enfeebled condition, for example), and the ranged attacks are Dexterity based. If your unarmed attack modifier is higher, you can use it instead.\n- Athletics modifier of +25, unless your own is higher.\nYou also gain specific abilities based on the stellar body:\n- Moon Speed 30 feet, fly 50 feet\n- Melee 1 fist (agile, reach 10 feet), Damage 2d4+10 bludgeoning plus 1d6 fire\n- Ranged 1 moonbeam (range 90 feet), Damage 2d4+10 fire; this form's fire damage is silver for resistances, weaknesses, and the like\n- On a critical hit with either Strike, the target is Stupefied 2 for 1 round.\n\n- Sun Speed 30 feet, fly 50 feet\n- Melee 1 fist (agile, reach 10 feet), Damage 2d6+10 fire plus 1d6 persistent fire\n- Ranged 1 sunbeam (range 90 feet), Damage 1d6+10 fire plus 1d6 persistent fire\n- On a critical hit with either Strike, the target is for 1 round.","source":{"provider":"PAIZO","sourceId":"IHUs4qn27RrdFQ5Y","book":"Pathfinder Secrets of Magic","license":"OGL","remaster":false},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.curse-of-the-spirit-orchestra","name":"Curse of the Spirit Orchestra","kind":"SPELL","rank":7,"rarity":"UNCOMMON","traits":["concentrate","curse","manipulate","misfortune"],"traditions":["OCCULT"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":30},"target":"1 creature","area":null},"duration":{"text":"varies","sustained":false},"defense":{"kind":"SAVE","statistic":"WILL","basic":false},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You summon an , insubstantial group of extraplanar musicians who follow the target and play distracting music to hinder its actions. The music the musicians play is as inappropriate to the action as possible (for example, loud drumbeats as the target tries to or silly children's songs when the target tries to orate in a serious manner). The musicians can't be reasoned with or harmed.\n\nCritical Success The target is unaffected.\n\nSuccess Until the start of your next turn, the target must roll twice and use the worse result when it attempts a Diplomacy, Intimidation, Performance, or Stealth check. When the target rolls a critical success on any skill check, it gets a success instead. When the target rolls a failure on any skill check, it gets a critical failure instead.\n\nFailure As success, but the duration is 1 hour.\n\nCritical Failure As success, but the duration is unlimited.","source":{"provider":"PAIZO","sourceId":"1VOjUKd1pacI67RZ","book":"Pathfinder #185: A Taste of Ashes","license":"OGL","remaster":false},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.dancing-fountain","name":"Dancing Fountain","kind":"SPELL","rank":7,"rarity":"COMMON","traits":["concentrate","manipulate","water"],"traditions":["ARCANE","PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":3}},"targeting":{"range":{"kind":"NONE"},"area":{"shape":"BURST","feet":30}},"duration":{"text":"1 minute","sustained":true},"defense":{"kind":"SAVE","statistic":"REFLEX","basic":true},"damage":[{"id":"CMSE36W7SDcJjtPP","formula":"10d6","damageType":"bludgeoning","kind":"DAMAGE","applyAbilityModifier":false}],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"Area 30-foot burst centered on you\n\nTapping the ground, you create a shallow pool of water that spreads over the affected area, and majestic sprays, jets, and mists of water erupt forth in a dazzling water show. When you Cast the Spell, and the first time each round you Sustain the spell, you can command the fountain to use one of the following displays, which is accompanied by a loud burst of music. The dancing fountain is somewhat fickle in its desire for novelty, meaning it can't be commanded to use the same display on two consecutive turns.\n\n- Chasing Jets A series of vertical jets shoot up in a chase sequence, forcing one creature within the fountain to move 15 feet in a direction of your choice unless it succeeds at a Reflex save against your spell DC. The fountain can't make a creature move outside its area.\n\n- Flashing Spray Diffuse fog fills the area of the emanation. All creatures within the fountain become , and all creatures outside the fountain become concealed to creatures within it. The spray persists until the beginning of your next turn.\n\n- Power Rings The fountain blasts a series of rings of water into the air that land with a crash in a centered on a location of your choice within the fountain. The falling torrent deals 10d6[bludgeoning] damage to all creatures within the burst (basic Reflex).","source":{"provider":"PAIZO","sourceId":"smiVuoFMSgY2FTOO","book":"Pathfinder Rage of Elements","license":"OGL","remaster":true},"automation":{"status":"SUPPORTED","reasons":[]}},{"id":"pf2e.spell.darklight","name":"Darklight","kind":"SPELL","rank":7,"rarity":"UNCOMMON","traits":["concentrate","darkness","focus","manipulate","shadow"],"traditions":[],"casting":{"time":{"kind":"ACTIONS","actions":3}},"targeting":{"range":{"kind":"DISTANCE","feet":120},"area":{"shape":"BURST","feet":20}},"duration":{"text":"1 minute","sustained":false},"defense":{"kind":"SAVE","statistic":"FORTITUDE","basic":true},"damage":[{"id":"0","formula":"2d6","damageType":"bludgeoning","kind":"DAMAGE","applyAbilityModifier":false},{"id":"1","formula":"2d6","damageType":"void","kind":"DAMAGE","applyAbilityModifier":false}],"heightening":{"kind":"MANUAL","text":"Aprimoramento com valores especificos por rank."},"counteraction":false,"ritual":null,"description":"Shadows pour forth from your eyes, creating a field of darkness that prevents light from emanating within the area. Light doesn't enter the area; any non-magical light sources, such as a torches or lanterns, don't emanate any light while inside the area, even if their light radius would extend beyond the darkness. The spell similarly suppresses magical light of the spell's rank or lower.\n\nLight can't pass through, so creatures in the area can't see outside. Even creatures with darkvision (but not greater darkvision) can barely see through the darkness; any creatures seen through the darkness are to them. Creatures with greater darkvision can see through the darkness normally.\n\nCreatures who move into the field or start their turn within the field have some of the life and light sucked out of them, taking 2d6 bludgeoning damage and 2d6 void damage, with a basic Fortitude save.\n\nWhen you cast this spell, choose up to four allies in the area to spare from darklight's effects. Until the spell ends, they're immune to damage from darklight spells and can see through darklight (but not other darkness) as though they had greater darkvision.\n\nHeightened (10th) The bludgeoning and void damage both increase to 3d6.","source":{"provider":"PAIZO","sourceId":"sFwoKj0TsacsmoWj","book":"Pathfinder Secrets of Magic","license":"OGL","remaster":false},"automation":{"status":"PARTIAL","reasons":["HEIGHTENING_REQUIRES_MANUAL_RESOLUTION","MULTIPLE_DAMAGE_COMPONENTS"]}},{"id":"pf2e.spell.deitys-strike","name":"Deity's Strike","kind":"SPELL","rank":7,"rarity":"COMMON","traits":["concentrate","force","manipulate"],"traditions":["DIVINE"],"casting":{"time":{"kind":"ACTIONS","actions":2},"requirements":"You have a deity."},"targeting":{"range":{"kind":"DISTANCE","feet":500},"target":"1 creature","area":null},"duration":{"text":"","sustained":false},"defense":{"kind":"SAVE","statistic":"REFLEX","basic":true},"damage":[{"id":"0","formula":"7d12","damageType":"force","kind":"DAMAGE","applyAbilityModifier":false}],"heightening":{"kind":"MANUAL","text":"Aprimoramento com valores especificos por rank."},"counteraction":false,"ritual":null,"description":"A manifested version of your deity's favored weapon appears in the air above and attacks the target, using your spell attack roll. On a hit, the weapon deals 7d12 force damage, or double damage on a critical hit.\n\nAfter the attack, whether it succeeds or fails, divine energy bursts from the weapon in a shock wave. It emits in a {10-foot-wide, 30-foot-long line} starting from the target and continuing in a direction you choose. Choose an alignment your deity has (chaotic, evil, good, or lawful). Your target and any other creatures within the area of the spell take (ternary(gte(@item.rank,9),6,5))d6[spirit|shortLabel] damage of the chosen alignment type, with a basic Reflex save. The spell gains the trait of the alignment you choose. If your deity is true neutral, the weapon doesn't create a shock wave.\nHeightened (9th) The force damage increases by 1d12 and the alignment damage increases by 1d6.","source":{"provider":"PAIZO","sourceId":"x9RIFhquazom4p02","book":"Pathfinder Secrets of Magic","license":"OGL","remaster":false},"automation":{"status":"PARTIAL","reasons":["HEIGHTENING_REQUIRES_MANUAL_RESOLUTION"]}},{"id":"pf2e.spell.devouring-void","name":"Devouring Void","kind":"SPELL","rank":7,"rarity":"UNCOMMON","traits":["concentrate","manipulate","void"],"traditions":["ARCANE","OCCULT","DIVINE"],"casting":{"time":{"kind":"ACTIONS","actions":3}},"targeting":{"range":{"kind":"DISTANCE","feet":120},"area":{"shape":"BURST","feet":30}},"duration":{"text":"1 minute","sustained":true},"defense":{"kind":"SAVE","statistic":"FORTITUDE","basic":true},"damage":[{"id":"kCSMLZj2yQZnMN8b","formula":"7d8","damageType":"void","kind":"DAMAGE","applyAbilityModifier":false}],"heightening":{"kind":"INTERVAL","everyRanks":1,"damage":{"kCSMLZj2yQZnMN8b":"1d8"},"areaFeet":0},"counteraction":false,"ritual":null,"description":"Countless tears in space appear in the area, like hungry mouths. When the spell is cast and the first time each round it's sustained, living creatures in its area take 7d8 void damage (basic Fortitude save). A living creature using a move action to leave the area must succeed at a reflex save or their action is disrupted at the edge of the area.\nHeightened (+1) The void damage increases by 1d8.","source":{"provider":"PAIZO","sourceId":"EAuUxxnDV4v3KDAC","book":"Pathfinder Lost Omens Rival Academies","license":"ORC","remaster":true},"automation":{"status":"SUPPORTED","reasons":[]}},{"id":"pf2e.spell.divine-decree","name":"Divine Decree","kind":"SPELL","rank":7,"rarity":"COMMON","traits":["concentrate","manipulate","sanctified","spirit"],"traditions":["DIVINE"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"NONE"},"area":{"shape":"EMANATION","feet":40}},"duration":{"text":"varies","sustained":false},"defense":{"kind":"SAVE","statistic":"FORTITUDE","basic":false},"damage":[{"id":"0","formula":"7d10","damageType":"spirit","kind":"DAMAGE","applyAbilityModifier":false}],"heightening":{"kind":"INTERVAL","everyRanks":1,"damage":{"0":"1d10"},"areaFeet":0},"counteraction":false,"ritual":null,"description":"You utter a potent litany from your faith, a mandate that harms those who oppose your ideals. You deal 7d10 spirit damage to your enemies in the area; each enemy must attempt a Fortitude save.\n\nCritical Success The creature is unaffected.\n\nSuccess The creature takes half damage.\n\nFailure The creature takes full damage and is Enfeebled 2 for 1 minute.\n\nCritical Failure The creature takes double damage and is enfeebled 2 for 1 minute. If you're on your home plane and the creature is not, the creature is sent back to its home plane. A creature of 10th level or lower must also succeed at a Will save or be for 1 minute; if it critically fails, it dies (this is a death effect).\n\nHeightened (+1) The damage increases by 1d10, and the level of creatures that must attempt a second save on a critical failure increases by 2.","source":{"provider":"PAIZO","sourceId":"sX2o0HH4RjJDAZ8C","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"SUPPORTED","reasons":[]}},{"id":"pf2e.spell.divine-vessel","name":"Divine Vessel","kind":"SPELL","rank":7,"rarity":"COMMON","traits":["concentrate","manipulate","morph"],"traditions":["DIVINE"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"NONE"},"area":null},"duration":{"text":"1 minute","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You accept otherworldly energies into your body; while you are still recognizably yourself, you gain the features of one of your deity's servitors. Choose an alignment your deity has (chaotic, evil, good, or lawful). You can't cast this spell if you don't have a deity or your deity is true neutral. This spell gains the trait of the alignment you chose.\n\nIf you were Medium or smaller, you become Large, as the effects of . You must have space to expand into, or the spell is lost. You also gain the following benefits.\n\n- 40 temporary Hit Points.\n\n- A fly Speed equal to your Speed.\n\n- Weakness 10 to the alignment opposite the one you chose.\n\n- A +1 status bonus to saves against spells.\n\n- Darkvision.\n\n- Your unarmed attacks and weapons deal 1 additional damage of the chosen alignment type.\n\n- One or more unarmed melee attacks. If you chose good or lawful, your fist attacks deal 2d8 damage. If you chose chaotic, you gain a bite unarmed attack that deals 2d10 piercing damage. If you chose evil, you gain a claws unarmed attack that deals 2d8 slashing damage and has the agile and finesse traits.\n\nHeightened (9th) The temporary Hit Points increase to 60, the weakness increases to 15, and the duration increases to 10 minutes.","source":{"provider":"PAIZO","sourceId":"hiVL8qsnTJtpouw0","book":"Pathfinder Core Rulebook","license":"OGL","remaster":false},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.duplicate-foe","name":"Duplicate Foe","kind":"SPELL","rank":7,"rarity":"COMMON","traits":["concentrate","manipulate"],"traditions":["ARCANE","OCCULT"],"casting":{"time":{"kind":"ACTIONS","actions":3}},"targeting":{"range":{"kind":"DISTANCE","feet":30},"target":"1 enemy of level 15 or lower","area":null},"duration":{"text":"1 minute","sustained":true},"defense":{"kind":"SAVE","statistic":"FORTITUDE","basic":false},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You create a temporary duplicate of an enemy to fight on your behalf. The target can attempt a Fortitude save to disrupt the spell. The duplicate appears in an unoccupied space adjacent to the target and has the target's attack modifier, AC, saving throw modifiers, Perception, and skill modifiers, but it has only 70 Hit Points and lacks the target's special abilities, including immunities, resistances, and weaknesses. It has no magic items except weapon potency runes.\n\nThe duplicate gains the minion trait, and it can only Stride and Strike. Its Strikes deal the target's normal damage but don't apply added effects, since it doesn't have special abilities. The spell automatically ends if the duplicate's Hit Points drop to 0.\n\nThe duplicate attacks your enemies to the best of its abilities. You can also try to give it additional instructions; when you Sustain the spell, you can also Command a Minion as part of your action, but the GM determines whether the duplicate follows your command.\n\nThe duplicate is unstable, so each turn after it takes its actions, it loses 4d6 Hit Points. It's not a living creature, and it can never regain its lost Hit Points in any way.\n\nCritical Success You fail to create a duplicate.\n\nSuccess The duplicate deals half damage with its Strikes and the duration is reduced to a maximum of 2 rounds.\n\nFailure The duplicate works as described.\n\nHeightened (+1) The level of creature you can target increases by 2. The duplicate has 10 more HP.","source":{"provider":"PAIZO","sourceId":"73rToy0v5Ra9NvL6","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.eclipse-burst","name":"Eclipse Burst","kind":"SPELL","rank":7,"rarity":"COMMON","traits":["cold","concentrate","darkness","manipulate","void"],"traditions":["ARCANE","DIVINE","PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":500},"area":{"shape":"BURST","feet":60}},"duration":{"text":"","sustained":false},"defense":{"kind":"SAVE","statistic":"REFLEX","basic":false},"damage":[{"id":"0","formula":"8d10","damageType":"cold","kind":"DAMAGE","applyAbilityModifier":false},{"id":"v1pnjhfu6e9akqe0","formula":"8d4","damageType":"void","kind":"DAMAGE","applyAbilityModifier":false}],"heightening":{"kind":"INTERVAL","everyRanks":1,"damage":{"0":"1d10","v1pnjhfu6e9akqe0":"1d4"},"areaFeet":0},"counteraction":false,"ritual":null,"description":"A globe of freezing darkness explodes in the area, dealing 8d10 cold damage to creatures in the area, plus an additional 8d4 void damage to living creatures. Each creature in the area must attempt a Reflex save.\n\nIf the globe overlaps with an area of magical light or affects a creature affected by magical light, eclipse burst attempts to counteract the light effect.\nCritical Success The creature is unaffected.\n\nSuccess The creature takes half damage.\n\nFailure The creature takes full damage.\n\nCritical Failure The creature takes double damage and becomes by the darkness for an unlimited duration.\nHeightened (+1) The cold damage increases by 1d10 and the void damage against the living increases by 1d4.","source":{"provider":"PAIZO","sourceId":"0jadeyQIItIuRgeH","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"PARTIAL","reasons":["MULTIPLE_DAMAGE_COMPONENTS"]}},{"id":"pf2e.spell.empower-ley-line","name":"Empower Ley Line","kind":"RITUAL","rank":7,"rarity":"RARE","traits":[],"traditions":[],"casting":{"time":{"kind":"LONG","text":"1 day"},"cost":"magical foci worth a total value of 50 gp × the spell rank × the target's level"},"targeting":{"range":{"kind":"DISTANCE","feet":10},"target":"1 ley line or ley line node up to double this ritual's level","area":null},"duration":{"text":"","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":{"primaryCheck":"Arcana, Nature, Occultism, or Religion matching the ley line's tradition (legendary)","secondaryChecks":"Ley Line Lore or Occultism","secondaryCasters":6},"description":"You draw upon surrounding magical energy to empower a ley line, enhancing both its positive and negative effects.\n\nThe duration of an empowered ley line's benefits increases: when you successfully that's empowered, you gain its benefits until the end of your next turn on a success (1 minute on a critical success).\n\nYou take double the damage if you fail to Tap a Ley Line that's empowered and double the damage from the ley line's backlash effects (if any). If a backlash effect has a duration, that duration increases: a backlash effect that would ordinarily last until the end of your next turn now lasts for 1 minute, effects that last for 1 minute now last for 10 minutes, effects that last for 10 minutes now last for 1 hour, and effects that last for 1 hour now last for 1 day.\n\nCritical Success You empower the ley line until the next turning of the season.\n\nSuccess You empower the ley line for 1 week.\n\nFailure You fail to empower the ley line.\n\nCritical Failure All casters take damage and suffer the ley line's backlash as if they had critically failed to Tap the Ley Line. This damage and backlash is enhanced as if the ley line were successfully empowered, leading to increased damage and longer backlash effects.","source":{"provider":"PAIZO","sourceId":"XnpRRUVAVoY6z88H","book":"Pathfinder Secrets of Magic","license":"OGL","remaster":false},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.energy-aegis","name":"Energy Aegis","kind":"SPELL","rank":7,"rarity":"COMMON","traits":["concentrate","manipulate"],"traditions":["ARCANE","DIVINE","OCCULT","PRIMAL"],"casting":{"time":{"kind":"LONG","text":"1 minute"}},"targeting":{"range":{"kind":"TOUCH"},"target":"1 creature","area":null},"duration":{"text":"until your next daily preparations","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You protect the target with a powerful, long-lasting energy barrier. The target gains resistance 5 to acid, cold, electricity, fire, force, sonic, vitality, and void damage.\n\nHeightened (9th) The resistances increase to 10.","source":{"provider":"PAIZO","sourceId":"m2xFMNyQiUKQDRaj","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.entrancing-eyes","name":"Entrancing Eyes","kind":"SPELL","rank":7,"rarity":"UNCOMMON","traits":["concentrate","manipulate","mental","visual"],"traditions":["ARCANE"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"NONE"},"area":{"shape":"EMANATION","feet":30,"text":"30-foot emanation centered on you"}},"duration":{"text":"1 minute","sustained":true},"defense":{"kind":"SAVE","statistic":"WILL","basic":false},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"Your eyes glow with an entrancing radiance that captivates those who meet your gaze. Any creature that ends its turn within the emanation must attempt a Will save.\n\nCritical Success The target is unaffected and becomes immune to this particular casting of the spell.\n\nSuccess The target is unaffected.\n\nFailure Until the end of its next turn, the target is Stupefied 2 and .\n\nCritical Failure Until the end of its next turn, the target is Stupefied 4, Fascinated, and can't take reactions. In addition, all creatures and objects other than you are from the target.\n\nDuring any round you Sustain the Spell, you can use a single action, which has the manipulate trait, to focus your entrancing eyes on a single creature you can see within 30 feet. This creature must immediately make a Will save against the spell as if it were ending its turn in the emanation. If the creature was already Fascinated by your entrancing eyes before its save, a failed save causes it to be for 1 round. You can't use this action to focus on the same creature more than once per round.","source":{"provider":"PAIZO","sourceId":"Vw2CNwlRRKABsuZi","book":"Pathfinder #154: Siege of the Dinosaurs","license":"OGL","remaster":false},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.ethereal-jaunt","name":"Ethereal Jaunt","kind":"SPELL","rank":7,"rarity":"UNCOMMON","traits":["concentrate","manipulate","teleportation"],"traditions":["DIVINE","OCCULT"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"NONE"},"area":null},"duration":{"text":"1 minute","sustained":true},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"MANUAL","text":"Aprimoramento com valores especificos por rank."},"counteraction":false,"ritual":null,"description":"You travel to the Ethereal Plane, which overlaps the Material Plane. Material Plane creatures can't see you, and you can move through things on the Material Plane. You move at half your normal Speeds, but can move in any direction (including up and down). You can see onto the Material Plane within a radius of 60 feet; it is gray, hazy, and from you. You can't affect the Material Plane, and you can't be affected by the Material Plane except by force effects and abjurations originating there. When the spell ends, you return to the Material Plane. If you're in the air, you fall (unless you can fly), and if you're inside an object, you're pushed into the nearest open space and take 1d6 damage per 5 feet you were pushed. If you cast this spell when not on the Material Plane, it is lost.\n\nHeightened (9th) You can target up to five additional willing creatures at a range of 30 feet. The duration is up to 10 minutes.","source":{"provider":"PAIZO","sourceId":"D2nPKbIS67m9199U","book":"Pathfinder Core Rulebook","license":"OGL","remaster":false},"automation":{"status":"MANUAL","reasons":["HEIGHTENING_REQUIRES_MANUAL_RESOLUTION","NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.execute","name":"Execute","kind":"SPELL","rank":7,"rarity":"COMMON","traits":["concentrate","death","manipulate","void"],"traditions":["DIVINE","PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":30},"target":"1 creature","area":null},"duration":{"text":"","sustained":false},"defense":{"kind":"SAVE","statistic":"FORTITUDE","basic":true},"damage":[{"id":"0","formula":"70","damageType":"void","kind":"DAMAGE","applyAbilityModifier":false}],"heightening":{"kind":"INTERVAL","everyRanks":1,"damage":{"0":"10"}},"counteraction":false,"ritual":null,"description":"You point at a creature and invoke the demise of all things. The target takes 70 void damage with a basic Fortitude save. If the target is undead or otherwise has void healing, the spell loses the death and void traits and gains the vitality trait, and the target takes 70 vitality damage with a basic Fortitude save.\n\nHeightened (+1) The damage increases by 10.","source":{"provider":"PAIZO","sourceId":"Z9OrRXKgAPv6Hn5l","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"SUPPORTED","reasons":[]}},{"id":"pf2e.spell.fiery-body","name":"Fiery Body","kind":"SPELL","rank":7,"rarity":"COMMON","traits":["concentrate","fire","manipulate","polymorph"],"traditions":["ARCANE","PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"NONE"},"area":null},"duration":{"text":"1 minute","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You become living flame, giving you fire immunity, resistance 10 to precision damage, and weakness 5 to cold and to water. Any creature that touches you or damages you with an unarmed attack or non-reach melee weapon takes 3d6[fire] damage.\n\nYour unarmed attacks deal an additional 1d4 fire damage, and your fire spells deal one additional die of fire damage (of the same damage die the spell uses). You can cast as an innate spell; the casting is reduced from 2 actions to 1.\n\nIn fire form, you have a fly Speed of 40 feet and don't need to breathe.\n\nHeightened (9th) Creatures touching you take 4d6[fire] damage instead of 3d6, your unarmed attacks deal 2d4 additional fire damage, and you have a fly Speed of 60 feet.","source":{"provider":"PAIZO","sourceId":"XS7Wyh5YC0NWeWyB","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.final-fate-of-the-locust-host","name":"Final Fate of the Locust Host","kind":"SPELL","rank":7,"rarity":"RARE","traits":["concentrate","incarnate","manipulate","mythic"],"traditions":["ARCANE","DIVINE","OCCULT","PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":3}},"targeting":{"range":{"kind":"DISTANCE","feet":500},"area":null},"duration":{"text":"until the end of your next turn","sustained":false},"defense":{"kind":"NONE"},"damage":[{"id":"MpZ5f5dp1t309Kpc","formula":"5d8","damageType":"piercing","kind":"DAMAGE","applyAbilityModifier":false},{"id":"rQOvmXjYxlJ2tKPb","formula":"5d8","damageType":"poison","kind":"DAMAGE","applyAbilityModifier":false}],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You conjure the rotting corpse of Deskari, previously Lord of the Locust Hosts, to the battlefield. Deskari's corpse occupies the space of a Gargantuan creature. The corpse is riddled with vermin, including countless locusts, whose collective movement grants the corpse a Speed of 60 feet and a fly Speed of 60 feet.\n\nArrive Behold the Rotten Lord Deskari's corpse is unspeakably foul, emitting a putrid stench, and constantly twitches thanks to the movement of the millions of insects and vermin that consume it. A loud, persistent buzzing is created by the clouds of locusts surrounding it like a haze. Each living enemy creature within a must attempt a Fortitude save with the following effects.\nCritical Success The creature is unaffected.\n\nSuccess The creature is Sickened 2.\n\nFailure The creature is Sickened 3 and for the duration.\n\nCritical Failure The creature is Sickened 4, Stunned 1, and deafened for the duration.\nDepart (poison) Feast of the Locust Host The millions of insects and vermin feasting on Deskari pour out of its corpse and surge across the battlefield, consuming your enemies. This swarm deals 5d8 piercing damage and 5d8 poison damage to enemy creatures in a with a basic Reflex save. A creature that critically fails is additionally Drained 2.","source":{"provider":"PAIZO","sourceId":"bIz6QnUIxu5Z7vEH","book":"Pathfinder War of Immortals","license":"ORC","remaster":true},"automation":{"status":"PARTIAL","reasons":["MULTIPLE_DAMAGE_COMPONENTS"]}},{"id":"pf2e.spell.frigid-flurry","name":"Frigid Flurry","kind":"SPELL","rank":7,"rarity":"COMMON","traits":["cold","concentrate","manipulate","water"],"traditions":["ARCANE","PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"NONE"},"area":{"shape":"LINE","feet":120}},"duration":{"text":"","sustained":false},"defense":{"kind":"SAVE","statistic":"REFLEX","basic":true},"damage":[{"id":"0","formula":"9d6","damageType":"cold","kind":"DAMAGE","applyAbilityModifier":false},{"id":"1","formula":"9d6","damageType":"slashing","kind":"DAMAGE","applyAbilityModifier":false}],"heightening":{"kind":"INTERVAL","everyRanks":1,"damage":{"0":"1d6","1":"1d6"}},"counteraction":false,"ritual":null,"description":"Area (continued) line up to 120 feet\nYou place a palm to your lips and exhale a cold breath, whipping up a gust of wind that freezes the air's ambient moisture into a flurry of jagged shards. The flurry deals 9d6 cold damage and 9d6 slashing damage to all foes, with a basic Reflex save, but the gust flows harmlessly around your allies. The wind then picks you up and carries you to the other end of the area; though your movement within the gust can still trigger reactions, the storm of ice crystals prevents you from being affected by any effects, except for those that would counteract the spell's magic or that the GM decides would affect snow.\nHeightened (+1) The cold and slashing damage each increase by 1d6.","source":{"provider":"PAIZO","sourceId":"vFkz0gVBUT2gGnm1","book":"Pathfinder Secrets of Magic","license":"OGL","remaster":false},"automation":{"status":"PARTIAL","reasons":["MULTIPLE_DAMAGE_COMPONENTS"]}},{"id":"pf2e.spell.gathering-call","name":"Gathering Call","kind":"RITUAL","rank":7,"rarity":"RARE","traits":["teleportation"],"traditions":[],"casting":{"time":{"kind":"LONG","text":"7 days"},"cost":"rare oils and powdered minerals worth 5,000 gp"},"targeting":{"range":{"kind":"DISTANCE","feet":20},"target":"up to seven willing creatures of 14th level or lower","area":null},"duration":{"text":"1 year","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":{"primaryCheck":"Arcana or Occultism (expert, the check has the secret trait)","secondaryChecks":"Arcana or Occultism (whichever isn't used for the primary check), Society","secondaryCasters":2},"description":"You bind yourself and your allies to the specific safe location, referred to as a sanctuary, where you perform the ritual. This allows the participants to return later by simply speaking a word.\n\nSuccess You form the connection with the sanctuary. Any participant in the ritual can Dismiss the ritual. When they do, all the participants can immediately return to the sanctuary from any distance, as long as they are on the same plane as the sanctuary. Each participant arrives in the position in which they were standing during the casting of the ritual. When the word is spoken, all other participants know it, and each can choose whether or not to return to the sanctuary at that time. The ritual then immediately ends.\n\nFailure You fail to form the connection between the participants and the sanctuary and are aware that the ritual has failed.\n\nCritical Failure The ritual inadvertently forms a connection with a location on another plane. The casters are unaware of this misalignment. When the word is invoked, all ritual participants are shifted to this extraplanar location.\nHeightened (+1) The cost increases by 5,000 gp, the ritual can target one more creature, and the maximum level of creature it can target increases by 2.","source":{"provider":"PAIZO","sourceId":"nzbnTqHgNKiGZkrZ","book":"Pathfinder Player Core 2","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.hasted-assault","name":"Hasted Assault","kind":"SPELL","rank":7,"rarity":"UNCOMMON","traits":["focus","magus","manipulate"],"traditions":[],"casting":{"time":{"kind":"ACTIONS","actions":1}},"targeting":{"range":{"kind":"NONE"},"area":null},"duration":{"text":"1 minute","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You call upon your magic to speed up your attacks. You gain the condition and can use the extra action each round for only Strike actions.","source":{"provider":"PAIZO","sourceId":"3MzuRDc7ccylpW2e","book":"Pathfinder Secrets of Magic","license":"OGL","remaster":false},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.heaving-earth","name":"Heaving Earth","kind":"SPELL","rank":7,"rarity":"COMMON","traits":["concentrate","earth","manipulate"],"traditions":["ARCANE","PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":120},"target":"1 creature or object on the ground","area":null},"duration":{"text":"","sustained":false},"defense":{"kind":"SAVE","statistic":"REFLEX","basic":true},"damage":[{"id":"knLe6PF6xfJGMWzT","formula":"12d10","damageType":"bludgeoning","kind":"DAMAGE","applyAbilityModifier":false}],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You strike the ground, and unleash a wave that travels through the struck surface to the target. The effect ends as soon as it can't travel through a solid surface, such as a stone floor. Each creature in a line between you and the target is shaken by tremors and must attempt a Reflex saving throw against your spell DC. A creature that fails this save is pushed 10 feet away from you.\n\nThe wave explodes once it reaches the target, showering the target with earth and stone and dealing 12d10[bludgeoning] damage with a basic Reflex save. A target that fails its save against this explosion is also pushed back 10 feet and knocked . A creature subject to the explosion doesn't need to save against the tremors.\n\nHeightened (9th) The wave explodes on one additional target of your choice in the line to the final target.","source":{"provider":"PAIZO","sourceId":"yWySiasyPZcRoe4d","book":"Pathfinder Rage of Elements","license":"OGL","remaster":true},"automation":{"status":"SUPPORTED","reasons":[]}},{"id":"pf2e.spell.hungry-depths","name":"Hungry Depths","kind":"SPELL","rank":7,"rarity":"COMMON","traits":["concentrate","manipulate","void","water"],"traditions":["ARCANE","PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":3}},"targeting":{"range":{"kind":"DISTANCE","feet":120},"area":{"shape":"BURST","feet":5}},"duration":{"text":"1 minute","sustained":true},"defense":{"kind":"SAVE","statistic":"REFLEX","basic":true},"damage":[{"id":"YsQUZm1QLMDCC7aJ","formula":"4d8","damageType":"piercing","kind":"DAMAGE","applyAbilityModifier":false},{"id":"b6lTqa8nIkcnlb6B","formula":"4d4","damageType":"void","kind":"DAMAGE","applyAbilityModifier":false}],"heightening":{"kind":"MANUAL","text":"Aprimoramento com valores especificos por rank."},"counteraction":false,"ritual":null,"description":"A spiral of dark, corrupted water appears in the ground, plunging open a door to the depths that seems to descend for miles. Disembodied glowing eyes and gnashing teeth spin within the vortex, consuming anything that crosses their path.\n\nAll creatures in the area take 4d8 piercing damage plus 4d4 void damage (basic Reflex save). Each time you Sustain the spell, you can increase the vortex's radius by 5 feet, to a maximum of 15 feet, or you can move the vortex up to 10 feet in a straight line. Each creature the vortex moves through takes the damage with a basic Reflex save. A creature can take damage from hungry depths only once per round.\n\nIf cast underwater, hungry depths instead fills a 40-foot-tall cylinder with a 5-foot radius.\n\nHeightened (9th) The vortex deals 5d8 piercing damage and 5d4 void damage.","source":{"provider":"PAIZO","sourceId":"0EzLXIpPPH0LOKqt","book":"Pathfinder Rage of Elements","license":"OGL","remaster":true},"automation":{"status":"PARTIAL","reasons":["HEIGHTENING_REQUIRES_MANUAL_RESOLUTION","MULTIPLE_DAMAGE_COMPONENTS"]}},{"id":"pf2e.spell.indolent-haze","name":"Indolent Haze","kind":"SPELL","rank":7,"rarity":"UNCOMMON","traits":["concentrate","incapacitation","manipulate","mental","sleep"],"traditions":["ARCANE","OCCULT"],"casting":{"time":{"kind":"ACTIONS","actions":3}},"targeting":{"range":{"kind":"DISTANCE","feet":120},"area":{"shape":"BURST","feet":20}},"duration":{"text":"1 minute","sustained":false},"defense":{"kind":"SAVE","statistic":"WILL","basic":false},"damage":[{"id":"DnKLI3UNhM9r5EwP","formula":"6d4","damageType":"spirit","kind":"DAMAGE","applyAbilityModifier":false}],"heightening":{"kind":"INTERVAL","everyRanks":1,"damage":{"DnKLI3UNhM9r5EwP":"2d4"},"areaFeet":0},"counteraction":false,"ritual":null,"description":"The faint scent of poppies and a soothing calm fill the area, urging creatures to lay down and take a rest, to do nothing at all, ever again. Creatures in the area when you Cast the Spell must attempt a Will save. Creatures who end their turn in the area must also attempt the save. You can Dismiss the spell.\nCritical Success The creature is unaffected.\n\nSuccess The creature lies down to rest, becoming . If they were already prone, they instead drift off to sleep, becoming .\n\nFailure As success, except that the creature is so happy lying down that they cannot attempt to Stand or otherwise maneuver themself off of the ground on their next turn, though they can (potentially to escape the spell's area).\n\nCritical Failure The creature immediately lies down and drifts off to sleep, becoming prone and unconscious. Any creature in the area who is already unconscious when you Cast the Spell (or whose turn ends in the spell's area while they are unconscious) takes 6d4 spirit damage as their life force is drained away through their dreams. This damage does not automatically wake them.\nHeightened (+1) The spirit damage increases by 2d4.","source":{"provider":"PAIZO","sourceId":"xh6hPMDx2n4OaBU7","book":"Pathfinder Lost Omens Rival Academies","license":"ORC","remaster":true},"automation":{"status":"SUPPORTED","reasons":[]}},{"id":"pf2e.spell.inexhaustible-cynicism","name":"Inexhaustible Cynicism","kind":"SPELL","rank":7,"rarity":"COMMON","traits":["concentrate","emotion","manipulate","mental"],"traditions":["ARCANE","DIVINE","OCCULT"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":30},"target":"up to 5 creatures","area":null},"duration":{"text":"","sustained":false},"defense":{"kind":"SAVE","statistic":"WILL","basic":false},"damage":[{"id":"0","formula":"6d6","damageType":"mental","kind":"DAMAGE","applyAbilityModifier":false}],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You inflict your targets with a crushing doubt about everyone and everything around them. For the duration, each target is unwilling to receive any effects that require a willing target (in case the effect was secretly an attack), refuse to ingest anything (in case the substances have been replaced with poisons and cursed duplicates), doesn't treat anyone as an ally (in case its friends were replaced by an impostor), and doesn't believe anything it's told (in case of lies, though this doesn't mean the creature automatically believes the opposite either). It doesn't even fully trust its own ability to Recall Knowledge, as it becomes convinced it most likely remembered false information, as from a critical failure on a check to Recall Knowledge.\n\nFinally, the creature takes 6d6 mental damage at the end of each of its turns (with no save) unless it spent at least 1 action that turn Seeking or otherwise interacting with its surroundings in an attempt to disbelieve the illusions that it feels are obviously surrounding it.\n\nCritical Success The creature is unaffected.\n\nSuccess The creature is affected for 1 round.\n\nFailure The creature is affected for 1 minute.\n\nCritical Failure The creature is affected for 1 hour.","source":{"provider":"PAIZO","sourceId":"gMbrNFKz9NP3TR4s","book":"Pathfinder Secrets of Magic","license":"OGL","remaster":false},"automation":{"status":"SUPPORTED","reasons":[]}},{"id":"pf2e.spell.interplanar-teleport","name":"Interplanar Teleport","kind":"SPELL","rank":7,"rarity":"UNCOMMON","traits":["concentrate","manipulate","teleportation"],"traditions":["ARCANE","DIVINE","OCCULT","PRIMAL"],"casting":{"time":{"kind":"LONG","text":"10 minutes"}},"targeting":{"range":{"kind":"DISTANCE","feet":5},"target":"up to 8 willing creatures","area":null},"duration":{"text":"","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"Requirements You have a planar key for the destination plane, used as a locus\n\nYou and your allies traverse the barriers between planes of existence. The targets move to another plane, such as the Plane of Fire, the Netherworld, or the Outer Rifts. You must know the destination plane exists and use a magic planar key created from material from that plane as a locus for the spell. While the planar keys for most prominent planes are uncommon, just like the spell interplanar teleport, more obscure planes and demiplanes often have rare or possibly even unique planar keys.\n\nThe spell is highly imprecise, and you appear 1d20×25 miles from the last place one of the targets (of your choice) was located the last time that target traveled to the plane. If it's the first time traveling to a particular plane for all targets, you appear at a random location on the plane. Interplanar teleport doesn't provide a means of return travel, though casting interplanar teleport again allows you to return to your previous plane unless there are extenuating circumstances.","source":{"provider":"PAIZO","sourceId":"5bTt2CvYHPvaR7QQ","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.leng-sting","name":"Leng Sting","kind":"SPELL","rank":7,"rarity":"UNCOMMON","traits":["concentrate","manipulate","poison"],"traditions":["ARCANE","OCCULT"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"TOUCH"},"target":"1 creature","area":null},"duration":{"text":"","sustained":false},"defense":{"kind":"SAVE","statistic":"FORTITUDE","basic":false},"damage":[{"id":"0","formula":"2d6","damageType":"piercing","kind":"DAMAGE","applyAbilityModifier":false}],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You use the power of nightmares to magically replicate the venomous attack of the aberrant and cunning Leng spiders. You deal 2d6[piercing] damage to the touched creature and afflict it with Leng spider venom. If the target takes piercing damage, they must attempt a Fortitude save.\n\nCritical Success The target is unaffected.\n\nSuccess The target takes 2d6[poison] damage.\n\nFailure The target is afflicted with Leng Spider Venom at stage 1.\n\nCritical Failure The target is afflicted with Leng spider venom at stage 2.\n\nLeng Spider Venom (incapacitation, poison) Level 13\n\nMaximum Duration 6 rounds\n\nStage 1 2d6[poison] damage and Drained 1 (1 round)\n\nStage 2 3d6[poison] damage and Drained 2 (1 round)\n\nStage 3 4d6[poison] damage, Drained 2, and (1 round)","source":{"provider":"PAIZO","sourceId":"QVMjPfXlpnmeuWKS","book":"Pathfinder #160: Assault on Hunting Lodge Seven","license":"OGL","remaster":false},"automation":{"status":"SUPPORTED","reasons":[]}},{"id":"pf2e.spell.lifewood-cage","name":"Lifewood Cage","kind":"SPELL","rank":7,"rarity":"COMMON","traits":["concentrate","manipulate","vitality","wood"],"traditions":["ARCANE","PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":3}},"targeting":{"range":{"kind":"TEXT","text":"30 feet; 1 cube 20 feet on each side"},"area":{"shape":"CUBE","feet":20}},"duration":{"text":"1 minute","sustained":true},"defense":{"kind":"SAVE","statistic":"REFLEX","basic":false},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You create an immobile, prison of hardened wood suffused with vital energy from the Forge of Creation. The cage is a 20-foot cube made of wooden branches, each a half inch thick and a half inch apart. Each creature in the area where you create the cage must attempt a Reflex save. If such a creature fails, it becomes trapped inside the cage. If it succeeds, it's pushed outside the cage into a space of its choice. If a creature in the area is too big to fit inside the prison, the spell automatically fails.\n\nThe cage has AC 10, Hardness 20, and 40 Hit Points, and it's immune to critical hits and precision damage, though it has weakness 5 to void damage. A creature capable of passing through the space between the bars (typically a Tiny creature) can leave; all others are confined within. The vitality energy suffusing the wood prevents incorporeal undead creatures from passing through the beams. Attacks with a weapon too large to fit between the bars can't pass through the cage, and the bars provide standard cover even against attacks that can pass through the gaps. Spells and most area effects (such as dragon breath) can pass through the cage uninhibited.","source":{"provider":"PAIZO","sourceId":"HES5jvGiNZZnJycK","book":"Pathfinder Player Core 2","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["RANGE_NOT_STRUCTURED","NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.loves-sacrifice","name":"Love's Sacrifice","kind":"SPELL","rank":7,"rarity":"UNCOMMON","traits":["auditory","concentrate","emotion","mental"],"traditions":["ARCANE","DIVINE"],"casting":{"time":{"kind":"REACTION"}},"targeting":{"range":{"kind":"DISTANCE","feet":30},"target":"one creature","area":null},"duration":{"text":"","sustained":false},"defense":{"kind":"SAVE","statistic":"WILL","basic":false},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"Trigger You take damage that would reduce you to 0 Hit Points.\nYou cry out for aid, and a creature near you feels compelled to throw itself in front of the threat as the ultimate expression of their love. A target that genuinely loves the caster without magical compulsion, at their player's or the GM's discretion, fails the save.\nCritical Success The target is unaffected.\n\nSuccess The creature moves adjacent to you, moving further than its Speed if necessary as the magic compels it to exceed its limits. It takes half the damage you would have taken, while you take the rest. If you would be reduced to 0 Hit Points, you're reduced to 1 instead.\n\nFailure As success, except they take the full damage. If the damage reduces them to 0 Hit Points, they immediately die; this is a death effect.\nPFS Note: This spell can only be cast on a friendly NPC with GM approval, and on a PC with their player's approval.","source":{"provider":"PAIZO","sourceId":"flKde7BHrZnRheMl","book":"Pathfinder Lost Omens Rival Academies","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.mask-of-terror","name":"Mask of Terror","kind":"SPELL","rank":7,"rarity":"COMMON","traits":["concentrate","emotion","fear","illusion","manipulate","mental","visual"],"traditions":["ARCANE","OCCULT","PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":30},"target":"1 creature","area":null},"duration":{"text":"1 minute","sustained":false},"defense":{"kind":"SAVE","statistic":"WILL","basic":false},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"The target appears to be a gruesome and terrifying creature. The effect is unique to each observer, so a human viewing the target might see a demon with bloody fangs, but a demon observing the target might see a glowing angelic visage.\n\nWhen any creature attempts a hostile action against the target, the creature must attempt a Will save. It is then temporarily immune until the end of its next turn.\n\nSuccess The creature is unaffected.\n\nFailure The creature becomes Frightened 2 before using its action.\n\nCritical Failure The creature becomes Frightened 2, and its action fails and is wasted.\n\nHeightened (8th) You can target up to 5 creatures. If a creature uses a hostile action or reaction that affects multiple targets simultaneously, it needs to attempt only one save against mask of terror.","source":{"provider":"PAIZO","sourceId":"O6VQC1Bs4aSYDa6R","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.maze-of-locked-doors","name":"Maze of Locked Doors","kind":"SPELL","rank":7,"rarity":"UNCOMMON","traits":["concentrate","extradimensional","incapacitation","manipulate","teleportation"],"traditions":["ARCANE","OCCULT"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":120},"target":"1 creature","area":null},"duration":{"text":"","sustained":true},"defense":{"kind":"SAVE","statistic":"WILL","basic":false},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"The target of your spell is drawn into a long, twisting, extradimensional hallway blocked at 30-foot intervals with high-grade duskwood doors (Hardness 20, HP 80, BT 40, athletics to Force Open) secured with (thievery, 4 successful checks required). A creature trapped within this hallway can escape only when the spell expires, or when they successfully pass through the number of doors determined by their save, either by breaking through the doors or picking the locks (or any combination of these, if the target must pass through multiple doors to escape). Teleportation effects of 6th level or lower are automatically suppressed within the extradimensional hallway; higher-level teleportation effects require the caster to succeed at a counteract check against your spell DC or they fail.\n\nCritical Success The target is unaffected.\n\nSuccess The target is trapped for 1 round, or until it bypasses 1 door.\n\nFailure The target is trapped for 1 minute, or until it bypasses 2 doors.\n\nCritical Failure The target is trapped for 10 minutes, or until it bypasses 3 doors.","source":{"provider":"PAIZO","sourceId":"qOeBQyC1z7OScHvP","book":"Pathfinder #158: Sixty Feet Under","license":"OGL","remaster":false},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.momentary-recovery","name":"Momentary Recovery","kind":"SPELL","rank":7,"rarity":"COMMON","traits":["concentrate","manipulate","teleportation"],"traditions":["ARCANE","OCCULT"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":60},"area":null},"duration":{"text":"","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You instantly teleport yourself and any items you're wearing or holding from your current space to a clear space within range that you can see. If this teleportation would bring another creature with you—even if you're carrying it in an extradimensional container—the spell is lost. After you vanish but before you arrive, you can take up to 2 actions (or the number of actions you spent to cast momentary recovery, if it was fewer than 2 actions). You can't target any other creatures or objects with anything during these actions and any effect with a duration that you create during these actions ends immediately when you arrive. After you arrive, you are Slowed 1 until the end of your next turn.","source":{"provider":"PAIZO","sourceId":"ggtZTxeyEnDYbt6f","book":"Pathfinder Dark Archive (Remastered)","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.moonburst","name":"Moonburst","kind":"SPELL","rank":7,"rarity":"COMMON","traits":["cold","concentrate","light","manipulate","vitality"],"traditions":["DIVINE","PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":500},"area":{"shape":"BURST","feet":60}},"duration":{"text":"","sustained":false},"defense":{"kind":"SAVE","statistic":"REFLEX","basic":false},"damage":[{"id":"8if8c4kjctnupcu8","formula":"8d10","damageType":"cold","kind":"DAMAGE","applyAbilityModifier":false}],"heightening":{"kind":"INTERVAL","everyRanks":1,"damage":{"8if8c4kjctnupcu8":"1d10"},"areaFeet":0},"counteraction":true,"ritual":null,"description":"A powerful globe of chilling moonlight explodes in the area, dealing 8d10 cold damage to all creatures in the area, plus an additional (@item.rank+1)d10[vitality] damage to undead creatures.\n\nMoonburst's cold damage is silver damage for the purposes of weaknesses, resistances, and the like. Each creature and object in the area must attempt a Reflex save.\nCritical Success The creature is unaffected.\n\nSuccess The creature takes half damage.\n\nFailure The creature takes full damage.\n\nCritical Failure The creature takes full damage and becomes permanently.\n\nIf the globe overlaps with an area of magical darkness, moonburst attempts to counteract the darkness effect.\nHeightened (+1) The cold damage increases by 1d10, and the vitality damage against undead increases by 1d10.","source":{"provider":"PAIZO","sourceId":"Shiuhdb2nO6Qgk3k","book":"Pathfinder Lost Omens Divine Mysteries","license":"ORC","remaster":true},"automation":{"status":"SUPPORTED","reasons":[]}},{"id":"pf2e.spell.orb-of-twisting-fate","name":"Orb of Twisting Fate","kind":"SPELL","rank":7,"rarity":"COMMON","traits":["concentrate","manipulate","mental"],"traditions":["OCCULT"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":15},"target":"1 creature","area":null},"duration":{"text":"up to 1 minute","sustained":false},"defense":{"kind":"SAVE","statistic":"WILL","basic":false},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"The glass orb of an omen dragon erupts from your target's forehead, overwhelming their mind with alternative options.\nCritical Success The creature is unaffected.\n\nSuccess At the start of its turn, the target must decide whether to spend its first action to Stride in a random direction or to spend its first action doing nothing. The spell then ends.\n\nFailure As success, but instead of ending automatically, the target attempts a new save at the end of each of its turns, ending the effect on a success.\n\nCritical Failure As success, but instead of ending automatically, the spell lasts for the full duration.","source":{"provider":"PAIZO","sourceId":"qO4xOJ0kAvhVGDpX","book":"Pathfinder Lost Omens Draconic Codex","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.planar-displacement","name":"Planar Displacement","kind":"RITUAL","rank":7,"rarity":"UNCOMMON","traits":["teleportation"],"traditions":[],"casting":{"time":{"kind":"LONG","text":"1 day"},"cost":"rare incense, precious metals, and purified chalk worth 500 gp","requirements":"planar key for the destination plane used as a locus"},"targeting":{"range":{"kind":"DISTANCE","feet":20},"area":{"shape":"BURST","feet":20}},"duration":{"text":"","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":{"primaryCheck":"Arcana (master), Nature (master), Occultism (master), or Religion (master)","secondaryChecks":"Lore (related to the destination plane), Survival","secondaryCasters":2},"description":"You draw a ritual circle, and when the ritual is complete, you shift all creatures in the area to a different plane of existence. The skill you use for the primary check must be one that can be used to make a Recall Knowledge check about the intended destination, such as Arcana or Nature for the Plane of Fire or Occultism for the Astral Plane.\n\nA secondary caster can be located at the exact site of the destination, instead of with you at the point of origin. If a secondary caster at the destination succeeds at its check and you roll a success, the ritual is a critical success instead.\n\nCritical Success You arrive on the intended plane at the last place one of the targets (of your choice) was located the last time the target traveled to that plane. If it's the first time traveling to a particular plane for all targets, you appear at a random location on the plane. The circle remains active for 1 minute, during which time any creature the ritual transported can return to the origin point with a single action, which has the concentrate trait.\n\nSuccess As critical success, but you arrive 1d10×25 miles from your destination.\n\nFailure Your attempt is unsuccessful.\n\nCritical Failure The ritual fails, and the GM determines whether you travel to the wrong plane or are barred from planar travel for 1 week.","source":{"provider":"PAIZO","sourceId":"HmKajQS0DP23bipp","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.planar-palace","name":"Planar Palace","kind":"SPELL","rank":7,"rarity":"UNCOMMON","traits":["concentrate","extradimensional","manipulate"],"traditions":["ARCANE","OCCULT"],"casting":{"time":{"kind":"LONG","text":"1 minute"}},"targeting":{"range":{"kind":"DISTANCE","feet":30},"area":null},"duration":{"text":"until the next time you make your daily preparations","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You grow an extradimensional demiplane consisting of a spacious dwelling with a single entrance. The entrance connects to the plane where you Cast the Spell, appearing anywhere within the spell's range as a faint, shimmering, vertical rectangle 5 feet wide and 10 feet high. You designate who can enter when you Cast the Spell. Once inside, you can shut the entrance, making it . You and the creatures you designated can reopen the door at will.\n\nInside, the demiplane appears to be a mansion featuring a magnificent foyer and numerous opulent chambers. The mansion can have any floor plan you imagine as you Cast the Spell, provided it fits within a space 40 feet wide, 40 feet deep, and 30 feet tall. While the entrance to the mansion is closed, effects from outside the mansion fail to penetrate it, and vice versa, except for , which can be used to enter the mansion. You can use scrying magic and similar effects to observe the outside only if they're capable of crossing planes.\n\nA staff of up to 24 servants attends to anyone within the mansion. These are like the servant created by the spell, though they're visible, with an appearance you determine during casting. The mansion is stocked with enough food to serve a nine-course banquet to 150 people.","source":{"provider":"PAIZO","sourceId":"vPWMEyVTreMOoFnm","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.planar-seal","name":"Planar Seal","kind":"SPELL","rank":7,"rarity":"UNCOMMON","traits":["concentrate","manipulate"],"traditions":["ARCANE","DIVINE","OCCULT"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":120},"area":{"shape":"BURST","feet":60}},"duration":{"text":"until your next daily preparations","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":true,"ritual":null,"description":"You create a visible magical barrier that attempts to counteract teleportation effects and planar travel into or out of the area, including items that allow access to extradimensional spaces. Planar seal tries to counteract any attempt to summon a creature into the area but doesn't stop the creature from departing when the summoning ends.","source":{"provider":"PAIZO","sourceId":"XZE4BawIlTf88Yl9","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.pollen-pods","name":"Pollen Pods","kind":"SPELL","rank":7,"rarity":"COMMON","traits":["concentrate","manipulate","plant","wood"],"traditions":["ARCANE","PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":100},"area":null},"duration":{"text":"12 hours","sustained":false},"defense":{"kind":"SAVE","statistic":"FORTITUDE","basic":false},"damage":[{"id":"ajfWkaLEMJuneDnB","formula":"8d8","damageType":"poison","kind":"DAMAGE","applyAbilityModifier":false}],"heightening":{"kind":"INTERVAL","everyRanks":1,"damage":{"ajfWkaLEMJuneDnB":"2d8"}},"counteraction":false,"ritual":null,"description":"Area four unoccupied 5-foot squares, each of which is at least 20 feet apart\n\nYou cultivate four wooden bulbs, each filled with toxic pollen and sensitive to motion. When a creature enters a space adjacent to a bulb, or when a bulb is touched or damaged (each bulb has AC 5), the bulb blossoms and releases pollen in a . Creatures in the area take 8d8 poison damage and must attempt a Fortitude save with the following results.\n\nCritical Success The creature is unaffected.\n\nSuccess The creature takes half damage and becomes for 1 round.\n\nFailure The creature takes full damage, becomes dazzled for 1 round, and becomes Stupefied 1 for 1 minute.\n\nCritical Failure The creature takes double damage, is dazzled for 1 round, and becomes Stupefied 2 for 1 minute.\n\nHeightened (+1) The damage increases by 2d8.","source":{"provider":"PAIZO","sourceId":"2uEuYmlyx1R7zQeH","book":"Pathfinder Rage of Elements","license":"OGL","remaster":true},"automation":{"status":"SUPPORTED","reasons":[]}},{"id":"pf2e.spell.possession","name":"Possession","kind":"SPELL","rank":7,"rarity":"UNCOMMON","traits":["concentrate","incapacitation","manipulate","mental","possession"],"traditions":["OCCULT"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":30},"target":"1 living creature","area":null},"duration":{"text":"1 minute","sustained":false},"defense":{"kind":"SAVE","statistic":"WILL","basic":false},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You send your mind and soul into the target's body, attempting to take control. The target must attempt a Will save. If you want to exert less control over the target, you can choose to use the effects of any degree of success more favorable to the target.\n\nWhile you're possessing a target, your own body is and can't wake up normally. You can sense everything the possessed target does. You can Dismiss this spell. If the possessed body dies, the spell ends and you must succeed at a Fortitude save against your spell DC or be for 1 hour, or 24 hours on a critical failure. If the spell ends during an encounter, you act just before the possessed creature's initiative.\nCritical Success The target is unaffected.\n\nSuccess You possess the target but can't control it. You ride along in the body while the spell lasts.\n\nFailure You possess the target and take partial control of it. You no longer have a separate turn; instead, you might control the target. At the start of each of the target's turns, it attempts another Will save. If it fails, it's by you on that turn; if it succeeds, it chooses its own actions; and if it critically succeeds, it forces you out and the spell ends.\n\nCritical Failure You possess the target fully, and it can only watch as you manipulate it like a puppet. The target is controlled by you.\nHeightened (9th) The duration is 10 minutes, and you can physically enter the creature's body, protecting your physical body while the spell lasts.","source":{"provider":"PAIZO","sourceId":"wU6hNzK8Yfqdmc8m","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.power-word-blind","name":"Power Word Blind","kind":"SPELL","rank":7,"rarity":"UNCOMMON","traits":["auditory","concentrate","mental"],"traditions":["ARCANE"],"casting":{"time":{"kind":"ACTIONS","actions":1}},"targeting":{"range":{"kind":"DISTANCE","feet":30},"target":"1 creature","area":null},"duration":{"text":"varies","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You utter an arcane word of power that can make the target upon hearing it. Once targeted, the target is then temporarily immune for 10 minutes. The effect of the spell depends on the target's level.\n\n11th or Lower The target is Blinded permanently.\n\n12th-13th The target is Blinded for [[/r 1d4 #minutes]]{1d4 minutes}.\n\n14th or Higher The target is for 1 minute.\n\nHeightened (+1) The levels at which each outcome applies increase by 2.","source":{"provider":"PAIZO","sourceId":"Yk3t4ekEiFIoEz9c","book":"Pathfinder Core Rulebook","license":"OGL","remaster":false},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.prismatic-armor","name":"Prismatic Armor","kind":"SPELL","rank":7,"rarity":"COMMON","traits":["concentrate","light","manipulate"],"traditions":["ARCANE","OCCULT"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"TOUCH"},"target":"1 willing creature","area":null},"duration":{"text":"1 minute","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You wrap the target in armor made of multicolored light. It functions as that is all colors (granting resistance 5 to acid, electricity, fire, force, mental, poison, and sonic). An attacker that critically fails on its saving throw against the spell is rather than .\n\nHeightened (9th) The resistances increase to 10 each.","source":{"provider":"PAIZO","sourceId":"4nEY2BcV85wavKLO","book":"Pathfinder Secrets of Magic","license":"OGL","remaster":false},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.prismatic-spray","name":"Prismatic Spray","kind":"SPELL","rank":7,"rarity":"COMMON","traits":["concentrate","light","manipulate"],"traditions":["ARCANE","OCCULT"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"NONE"},"area":{"shape":"CONE","feet":30}},"duration":{"text":"","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"A spray of rainbow light beams cascades from your open hand. Each creature in the area must roll 1d8 on the table below to see which beam affects it, then attempt a saving throw of the indicated type. The table notes any additional traits that apply to each type of ray. If a creature is struck by multiple beams, it uses the same d20 result for all its saving throws. For all rays, a successful saving throw negates the effect for that creature.\nPrismatic Spray\n[[/r 1d8 #Prismatic Spray]]ColorSaveEffects (Traits)\n1RedReflex50[fire] damage (fire)\n2OrangeReflex60[acid] damage (acid)\n3YellowReflex70[electricity] damage (electricity)\n4GreenFortitude30[poison] damage and Enfeebled 1 for 1 minute (poison)\n5BlueFortitudeAffected as if by\n6IndigoWill, as the spell (mental)\n7VioletWill for 1 minute; if a critical failure, sent to another plane, as (teleportation)\n8Potent beam-Affected by two beams - roll twice, rerolling any duplicates or results of 8","source":{"provider":"PAIZO","sourceId":"d6o52BnjViNz7Gub","book":"Pathfinder Core Rulebook","license":"OGL","remaster":false},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.project-image","name":"Project Image","kind":"SPELL","rank":7,"rarity":"COMMON","traits":["concentrate","illusion","manipulate","mental"],"traditions":["ARCANE","OCCULT"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":30},"area":null},"duration":{"text":"1 minute","sustained":true},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You project an illusory image of yourself. You must stay within range of the image, and if at any point you can't see the image, the spell ends. Whenever you Cast a Spell other than one whose area is an emanation, you can cause the spell effect to originate from either yourself or the image. Because the image is an illusion, it can't benefit from spells, though visual manifestations of the spell appear. The image has the same AC and saves as you. If it is hit by an attack or fails a save, the spell ends.\n\nHeightened (+2) The maximum duration you can Sustain the spell increases to 10 minutes.","source":{"provider":"PAIZO","sourceId":"0873MWM0qKDDv81O","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.ravenous-reanimation","name":"Ravenous Reanimation","kind":"RITUAL","rank":7,"rarity":"RARE","traits":["evil"],"traditions":[],"casting":{"time":{"kind":"LONG","text":"1 day"},"cost":"valuable treasures from the target dragon's hoard worth a total value of 50,000 gp","requirements":"You must be an evil dragon"},"targeting":{"range":{"kind":"NONE"},"area":null},"duration":{"text":"","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":{"primaryCheck":"Arcana (master), Occultism (master), or Religion (master)","secondaryCasters":0},"description":"You destroy the gathered treasures with your breath weapon or other powerful magic, then invoke necromantic energies before you feed upon the charred and melted remains. As you do so, void energy courses through your flesh, automatically killing you. Each individual ravener's ravenous reanimation requires three to five unique additional components. Whether or not you return as a ravener depends on the success of the ritual.\n\nCritical Success You immediately transform into a ravener upon finishing the ritual; your soul ward starts at full Hit Points (equal to 5 × your level).\n\nSuccess You rise as a ravener 24 hours after completing the ritual, as long as your body remains relatively intact. When you rise as a ravener, your soul ward starts at 1 Hit Point.\n\nFailure You rise as a ravener husk 24 hours after completing the ritual.\n\nCritical Failure You die.","source":{"provider":"PAIZO","sourceId":"u3pdkfmy0AWICdoM","book":"Pathfinder Bestiary 2","license":"OGL","remaster":false},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.ray-of-corruption","name":"Ray of Corruption","kind":"SPELL","rank":7,"rarity":"RARE","traits":["concentrate","fungus","manipulate","poison"],"traditions":["DIVINE","PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":60},"target":"one creature or object","area":null},"duration":{"text":"","sustained":false},"defense":{"kind":"SAVE","statistic":"FORTITUDE","basic":true},"damage":[{"id":"8SyVNJyczWWZhieq","formula":"6d12","damageType":"spirit","kind":"DAMAGE","applyAbilityModifier":false},{"id":"YqImozxRine8IeIZ","formula":"6d12","damageType":"poison","kind":"DAMAGE","applyAbilityModifier":false}],"heightening":{"kind":"INTERVAL","everyRanks":1,"damage":{"8SyVNJyczWWZhieq":"1d12","YqImozxRine8IeIZ":"1d12"},"areaFeet":0},"counteraction":false,"ritual":null,"description":"You unleash a sickly gray beam of toxic spores at your target. Make a spell attack against the target. If you hit a non-magical object that's made of organic material (such as a tree, wooden house, or massive skull), it melts away into a foul-smelling sludge. A single casting can destroy no more than a 10-foot cube of matter.\n\nIf you hit a creature, it takes 6d12 poison damage and 6d12 spirit damage with a basic Fortitude save. If you critically hit, the target gets a result one degree of success worse than the outcome of its Fortitude save.\nCritical Success The target is unaffected.\n\nSuccess The target takes half damage.\n\nFailure The target takes full damage. Fungal tendrils swiftly digest the body and reduce it to sludge—the target takes 2d12[persistent,acid] damage.\n\nCritical Failure As failure, but the target takes double damage, plus 4d12[persistent,acid] damage.\nHeightened (+1) The poison damage and spirit damage each increase by 1d12.","source":{"provider":"PAIZO","sourceId":"nPxYYID5JARKouSV","book":"Pathfinder #211: The Secret of Deathstalk Tower","license":"ORC","remaster":true},"automation":{"status":"PARTIAL","reasons":["MULTIPLE_DAMAGE_COMPONENTS"]}},{"id":"pf2e.spell.recall-legacy","name":"Recall Legacy","kind":"SPELL","rank":7,"rarity":"RARE","traits":["concentrate","manipulate","mental"],"traditions":["ARCANE","OCCULT"],"casting":{"time":{"kind":"ACTIONS","actions":3}},"targeting":{"range":{"kind":"TOUCH"},"target":"1 willing creature","area":null},"duration":{"text":"Until the target's next daily preparations","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You establish a mental link with the target, focusing on a piece of knowledge important to their culture, family (by birth or choice), or home settlement. Both you and the target must be aware this knowledge exists, even if you don't know the exact details.\n\nAs your magic connects them to this legacy, the target gains a non-lineage ancestry feat from their ancestry. The feat must be of a level no higher than twice recall legacy's rank and the target must meet any prerequisites for the feat.\n\nThe target is then immune to any further castings of recall legacy until their next daily preparations.","source":{"provider":"PAIZO","sourceId":"onvFdBWAsQp0CsAy","book":"Pathfinder Lost Omens Rival Academies","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.regenerate","name":"Regenerate","kind":"SPELL","rank":7,"rarity":"COMMON","traits":["concentrate","healing","manipulate","vitality"],"traditions":["DIVINE","PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"TOUCH"},"target":"1 willing living creature","area":null},"duration":{"text":"1 minute","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"An infusion of vital energy grants a creature continuous healing. The target temporarily gains regeneration 15, which restores 15 Hit Points to it at the start of each of its turns. While it has regeneration, the target can't die from taking Hit Point damage and its condition can't increase to a value that would kill it (this stops most creatures' dying condition at dying 3), though if its value becomes 4 or higher, it stays until its wounds are treated. If the target takes acid or fire damage, its regeneration deactivates until after the end of its next turn.\n\nEach time the creature regains Hit Points from regeneration, it also regrows one damaged or ruined organ (if any). During the spell's duration, the creature can also reattach severed body parts by spending an Interact action to hold the body part to the area it was severed from.\n\nHeightened (9th) The regeneration increases to 20.","source":{"provider":"PAIZO","sourceId":"2Vkd1IxylPceUAAF","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.restore-ground","name":"Restore Ground","kind":"SPELL","rank":7,"rarity":"UNCOMMON","traits":["concentrate","earth","manipulate"],"traditions":["ARCANE","PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":120},"area":{"shape":"BURST","feet":30}},"duration":{"text":"varies","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You sense that this place yearns to throw off the shackles of civilization. You attempt to restore the area within the burst to a natural state, removing all artificial objects and buildings and encouraging the growth of plants on the ground that remains. Creatures are unaffected unless caught in a structural collapse.\n- Ground All ground within the area becomes greater difficult terrain for 1 round.\n- Objects Any unattended object of Bulk 4 or less is destroyed, regardless of Hardness, unless it's an artifact or similarly hard to destroy.\n- Plants Plants in the area become healthier and more fruitful for 1 year.\n- Structures Structures within range are shaken and may collapse, as if affected by .","source":{"provider":"PAIZO","sourceId":"ljo9CEmnCMZXqfOQ","book":"Pathfinder Lost Omens Rival Academies","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.retrocognition","name":"Retrocognition","kind":"SPELL","rank":7,"rarity":"COMMON","traits":["concentrate","manipulate"],"traditions":["ARCANE","OCCULT"],"casting":{"time":{"kind":"LONG","text":"1 minute"}},"targeting":{"range":{"kind":"NONE"},"area":null},"duration":{"text":"","sustained":true},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"Opening your mind to mental echoes, you gain impressions from past events that occurred in your current location. Retrocognition reveals psychic impressions from events that occurred over the course of the last day throughout the first minute of the duration, followed by impressions from the next day back the next minute, and so on. These echoes don't play out like a vision but instead reveal impressions of emotions and metaphors that provide cryptic clues and details of the past. If you witness a traumatic or turbulent event through an impression, the spell ends unless you succeed at a Will save with a DC of at least 30 and possibly as much as 50, depending on the severity of the event. The GM determines whether an event is traumatic and chooses the DC.\n\nHeightened (8th) You gain impressions of events that occurred over the previous year for each minute you concentrate, instead of the previous day, though the details diminish, making it harder to distinguish impressions from all but the most major events.\n\nHeightened (9th) You gain impressions of events that occurred over the previous century for each minute you concentrate, instead of the previous day, though the details diminish, making it almost impossible to distinguish impressions from all but the most major events.","source":{"provider":"PAIZO","sourceId":"rsZ5c0AUyywe5yoK","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.return-to-essence","name":"Return To Essence","kind":"SPELL","rank":7,"rarity":"RARE","traits":["concentrate","manipulate"],"traditions":["ARCANE","DIVINE","OCCULT"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":120},"target":"one magically sealed or warded doorway or chest","area":null},"duration":{"text":"","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":true,"ritual":null,"description":"You unravel the magic of a spell that affects a container, door, or lock, converting it into energy you can repurpose to power your own spells.\n\nAttempt a counteract check against the target spell or magical effect that wards or seals a doorway or chest, such as , or against a spell or effect that deals damage or delivers secondary effects when it's opened, such as . If you succeed, you recover its energy, restoring one of your expended spell slots of 3rd rank or lower.\n\nHeightened (8th) You can restore an expended spell slot of 4th rank or lower.\n\nHeightened (9th) You can restore an expended spell slot of 5th rank or lower.\n\nHeightened (10th) You can restore an expended spell slot of 6th rank or lower.","source":{"provider":"PAIZO","sourceId":"v8VnSMzaSYwkq6c7","book":"Pathfinder #173: Doorway to the Red Star","license":"OGL","remaster":false},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.reverse-gravity","name":"Reverse Gravity","kind":"SPELL","rank":7,"rarity":"UNCOMMON","traits":["concentrate","manipulate"],"traditions":["ARCANE","OCCULT"],"casting":{"time":{"kind":"ACTIONS","actions":3}},"targeting":{"range":{"kind":"DISTANCE","feet":120},"area":{"shape":"CYLINDER","feet":20}},"duration":{"text":"1 minute","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"Area (continued) 20-foot radius, 40-foot tall cylinder\nYou reverse gravity in the area. Creatures and objects that aren't secured to the ground immediately fall upward to the top of the area. A creature might be able to to arrest its fall if it falls past an appropriate surface. If a creature falls against a solid object (such as a ceiling), it takes the appropriate amount of falling damage and lands on the surface. Once an object or creature reaches the top of the area, it floats, caught between the normal and reversed gravity. The creature can move along the plane where the two forms of gravity meet. Creatures that can levitate or fly can use those abilities to mitigate the effects of reverse gravity.\n\nWhen reverse gravity ends, all creatures and objects caught in the area fall back down. Likewise, anything that moves beyond the spell's area is subjected to normal gravity again.","source":{"provider":"PAIZO","sourceId":"37ESlJzUvVbOudOT","book":"Pathfinder Core Rulebook","license":"OGL","remaster":false},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.shadow-raid","name":"Shadow Raid","kind":"SPELL","rank":7,"rarity":"COMMON","traits":["concentrate","illusion","manipulate","shadow"],"traditions":["ARCANE","OCCULT"],"casting":{"time":{"kind":"ACTIONS","actions":3}},"targeting":{"range":{"kind":"DISTANCE","feet":120},"area":{"shape":"BURST","feet":30}},"duration":{"text":"1 minute","sustained":false},"defense":{"kind":"SAVE","statistic":"REFLEX","basic":true},"damage":[{"id":"0","formula":"6d8","damageType":"bludgeoning","kind":"DAMAGE","applyAbilityModifier":false}],"heightening":{"kind":"MANUAL","text":"Aprimoramento com valores especificos por rank."},"counteraction":false,"ritual":null,"description":"You spin illusions of flying shadows throughout the area. The shadows strike and cavort, harming your foes and blocking their vision with twisting shadow. Enemies in the area when you Cast the Spell take 6d8 bludgeoning, piercing, or slashing damage, with a reflex or will save, as shadows explode into being. You choose the damage type when you Cast the Spell, and each creature chooses the type of save it attempts before it rolls the save. The shadows then persist in the area for 1 minute, dealing [[/r 3d8]] damage of the type you chose to any enemy that ends its turn in the area. All creatures are to enemies in the area, as the illusory shadows swarm over them and block light.\n\nA creature that spends an action to Seek or otherwise interact with the shadow raid can attempt a Perception check to disbelieve it. On a success, the creature halves the damage it takes from the shadows, and the shadows no longer impede its vision. These benefits last until the spell ends.\nHeightened (9th) The initial damage increases by 2d8, and the damage to a creature that ends its turn in the area increases by 1d8 ([[/r 4d8]]).","source":{"provider":"PAIZO","sourceId":"VTb0yI6P1bLkzuRr","book":"Pathfinder Secrets of Magic","license":"OGL","remaster":false},"automation":{"status":"PARTIAL","reasons":["HEIGHTENING_REQUIRES_MANUAL_RESOLUTION"]}},{"id":"pf2e.spell.shadows-web","name":"Shadow's Web","kind":"SPELL","rank":7,"rarity":"UNCOMMON","traits":["concentrate","focus","manipulate","monk"],"traditions":[],"casting":{"time":{"kind":"ACTIONS","actions":2},"requirements":"You are in clinging shadow stance."},"targeting":{"range":{"kind":"NONE"},"area":{"shape":"EMANATION","feet":30}},"duration":{"text":"","sustained":false},"defense":{"kind":"SAVE","statistic":"FORTITUDE","basic":false},"damage":[{"id":"0","formula":"14d4","damageType":"void","kind":"DAMAGE","applyAbilityModifier":false}],"heightening":{"kind":"INTERVAL","everyRanks":1,"damage":{"0":"2d4"},"areaFeet":0},"counteraction":false,"ritual":null,"description":"Grasping darkness surges from you, dealing 14d4 void damage. Each creature in the area must attempt a Fortitude save.\nCritical Success The creature is unaffected.\n\nSuccess The creature takes half damage and is Enfeebled 1 for 1 round.\n\nFailure The creature takes full damage and is Enfeebled 2 for 1 round.\n\nCritical Failure The creature takes double damage, is Stunned 1, and enfeebled 2 for 1 round, and for 1 round or until it Escapes, whichever comes first.\nHeightened (+1) The void damage increases by 2d4.","source":{"provider":"PAIZO","sourceId":"n8eEXXAtguoErW0y","book":"Pathfinder Player Core 2","license":"ORC","remaster":true},"automation":{"status":"SUPPORTED","reasons":[]}},{"id":"pf2e.spell.shock-to-the-system","name":"Shock to the System","kind":"SPELL","rank":7,"rarity":"COMMON","traits":["air","concentrate","electricity","healing","manipulate","vitality"],"traditions":["DIVINE","OCCULT","PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":30},"target":"1 living creature or 1 corpse that died within the last round","area":null},"duration":{"text":"1 minute","sustained":false},"defense":{"kind":"NONE"},"damage":[{"id":"nnCp1s4ZCp3MyqM2","formula":"8d8","damageType":"untyped","kind":"HEALING","applyAbilityModifier":false}],"heightening":{"kind":"INTERVAL","everyRanks":1,"damage":{"nnCp1s4ZCp3MyqM2":"2d8"}},"counteraction":false,"ritual":null,"description":"A dense lightning cloud descends to fill the target's space, then fires a jolt of revitalizing lightning into the target. If the target is a corpse that died within the last round, the creature comes back to life with 0 Hit Points, and any effects and conditions it had when it died, with the exception of dying, and its wounded condition increases by 1. The creature's initiative is right before yours.\n\nRegardless of whether the creature came back to life or was already alive, it regains 8d8 Hit Points, and the bolt wakes it up if it was . For the duration of the spell, the target is supercharged. It becomes and can use the extra action to Stand, Stride, Strike, or Fly (if it has a fly Speed). In addition, it can cast 5th-rank as an innate spell at will, using your spell DC.\n\nThe cloud that covered the creature remains until the end of the target's next turn. Any creature in the cloud is , and anything outside the cloud is hidden to any creature inside the cloud.\n\nHeightened (+1) The healing increases by 2d8, and the thunderstrike rank increases by 1.","source":{"provider":"PAIZO","sourceId":"M5dp7ILSCKID9fDK","book":"Pathfinder Rage of Elements","license":"OGL","remaster":true},"automation":{"status":"SUPPORTED","reasons":[]}},{"id":"pf2e.spell.soothing-ballad","name":"Soothing Ballad","kind":"SPELL","rank":7,"rarity":"UNCOMMON","traits":["bard","composition","concentrate","emotion","focus","healing","manipulate","mental"],"traditions":[],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":30},"target":"you and up to 9 allies","area":null},"duration":{"text":"","sustained":false},"defense":{"kind":"NONE"},"damage":[{"id":"0","formula":"7d8","damageType":"untyped","kind":"HEALING","applyAbilityModifier":false}],"heightening":{"kind":"INTERVAL","everyRanks":1,"damage":{"0":"1d8"}},"counteraction":true,"ritual":null,"description":"You draw upon your muse to soothe your allies. Choose one of the following three effects:\n\n- The spell attempts to counteract fear effects on the targets.\n\n- The spell attempts to counteract effects imposing paralysis on the targets.\n\n- The spell restores 7d8 Hit Points to the targets.\n\nHeightened (+1) When used to heal, soothing ballad restores 1d8 more Hit Points.","source":{"provider":"PAIZO","sourceId":"0JigNJDRwevZOyjI","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"SUPPORTED","reasons":[]}},{"id":"pf2e.spell.spell-riposte","name":"Spell Riposte","kind":"SPELL","rank":7,"rarity":"UNCOMMON","traits":["manipulate"],"traditions":["ARCANE","DIVINE","OCCULT"],"casting":{"time":{"kind":"REACTION"}},"targeting":{"range":{"kind":"NONE"},"area":null},"duration":{"text":"","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"Trigger You're the target of a spell you're aware of.\nYou attempt to counteract the triggering spell. If the spell would be counteracted, it instead continues with the caster as a target instead of you. Spell riposte can't affect spells that aren't targeted (such as area spells).","source":{"provider":"PAIZO","sourceId":"9igi8LcrNQKwljK7","book":"Pathfinder Player Core 2","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.spell-turning","name":"Spell Turning","kind":"SPELL","rank":7,"rarity":"UNCOMMON","traits":["concentrate","manipulate"],"traditions":["ARCANE"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"NONE"},"area":null},"duration":{"text":"1 hour","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":true,"ritual":null,"description":"This abjuration reflects spells cast at you back at their caster. When a spell targets you, you can spend a reaction to attempt to reflect it. This uses the rules for counteracting the spell, but if the spell is successfully counteracted, the effect is turned back on the caster. Whether or not the counteract attempt is successful, spell turning then ends. Spell turning can't affect spells that aren't targeted (such as area spells). If spell turning reflects a spell back at a caster who is also under the effect of spell turning, their spell turning can attempt to reflect their own spell back at you again; if they do so, their counteract attempt automatically succeeds.","source":{"provider":"PAIZO","sourceId":"OOELvfkTedBMlWtq","book":"Pathfinder Core Rulebook","license":"OGL","remaster":false},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.sprawling-tunnels","name":"Sprawling Tunnels","kind":"RITUAL","rank":7,"rarity":"UNCOMMON","traits":["earth"],"traditions":[],"casting":{"time":{"kind":"LONG","text":"8 hours"},"cost":"fine ink worth 50 gp"},"targeting":{"range":{"kind":"TEXT","text":"5 miles"},"area":null},"duration":{"text":"1 week","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":{"primaryCheck":"Mining Lore (expert) or Nature (expert)","secondaryChecks":"Engineering Lore, Warfare Lore","secondaryCasters":2},"description":"You spill the ink on an accurate map of the area, which transforms into a series of lines that correspond to a new network of tunnels under the earth. A momentary shift, like the aftershock of a distant earthquake, is the only aboveground sign that anything has occurred. You choose a single entrance and exit to these tunnels, which must be locations within range that are known to you, though you need not be familiar with them. For example, you could name \"the basement of the town hall\" as an exit if you knew the town hall had a basement but had never seen it with your own eyes. If either named entrance or exit doesn't exist, the ritual fails. The entrance and exit are difficult to spot, requiring a successful perception check to see; the casters automatically succeed at this check.\n\nThe tunnels avoid existing subterranean features and underground structures, unless they're designated as an entrance or an exit. The tunnels are 10 feet wide and 15 feet high, providing room for most armies, but the passageways twist and turn, making navigation difficult. A creature can lead groups through the tunnels with a successful survival check to Sense Direction. On a success, the group reaches the other end of the tunnels in 2 hours. Failure on this check means the group gets lost within the tunnels for 4 hours, after which the leader can attempt the check again. A critical failure means that the group spends 8 hours wandering through the tunnels, only to arrive where they entered; the leader can attempt the check again the next day.\n\nIf any creature is in the tunnels when the ritual's duration ends, it's harmlessly pushed to the nearest entrance or exit.\nCritical Success The map provides some indication of the layout of the tunnels. A creature with the map gains a +2 circumstance bonus to the Survival check to navigate the tunnels. Any creatures not allied with the casters take a –2 circumstance penalty to the Perception check to spot the entrance and exit.\n\nSuccess As critical success, but the bonus to the Survival check is +1, and the penalty to the Perception check is –1.\n\nFailure The ritual has no effect.\n\nCritical Failure The ground beneath your feet rebels against your attempt to control it. The casters are attacked by a pair of elite Elemental Avalanches.","source":{"provider":"PAIZO","sourceId":"rsYeiz2V2KeEfjpr","book":"Pathfinder Battlecry!","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["RANGE_NOT_STRUCTURED","NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.summon-stampede","name":"Summon Stampede","kind":"SPELL","rank":7,"rarity":"COMMON","traits":["concentrate","incarnate","manipulate"],"traditions":["PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":3}},"targeting":{"range":{"kind":"DISTANCE","feet":120},"area":null},"duration":{"text":"until the end of your next turn","sustained":false},"defense":{"kind":"SAVE","statistic":"WILL","basic":false},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You summon an unstoppable stampede of panicking beasts. Whether you conjure wild beasts or tamed cattle, the stampede is a force of nature that leaves behind nothing in its wake. The stampede occupies the space of a Gargantuan creature and has a Speed of 60 feet.\n\nArrive(emotion, fear, mental) Foreboding Tremors The sheer energy of a stampede can cause even apex predators to panic. Each creature within a must attempt a Will save with the following effects.\n\nCritical Success The creature is unaffected.\n\nSuccess The creature is Frightened 1.\n\nFailure The creature is Frightened 2.\n\nCritical Failure The creature is Frightened 3 and for 1 round.\n\nDepartFlatten the Earth The stampede Strides up to double its Speed, trampling each Large or smaller creature, hazard, and structure whose space it enters, dealing (8d8)[bludgeoning] damage (basic Reflex save). The stampede ignores and attempts to counteract all difficult terrain it enters caused by debris, overgrowth, rubble, or thick ground cover.","source":{"provider":"PAIZO","sourceId":"XWqxMJpCT95A0dZs","book":"Pathfinder Howl of the Wild","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.sunburst","name":"Sunburst","kind":"SPELL","rank":7,"rarity":"COMMON","traits":["concentrate","fire","light","manipulate","vitality"],"traditions":["DIVINE","PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":500},"area":{"shape":"BURST","feet":60}},"duration":{"text":"","sustained":false},"defense":{"kind":"SAVE","statistic":"REFLEX","basic":false},"damage":[{"id":"0","formula":"8d10","damageType":"fire","kind":"DAMAGE","applyAbilityModifier":false}],"heightening":{"kind":"INTERVAL","everyRanks":1,"damage":{"0":"1d10"},"areaFeet":0},"counteraction":true,"ritual":null,"description":"A powerful globe of searing sunlight explodes in the area, dealing 8d10 fire damage to all creatures in the area, plus an additional (@item.level+1)d10[vitality] damage to undead creatures. Each creature in the area must attempt a Reflex save.\n\nCritical Success The creature is unaffected.\n\nSuccess The creature takes half damage.\n\nFailure The creature takes full damage.\n\nCritical Failure The creature takes full damage and becomes permanently.\n\nIf the globe overlaps with an area of magical darkness, sunburst attempts to counteract the darkness effect.\n\nHeightened (+1) The fire damage increases by 1d10, and the vitality damage against undead increases by 1d10.","source":{"provider":"PAIZO","sourceId":"a3aQxCpoj1q1NQxC","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"SUPPORTED","reasons":[]}},{"id":"pf2e.spell.supreme-connection","name":"Supreme Connection","kind":"RITUAL","rank":7,"rarity":"UNCOMMON","traits":[],"traditions":[],"casting":{"time":{"kind":"LONG","text":"1 day"},"cost":"rare perfume worth 250 gp"},"targeting":{"range":{"kind":"NONE"},"area":null},"duration":{"text":"up to 10 minutes","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"INTERVAL","everyRanks":1,"damage":{}},"counteraction":false,"ritual":{"primaryCheck":"Occultism (master) or Religion (master)","secondaryChecks":"Performance","secondaryCasters":2},"description":"In a show of power, you call forth a powerful entity in front of a crowd of onlookers, forcing the entity to manifest and answer your questions. The being appears as a twisted ball of vines and branches that springs forth from a nearby patch of dirt or up from between cobblestones or bricks. The ball of vines is relatively formless, giving no indication of the being that controls it. However, when you make a request, it twists into a rough face to answer your request.\n\nYou can ask up to seven questions that could be answered with \"yes\" or \"no,\" although the entity can give you any one working answer it wants, including vague answers like \"likely\" or \"unknown.\" The entity is likely to know answers related to its nature and priorities. Depending on the entity you call, it might attempt to deceive you and likely has its own agenda. The entity can only respond when surrounded by the energy of a crowd.\n\nOnce it has answered your questions, the vines freeze in place, contorted in pain, a reminder of where the powerful creature touched this world.\n\nCritical Success The entity is in a good mood or is more honest than most. It won't attempt to deceive you, though it still might not know the answers. When it's important to provide clarity, the entity will answer your questions with up to five words, such as \"if you leave immediately\" or \"that was true once.\" The words of the entity ring with truth, and the crowd takes the statements as gospel. You gain a +4 circumstance bonus to Diplomacy checks made to influence the crowd and to any Deception checks to Lie to the crowd by directly incorporating the entity's answers.\n\nSuccess You can ask and receive your seven answers normally. The crowd is excited by the entity's words and believes them to be true. You gain a +2 circumstance bonus to Diplomacy checks made to influence the crowd and to any Deception checks to Lie to the crowd by directly incorporating the entity's answers.\n\nFailure The vines reach out in a weighted gasp before dying. The crowd is likely disappointed, especially if you made them wait, but they don't necessarily change their attitude toward you.\n\nCritical Failure The vines wrap around you in desperation, trying to squeeze out your life force to survive. You take 10d6[bludgeoning] damage and become Drained 3, and you can't reduce the drained condition for 1 week. The attitude of the most members of the crowd toward you become one step worse, though individual members of the crowd might have different reactions.","source":{"provider":"PAIZO","sourceId":"6TKGaQm4PfEMkeRd","book":"Pathfinder Dark Archive (Remastered)","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.telekinetic-bombardment","name":"Telekinetic Bombardment","kind":"SPELL","rank":7,"rarity":"COMMON","traits":["concentrate","manipulate"],"traditions":["ARCANE","OCCULT"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":500},"area":{"shape":"BURST","feet":10}},"duration":{"text":"","sustained":false},"defense":{"kind":"SAVE","statistic":"REFLEX","basic":false},"damage":[{"id":"zssli0njmyjito8c","formula":"14d6","damageType":"bludgeoning","kind":"DAMAGE","applyAbilityModifier":false}],"heightening":{"kind":"INTERVAL","everyRanks":1,"damage":{"zssli0njmyjito8c":"2d6"},"areaFeet":0},"counteraction":false,"ritual":null,"description":"You grasp a piece of the landscape—such as a tree, carriage, or piece of masonry—and lob it in your foe's direction. Your missile crashes down in either a (for most missiles) or a (for something long and tall, like a tree or a ship's mast), dealing 14d6[bludgeoning|options:area-damage] damage and turning its area into difficult terrain as it breaks into rubble. All creatures in the area must attempt a Reflex save. If the area is a line, it doesn't have to start from your square but can instead start anywhere in range, as long as the entire area remains within range.\nCritical Success The creature is unaffected.\n\nSuccess The creature takes half damage.\n\nFailure The creature takes full damage and is knocked .\n\nCritical Failure The creature takes double damage, is knocked prone, and is Stunned 1.\nHeightened (+1) The damage increases by 2d6.","source":{"provider":"PAIZO","sourceId":"uc4I1diSSX6XYzb3","book":"Pathfinder Dark Archive (Remastered)","license":"ORC","remaster":true},"automation":{"status":"SUPPORTED","reasons":[]}},{"id":"pf2e.spell.teleportation-circle","name":"Teleportation Circle","kind":"RITUAL","rank":7,"rarity":"UNCOMMON","traits":["teleportation"],"traditions":[],"casting":{"time":{"kind":"LONG","text":"1 day"},"cost":"rare incense, precious metals, and purified chalk worth 500 gp"},"targeting":{"range":{"kind":"DISTANCE","feet":20},"area":null},"duration":{"text":"1 day","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":{"primaryCheck":"Arcana or Occultism (master)","secondaryChecks":"Crafting, Survival","secondaryCasters":2},"description":"You create a 10-foot-diameter circle on the ground, which acts as a portal to a destination determined at the time of the ritual. You designate the destination of the teleportation as part of the ritual. This destination can't be changed. The destination must be a location within 1,000 miles and be on the same plane as the teleportation circle. You must be able to identify the location precisely both by its position relative to the location where you create the teleportation circle and by the destination's appearance (or other identifying features). The destination must also be a 10-foot-diameter circle that doesn't overlap with any solid structures, but it can be a place that is harmful or dangerous.\n\nA secondary caster attempting a Survival check for this ritual can be located at the destination, instead of at the point of origin. If the secondary caster succeeds at their check at the destination and you roll a success, the ritual is a critical success instead.\n\nWhile the circle is active, any creature that moves to be fully within the circle is instantly teleported to the destination. A creature that is unwilling to be teleported can attempt a Will save to resist the effect. If it remains in the circle, the creature must attempt this save again at the end of each of its turns.\n\nThe circle normally works only in one direction, though you can double the cost to make it work in both directions.\nCritical Success You create the teleportation circle, and it's extremely precise, regardless of the distance traveled. Travelers arrive exactly at the designated point.\n\nSuccess As a critical success, but the destination is off target by roughly 1 percent of the distance traveled, to a maximum of 10 miles off target.\n\nFailure The teleportation circle doesn't function.\n\nCritical Failure The teleportation circle is wildly inaccurate. It leads to a random destination roughly the same distance from the origin point, and the chances of some other unusual mishap are much greater.\nHeightened (9th) The cost is 2,000 gp, the duration is 1 month, and the destination can be anywhere on the same planet.\n\nHeightened (10th) The cost is 10,000 gp, the duration is unlimited, and the destination can be anywhere on the same planet","source":{"provider":"PAIZO","sourceId":"5ZW1w9f4gWlSIuWA","book":"Pathfinder Player Core 2","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.tempest-of-shades","name":"Tempest of Shades","kind":"SPELL","rank":7,"rarity":"COMMON","traits":["concentrate","incarnate","manipulate"],"traditions":["ARCANE","DIVINE","OCCULT"],"casting":{"time":{"kind":"ACTIONS","actions":3}},"targeting":{"range":{"kind":"DISTANCE","feet":100},"area":null},"duration":{"text":"until the end of your next turn","sustained":false},"defense":{"kind":"SAVE","statistic":"FORTITUDE","basic":false},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You channel the forces of undeath to briefly call forth an amalgam of the vengeful dead slain by your enemies and allies alike. This amalgam manifests as a large tornado of insubstantial, howling faces. It occupies the space of a Huge creature and has a Speed of 60 feet.\n\nArrive (negative) Vortex of Death Each enemy creature within a 60-foot emanation must attempt a Fortitude save with the following effects.\nCritical Success The creature is unaffected\n\nSuccess The creature is Drained 1.\n\nFailure The creature is Drained 2.\n\nCritical Failure The creature is Drained 3.\nDepart (emotion, fear, mental) Howl of Eternity The vengeful dead lets out an anguished scream. All your enemies within a 100-foot emanation must attempt will saves with the following effects.\nCritical Success The creature is unaffected.\n\nSuccess The creature is Frightened 1.\n\nFailure The creature is Frightened 3.\n\nCritical Failure The creature is frightened 3. It's also for 1 round or until it's no longer frightened, whichever comes first.","source":{"provider":"PAIZO","sourceId":"JLdbyGKhjwAAoRLs","book":"Pathfinder Secrets of Magic","license":"OGL","remaster":false},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.time-beacon","name":"Time Beacon","kind":"SPELL","rank":7,"rarity":"COMMON","traits":["manipulate"],"traditions":["ARCANE","OCCULT"],"casting":{"time":{"kind":"ACTIONS","actions":1}},"targeting":{"range":{"kind":"NONE"},"area":null},"duration":{"text":"until the end of your turn","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":true,"ritual":null,"description":"You create a beacon in time to return to it if things go wrong. You can cast time beacon only on your turn. Keep careful track of everything that happens this turn after you cast time beacon. At the end of your turn, you can choose to rewind time back to just after you cast time beacon, removing all effects of your turn since then. Curses, traps, and other harmful effects that happen during your turn might prevent you from returning to the beacon if they're powerful enough. If you were affected by any harmful effects during your turn after casting time beacon, in order to return to your beacon, time beacon attempts a counteract check against each such effect. If it fails at any of these checks, you can't return. After returning to the time beacon, the spell ends.","source":{"provider":"PAIZO","sourceId":"G56DJkxlUjFv0C4Z","book":"Pathfinder Dark Archive (Remastered)","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.true-target","name":"True Target","kind":"SPELL","rank":7,"rarity":"COMMON","traits":["concentrate","fortune","prediction"],"traditions":["ARCANE","OCCULT"],"casting":{"time":{"kind":"ACTIONS","actions":1}},"targeting":{"range":{"kind":"DISTANCE","feet":60},"target":"4 creatures","area":null},"duration":{"text":"until the start of your next turn","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You delve into the possible futures of the next few seconds to understand all the ways your foe might avoid harm, then cast out a vision of that future to those around you. Designate a creature. The first time each target makes an attack roll against that creature during true target's duration, the attacker rolls twice and uses the better result. The attacker also ignores circumstance penalties to the attack roll and any flat check required due to the designated creature being or .","source":{"provider":"PAIZO","sourceId":"AlbpWWN87yGegoAF","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.unbearable-cacophony","name":"Unbearable Cacophony","kind":"RITUAL","rank":7,"rarity":"UNCOMMON","traits":["curse","mythic"],"traditions":[],"casting":{"time":{"kind":"LONG","text":"1 day"},"cost":"valuable crystals and tuning forks worth 300 gp"},"targeting":{"range":{"kind":"TEXT","text":"1-mile radius circle centered on you"},"area":null},"duration":{"text":"3 days","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":{"primaryCheck":"Performance (mythic)","secondaryChecks":"Arcana, Nature","secondaryCasters":2},"description":"You amplify the sound of every item and creature to impossible levels. Deaf creatures and creatures immune to sonic damage remain unaffected in most cases.\nCritical Success As success, and you and the secondary casters gain sonic resistance equal to your level for the duration.\n\nSuccess Any sound produced by a creature or object (such as a cricket, a ringing anvil, or a lion's roar) deals sonic damage equal to the level of the creature or item (minimum 1) to every creature within 15 feet (basic Fortitude save with a DC equal to the ritual's casting DC). For every size category over Tiny of the item or creature making noise, this damage increases by 2. Organized groups of creatures, such as a singing quartet or a swarm of insects, count as the next size category larger for this effect. Effects that normally deal sonic damage to creatures and objects ignore half the creature or object's sonic resistance or Hardness.\n\nFailure The ritual has no effect.\n\nCritical Failure An intense sound of ringing echoes in each caster's ears, imparting a weakness to sonic damage equal to their level for 1 day.\nHeightened (+2) The increase in damage made by creatures larger than Tiny increases to 6 per size category.","source":{"provider":"PAIZO","sourceId":"XhfsRLfQjN3ed1zI","book":"Pathfinder War of Immortals","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["RANGE_NOT_STRUCTURED","NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.unblinking-flame-emblem","name":"Unblinking Flame Emblem","kind":"SPELL","rank":7,"rarity":"UNCOMMON","traits":["fire","focus"],"traditions":[],"casting":{"time":{"kind":"ACTIONS","actions":1}},"targeting":{"range":{"kind":"NONE"},"target":"1 creature","area":null},"duration":{"text":"3 rounds","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"MANUAL","text":"Aprimoramento com valores especificos por rank."},"counteraction":false,"ritual":null,"description":"Trigger Your last action was a successful Strike against an enemy\n\nYou emblazon the target with a fiery sigil that projects your sight and your flame onto them, allowing you and your allies to track their movements and making it easier to hit them. Attack rolls against the target gain a +1 status bonus, and successful Strikes against the target deal 1d6[fire] damage, and 1d10[persistent,fire] damage on a critical hit. However, you're against other enemies, as the information from the emblem distracts you. The emblem takes your full attention; if you use unblinking flame emblem again before the original duration expires, the new casting replaces the previous casting.\n\nHeightened (9th) The fire damage increases to 1d8[fire] damage, and the persistent fire damage on a critical hit increases to 1d12[persistent,fire].","source":{"provider":"PAIZO","sourceId":"KADeCawMG6WAzYHa","book":"Pathfinder Lost Omens Impossible Lands","license":"OGL","remaster":false},"automation":{"status":"MANUAL","reasons":["HEIGHTENING_REQUIRES_MANUAL_RESOLUTION","NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.unbreaking-wave-barrier","name":"Unbreaking Wave Barrier","kind":"SPELL","rank":7,"rarity":"UNCOMMON","traits":["concentrate","focus","water"],"traditions":[],"casting":{"time":{"kind":"ACTIONS","actions":1}},"targeting":{"range":{"kind":"NONE"},"area":{"shape":"EMANATION","feet":5}},"duration":{"text":"","sustained":true},"defense":{"kind":"SAVE","statistic":"FORTITUDE","basic":false},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You create a protective circle around yourself that repels your foes. You gain a +1 status bonus to AC. Any creature other than you within the area, or attempting to move into the area, must attempt a Fortitude saving throw; a creature needs to attempt the Fortitude saving throw only once each round. If a creature pushed by unbreaking wave barrier would be pushed into a solid barrier or another creature, it stops at that point and takes 2d6[bludgeoning] damage for every additional 5 feet it would've been pushed. On subsequent rounds, the first time you this Spell each round, you can increase the radius of the barrier by 5 feet.\n\nCritical Success The creature is unaffected.\n\nSuccess The creature isn't pushed, but the space within the barrier is difficult terrain for it.\n\nFailure The creature is pushed 10 feet, and the space within the barrier is difficult terrain for it.\n\nCritical Failure The creature is pushed 20 feet and knocked , and the space within the barrier is difficult terrain for it.","source":{"provider":"PAIZO","sourceId":"YtJXpiu4ijkB6nP2","book":"Pathfinder Lost Omens Impossible Lands","license":"OGL","remaster":false},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.unfettered-pack","name":"Unfettered Pack","kind":"SPELL","rank":7,"rarity":"COMMON","traits":["concentrate","manipulate"],"traditions":["PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":30},"target":"up to 10 creatures","area":null},"duration":{"text":"1 hour","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You free those who travel alongside you from environmental hindrances. Targets don't take circumstance penalties to Speed from vegetation, rubble, winds, or other properties of the environment, and they ignore difficult terrain from such environmental properties.\n\nHeightened (9th) The targets also ignore greater difficult terrain from environmental properties.","source":{"provider":"PAIZO","sourceId":"bVtkBJvGLP69qVGI","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.unfolding-wind-blitz","name":"Unfolding Wind Blitz","kind":"SPELL","rank":7,"rarity":"UNCOMMON","traits":["air","concentrate","focus"],"traditions":[],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"NONE"},"area":null},"duration":{"text":"","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You blitz forward so quickly that you soar through the air, and nothing can react to you. Fly up to twice your Speed. This movement doesn't trigger reactions. At any point along the way, you can make Strikes with an unarmed attack against up to three different targets within your reach. You increase your multiple attack penalty for these attacks only after completing all of the attacks.","source":{"provider":"PAIZO","sourceId":"Ww4cPZ3QHTSpaM1m","book":"Pathfinder Lost Omens Impossible Lands","license":"OGL","remaster":false},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.untwisting-iron-augmentation","name":"Untwisting Iron Augmentation","kind":"SPELL","rank":7,"rarity":"UNCOMMON","traits":["concentrate","earth","focus"],"traditions":[],"casting":{"time":{"kind":"ACTIONS","actions":1}},"targeting":{"range":{"kind":"NONE"},"area":null},"duration":{"text":"1 minute","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"Your unarmed attacks are treated as cold iron and silver, they gain the earth trait, and they gain a +1 status bonus to damage rolls per damage die.\n\nHeightened (9th) Your unarmed attacks are also treated as adamantine.","source":{"provider":"PAIZO","sourceId":"8eOMAIvT7S1CJSit","book":"Pathfinder Lost Omens Impossible Lands","license":"OGL","remaster":false},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.vacuum","name":"Vacuum","kind":"SPELL","rank":7,"rarity":"COMMON","traits":["air","concentrate","incapacitation","manipulate"],"traditions":["ARCANE","PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"NONE"},"area":{"shape":"EMANATION","feet":15}},"duration":{"text":"1 minute","sustained":true},"defense":{"kind":"SAVE","statistic":"FORTITUDE","basic":false},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You inhale all air in the surrounding area, stealing the breath of nearby creatures. During vacuum's duration, you take a –1 circumstance penalty against inhaled threats, such as inhaled poisons. If you cast vacuum in an environment where you can't breathe, the spell fails and you immediately begin to suffocate.\n\nCreatures in the area must attempt a Fortitude save. A creature that's holding its breath gets a result one degree of success better than it rolled, and creatures that don't need to breathe air are immune to the spell. A creature that later enters the area or ceases holding its breath must attempt a save against the effect. On subsequent rounds, the first time each round you Sustain the spell, you can force each creature in the area to save against the effect.\n\nSuccess The creature begins holding its breath.\n\nFailure The creature wheezes and gasps as its breath is stolen, becoming Stunned 1. The creature then begins holding its breath but has only half its normal number of rounds of remaining air.\n\nCritical Failure The creature has all the air sucked out from its lungs and immediately starts to suffocate.","source":{"provider":"PAIZO","sourceId":"kk7JKox6MdGAWmCH","book":"Pathfinder Rage of Elements","license":"OGL","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.vibrant-vibrato","name":"Vibrant Vibrato","kind":"SPELL","rank":7,"rarity":"RARE","traits":["auditory","aura","concentrate","manipulate","sonic"],"traditions":["DIVINE","OCCULT"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"NONE"},"area":{"shape":"EMANATION","feet":40}},"duration":{"text":"1 minute","sustained":true},"defense":{"kind":"SAVE","statistic":"WILL","basic":false},"damage":[{"id":"WzgWqijGIH6TU9Iv","formula":"5d10","damageType":"sonic","kind":"DAMAGE","applyAbilityModifier":false}],"heightening":{"kind":"INTERVAL","everyRanks":1,"damage":{"WzgWqijGIH6TU9Iv":"1d10"},"areaFeet":0},"counteraction":false,"ritual":null,"description":"Your voice trills in perfect vibrato. When casting the spell, you can make the area any radius you choose, up to 40 feet. The reverberations of your voice continue to shimmer and hang in the air as long as you Sustain the spell but can't be heard at all outside of the area. A creature must attempt a Will save if it's within the area when you Cast the Spell or as soon as it enters the area while the spell is in effect. Once a creature has attempted the save, it uses the same result for that casting of vibrant vibrato.\nCritical Success The creature is unaffected.\n\nSuccess The creature takes 5d10[persistent,sonic] damage at the end of their turn as long as they remain within the aura's area of effect.\n\nFailure As success, but if the creature leaves the area, or if you move far enough from the creature that they're no longer in the area, the creature hears a shattering sound and takes 5d10 sonic damage and is Stunned 1. The creature is then for the rest of the spell's duration.\n\nCritical Failure As failure, but the creature takes double the sonic damage and is Stunned 3.\nHeightened (+1) The damage on a failed save increases by 1d10.","source":{"provider":"PAIZO","sourceId":"tPtTKe0X1dDwoDmQ","book":"Pathfinder #205: Singer, Stalker, Skinsaw Man","license":"ORC","remaster":true},"automation":{"status":"SUPPORTED","reasons":[]}},{"id":"pf2e.spell.visions-of-danger","name":"Visions of Danger","kind":"SPELL","rank":7,"rarity":"COMMON","traits":["auditory","concentrate","illusion","manipulate","visual"],"traditions":["OCCULT"],"casting":{"time":{"kind":"ACTIONS","actions":3}},"targeting":{"range":{"kind":"DISTANCE","feet":500},"area":{"shape":"BURST","feet":30}},"duration":{"text":"1 minute","sustained":false},"defense":{"kind":"SAVE","statistic":"WILL","basic":true},"damage":[{"id":"0","formula":"8d8","damageType":"mental","kind":"DAMAGE","applyAbilityModifier":false}],"heightening":{"kind":"INTERVAL","everyRanks":1,"damage":{"0":"1d8"},"areaFeet":0},"counteraction":false,"ritual":null,"description":"An illusion of horrific creatures fills the spell's area. The creatures look like Tiny swarming monsters with a specific appearance of your choice, such as fiendish flies or animated saw blades. The burst deals 8d8 mental damage with a basic Will save to each creature that's inside the burst when it's created, enters the burst, or starts its turn inside the burst. A creature that critically succeeds at its Will save can immediately attempt to disbelieve the illusion. A creature that tries to Interact with the monsters or observes one with a action can attempt to disbelieve the illusion. Creatures that disbelieve the illusion take no damage from the illusion thereafter.\nHeightened (+1) The mental damage increases by 1d8","source":{"provider":"PAIZO","sourceId":"jBGAYmR0BkkbpJvG","book":"Pathfinder Player Core 2","license":"ORC","remaster":true},"automation":{"status":"SUPPORTED","reasons":[]}},{"id":"pf2e.spell.volcanic-eruption","name":"Volcanic Eruption","kind":"SPELL","rank":7,"rarity":"COMMON","traits":["concentrate","fire","manipulate"],"traditions":["PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":120},"area":{"shape":"CYLINDER","feet":5}},"duration":{"text":"","sustained":false},"defense":{"kind":"SAVE","statistic":"REFLEX","basic":false},"damage":[{"id":"0","formula":"14d6","damageType":"fire","kind":"DAMAGE","applyAbilityModifier":false}],"heightening":{"kind":"INTERVAL","everyRanks":1,"damage":{"0":"2d6"},"areaFeet":0},"counteraction":false,"ritual":null,"description":"Area 5-foot radius, 80-foot-tall cylinder\n\nThe ground opens up, spraying a column of lava high into the air in a vertical cylinder, dealing 14d6 fire damage to creatures in the area. The lava rapidly cools and encases creatures in the area. A creature encased in rock is Clumsy 1 and takes a –10-foot status penalty to its Speeds. All normal terrain is difficult terrain to a flying creature, and such creatures immediately descend 20 feet the moment they're encased, but they don't take damage from this fall. A creature encased in rock can attempt to against your spell DC to end the effect. Otherwise, the creature remains encased until it takes a total of 50 damage, freeing it from the rock. Additionally, creatures in the area and those within 5 feet of the lava column automatically take (@item.rank -4)d6[fire] damage from the intense heat, regardless of the results of their saving throws.\n\nCritical Success The creature is unaffected.\n\nSuccess The creature takes half damage.\n\nFailure The creature takes full damage and is encased.\n\nCritical Failure The creature takes double damage and is encased.\n\nHeightened (+1) The damage in the area increases by 2d6, and the damage from the intense heat increases by 1d6.","source":{"provider":"PAIZO","sourceId":"O7ZEqWjwdKyo2CUv","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"SUPPORTED","reasons":[]}},{"id":"pf2e.spell.warp-mind","name":"Warp Mind","kind":"SPELL","rank":7,"rarity":"COMMON","traits":["concentrate","emotion","incapacitation","manipulate","mental"],"traditions":["ARCANE","OCCULT"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":120},"target":"1 creature","area":null},"duration":{"text":"","sustained":false},"defense":{"kind":"SAVE","statistic":"WILL","basic":false},"damage":[],"heightening":{"kind":"NONE"},"counteraction":true,"ritual":null,"description":"You scramble a creature's mental faculties and sensory input. The target must attempt a Will saving throw. Regardless of the result of that save, the target is then temporarily immune for 10 minutes. Warp mind's effects happen instantly, so and other effects that counteract spells can't counteract them. However, rituals and abilities that can remove non-magical effects can still counteract the effects.\n\nCritical Success The target is unaffected.\n\nSuccess The target spends the first action on its next turn with the condition.\n\nFailure The target is Confused for 1 minute.\n\nCritical Failure The target is Confused permanently.","source":{"provider":"PAIZO","sourceId":"8kJbiBEjMWG4VUjs","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.all-is-one-one-is-all","name":"All is One, One is All","kind":"SPELL","rank":8,"rarity":"RARE","traits":["concentrate","manipulate"],"traditions":["ARCANE","PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":3}},"targeting":{"range":{"kind":"DISTANCE","feet":60},"target":"You and up to 10 willing living allies","area":null},"duration":{"text":"","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You meld the targets' matter and life force into one and then, in an instant, sift them back out into their component selves. When you separate the targets back into themselves, you can choose to switch the positions of any number of targets with the positions of other targets. Additionally, you can modulate the share of vital essence to share the burden of pain. Distribute the Hit Points of all targets however you choose, except that no target can receive fewer than 1 Hit Point or more than their maximum Hit Points.","source":{"provider":"PAIZO","sourceId":"gtWxTfMbIN5RHQw6","book":"Pathfinder Lost Omens Legends","license":"OGL","remaster":false},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.antimagic-field","name":"Antimagic Field","kind":"SPELL","rank":8,"rarity":"RARE","traits":["concentrate","manipulate"],"traditions":["ARCANE","DIVINE","OCCULT"],"casting":{"time":{"kind":"ACTIONS","actions":3}},"targeting":{"range":{"kind":"NONE"},"area":{"shape":"EMANATION","feet":10,"text":"10-foot emanation which affects you."}},"duration":{"text":"1 minute","sustained":true},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You repel all magic from the target area, preventing spells and other magic from functioning. Spells can't penetrate the area, magic items cease to function within it, and no one inside can cast spells or use magic abilities, including yourself. Likewise, spells - such as - can't affect the field itself unless they are of a higher level. Magic effects resume the moment they pass outside the field. For example, a ray fired from one side of the field could target a creature on the other side (as long as caster and target are both outside the field). A summoned creature winks out of existence but reappears if the field moves or ends. Invested magic items cease to function, but they remain invested and resume functioning when they exit the field; the ability boost from an apex item isn't suppressed within the field. Spells of a higher rank than the antimagic field overcome its effects, and can even be cast by a creature within the field.\n\nThe field disrupts only magic, so a +3 longsword still functions as a longsword. Magically created creatures (such as golems) function normally within an antimagic field.","source":{"provider":"PAIZO","sourceId":"My7FvAoLYgGDDBzy","book":"Pathfinder Core Rulebook","license":"OGL","remaster":false},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.arctic-rift","name":"Arctic Rift","kind":"SPELL","rank":8,"rarity":"COMMON","traits":["cold","concentrate","manipulate"],"traditions":["ARCANE","PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"NONE"},"area":{"shape":"LINE","feet":120}},"duration":{"text":"","sustained":false},"defense":{"kind":"SAVE","statistic":"FORTITUDE","basic":false},"damage":[{"id":"dFAvAi8vt0k4MIyH","formula":"12d8","damageType":"cold","kind":"DAMAGE","applyAbilityModifier":false}],"heightening":{"kind":"INTERVAL","everyRanks":1,"damage":{"dFAvAi8vt0k4MIyH":"1d8"},"areaFeet":0},"counteraction":false,"ritual":null,"description":"A jagged crack opens in the air, dealing 12d8 cold damage as it draws away warmth. Each creature along the rift must attempt a Fortitude save.\nCritical Success The creature is unaffected.\n\nSuccess The creature takes half damage.\n\nFailure The creature takes full damage and is Slowed 1 until the start of your next turn.\n\nCritical Failure The creature takes double damage, is by a layer of ice, and is slowed 1 as long as it's immobilized. The ice is an object with 60 Hit Points, Hardness 5, immunity to cold damage, and vulnerability 10 to fire. It has object immunities and is destroyed if the target Escapes.\nHeightened (+1) The damage increases by 1d8 and the ice's Hit Points increase by 5.","source":{"provider":"PAIZO","sourceId":"C2GYCH3TtUFqPfdX","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"SUPPORTED","reasons":[]}},{"id":"pf2e.spell.awaken-curse","name":"Awaken Curse","kind":"RITUAL","rank":8,"rarity":"UNCOMMON","traits":["mythic"],"traditions":[],"casting":{"time":{"kind":"LONG","text":"1 day"}},"targeting":{"range":{"kind":"TEXT","text":"1 mile"},"target":"1 curse","area":null},"duration":{"text":"unlimited","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":{"primaryCheck":"Arcana (mythic) or Occultism (mythic)","secondaryChecks":"Arcana, Medicine, or Occultism","secondaryCasters":2},"description":"You siphon a tiny portion of life force from each of the ritual's casters to empower a curse against disrupting effects. The difficulty of the counteract check to remove the curse changes based on the success of the ritual. Additionally, the first three times the curse is successfully counteracted, it leaps to the closest possible target within 100 feet, forcing the new target to attempt a saving throw against the curse's initial effects. Saves against the curse are attempted at the same DC as the curse when it was cast, subject to changes based on the ritual's success. If any creature successfully saves against the curse's initial effects, the curse dissipates harmlessly.\nCritical Success The first counteract attempt against the curse automatically fails. After that, the curse's counteract rank increases by 2 (to a maximum of 10).\n\nSuccess The curse's counteract rank increases by 1 (to a maximum of 10).\n\nFailure The curse's counteract rank is unchanged.\n\nCritical Failure You fail to grasp the curse's nuances and entangle yourself in its effects. The curse is lifted from the original target, and you and each secondary caster is affected by the curse with no saving throw.","source":{"provider":"PAIZO","sourceId":"6P2fzrYkaiiptxlY","book":"Pathfinder War of Immortals","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["RANGE_NOT_STRUCTURED","NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.bathe-in-blood","name":"Bathe in Blood","kind":"RITUAL","rank":8,"rarity":"RARE","traits":[],"traditions":[],"casting":{"time":{"kind":"LONG","text":"1 day"},"cost":"alchemical herbs and components worth a total of 1,000 gp × the target's level"},"targeting":{"range":{"kind":"DISTANCE","feet":20},"target":"1 living creature of a level no greater than double the bathe in blood ritual's rank","area":null},"duration":{"text":"","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":{"primaryCheck":"Occultism (expert)","secondaryChecks":"Religion, Society","secondaryCasters":2},"description":"This is an old ritual, illegal in nearly every corner of Golarion, but never quite exterminated. You bathe in the freshly spilled blood of your people, whose lives and years you steal in the process.\n\nThis ritual requires that you submerge yourself in a bath of alchemically treated blood, attended by silent servants. The blood must come from the same ancestry as your own, and must have been spilled within the last 6 hours; a spell such as gentle repose can extend this time, but using such preserved blood applies a -4 circumstance penalty to the primary and secondary checks. If you're Medium, you require 30 gallons of blood to immerse yourself, and a typical Medium creature holds about 1-1/2 gallons of blood in its body. This ritual doesn't strictly require that the blood donors be killed and drained dry, but the logistical challenges of gathering enough blood without murder are beyond all but the most well-resourced casters.\n\nEach time you enact this ritual, regardless of its success or failure, you take a penalty to the primary check for all subsequent castings. This penalty starts at -1 and increases by -1 during each casting (so if you were casting this ritual on yourself for the fifth time, you would take a -4 penalty on your Occultism check).\n\nCritical Success You emerge rejuvenated and revived. You become up to 40 years younger, returning to the prime of youth and life. If you're already at your desired age, your aging instead stops for the next 40 years. While remaining recognizably yourself, you also become preternaturally attractive, gaining a +1 circumstance bonus to Make an Impression.\n\nSuccess You become 20 years younger or pause your aging for 20 years.\n\nFailure The ritual has no effect.\n\nCritical Failure You die. Casters killed this way frequently return as undead, often as ghosts or vampires.","source":{"provider":"PAIZO","sourceId":"bRW61IbjaFea0wcv","book":"Pathfinder Secrets of Magic","license":"OGL","remaster":false},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.boil-blood","name":"Boil Blood","kind":"SPELL","rank":8,"rarity":"COMMON","traits":["concentrate","fire","manipulate"],"traditions":["ARCANE","PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":60},"target":"1 creature","area":null},"duration":{"text":"","sustained":false},"defense":{"kind":"SAVE","statistic":"FORTITUDE","basic":false},"damage":[{"id":"0","formula":"10d10","damageType":"fire","kind":"DAMAGE","applyAbilityModifier":false}],"heightening":{"kind":"INTERVAL","everyRanks":1,"damage":{"0":"1d10"}},"counteraction":false,"ritual":null,"description":"You heat a foe's blood and boil it within its veins. The target takes 10d10 fire damage, with a Fortitude save. A nonliving creature with blood in its body (such as a vampire) can be affected, but a creature with no blood is immune.\n\nCritical Success The target is unaffected.\n\nSuccess The target takes half damage.\n\nFailure The target takes full damage and is Drained 2.\n\nCritical Failure The target takes double damage and is Drained 3.\n\nHeightened (+1) The damage increases by 1d10.","source":{"provider":"PAIZO","sourceId":"fBoiPXmcIO50OFFR","book":"Pathfinder Secrets of Magic","license":"OGL","remaster":false},"automation":{"status":"SUPPORTED","reasons":[]}},{"id":"pf2e.spell.burning-blossoms","name":"Burning Blossoms","kind":"SPELL","rank":8,"rarity":"COMMON","traits":["concentrate","fire","manipulate","plant"],"traditions":["ARCANE","PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":3}},"targeting":{"range":{"kind":"DISTANCE","feet":120},"area":{"shape":"CYLINDER","feet":30}},"duration":{"text":"1 minute","sustained":false},"defense":{"kind":"NONE"},"damage":[{"id":"0","formula":"6d6","damageType":"fire","kind":"DAMAGE","applyAbilityModifier":false}],"heightening":{"kind":"INTERVAL","everyRanks":1,"damage":{"0":"1d6"},"areaFeet":0},"counteraction":false,"ritual":null,"description":"Area 30-foot radius, 100-foot tall cylinder\n\nAn intangible hollow tree sprouts from the ground and grows to towering height, radiating a fiery passion and fascinating viewers. The base of the tree takes up a single square and grows 100 feet upwards, while its branches extend outwards 30 feet, forming the spell's cylindrical area. The tree then blossoms, growing delicate white flowers that burn with white-hot fire. As the tree's branches gently rustle in the wind, flower petals drift to the ground in a shower of flame. Any creature that ends its turn under the tree's branches takes 6d6 fire damage from the burning petals. Any enemy that can see the tree, even if the enemy is outside the spell's area, must attempt a will save. This is an emotion, mental, and visual effect. Creatures fascinated with the tree must use at least one of their actions on each of their turns to move toward the tree.\n\nCritical Success The creature is unaffected and is temporarily immune for 24 hours.\n\nSuccess The creature is unaffected, but it must attempt a new save at the end of its turn if it can still see the tree.\n\nFailure The creature is with the tree until the end of its next turn. If it can still see the tree then, it must attempt a save again.\n\nCritical Failure The creature is fascinated with the tree until the spell ends. The tree's fire damage doesn't end the fascination; other hostile actions end it, as normal. If the fascination ends, the creature must attempt a new save at the end of its turn if it can still see the tree.\n\nHeightened (+1) The damage increases by 1d6","source":{"provider":"PAIZO","sourceId":"kWDt0JcKPgX6MvdD","book":"Pathfinder Secrets of Magic","license":"OGL","remaster":false},"automation":{"status":"SUPPORTED","reasons":[]}},{"id":"pf2e.spell.canticle-of-everlasting-grief","name":"Canticle of Everlasting Grief","kind":"SPELL","rank":8,"rarity":"COMMON","traits":["auditory","concentrate","curse","emotion","fear","manipulate","mental"],"traditions":["DIVINE","OCCULT"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":120},"target":"1 creature","area":null},"duration":{"text":"varies","sustained":false},"defense":{"kind":"SAVE","statistic":"WILL","basic":true},"damage":[{"id":"XBFtljOdUx24bHoA","formula":"10d6","damageType":"mental","kind":"DAMAGE","applyAbilityModifier":false}],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You create a melody distilled from pure grief, conveying the inevitable loss of everything your target cherishes, audible to only them. The target takes 10d6 mental damage depending on its Will save. A creature cursed by this spell can't benefit from circumstance or status bonuses, for the duration noted in the degree of success.\n\nCritical Success The target is unaffected.\n\nSuccess The target takes half damage, is Frightened 1, and is cursed for 1 round.\n\nFailure The target takes full damage, is Frightened 3, and is cursed for 1 week.\n\nCritical Failure The target takes double damage, is Frightened 4, and is cursed for an unlimited duration. While the curse remains, the target's allies are also affected by the curse while within 15 feet of the creature.","source":{"provider":"PAIZO","sourceId":"qlxM7Ik3uUeUIOcv","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"SUPPORTED","reasons":[]}},{"id":"pf2e.spell.clockwork-devotion","name":"Clockwork Devotion","kind":"SPELL","rank":8,"rarity":"UNCOMMON","traits":["concentrate","incarnate","manipulate"],"traditions":["ARCANE"],"casting":{"time":{"kind":"ACTIONS","actions":3}},"targeting":{"range":{"kind":"DISTANCE","feet":100},"area":null},"duration":{"text":"until the end of your next turn","sustained":false},"defense":{"kind":"SAVE","statistic":"REFLEX","basic":true},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You toss a handful of magical cogs before you, summoning a battalion of clockwork soldiers to fight your enemies. The clockwork soldiers occupy the space of a Huge creature and have a Speed of 60 feet.\n\nArrive Clockwork Assault Clockwork soldiers slash at your enemies with their halberds, dealing 4d10 slashing damage (basic Reflex save) to all enemy creatures in its location or within 15 feet.\n\nDepart (fire) Ticking Bomb The clockwork soldiers freeze abruptly before exploding into a mass of flying cogs and metal shrapnel, dealing 4d8 slashing damage and 4d8 fire damage in a 30-foot emanation (basic Reflex save). On a critical failure, a creature takes an additional 2d8[persistent,fire] damage.","source":{"provider":"PAIZO","sourceId":"zEAblSSbfu1246JL","book":"Pathfinder Battlecry!","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}}]
